#include "tig.h"

void
die(const char *err, ...)
{
	va_list args;

	endwin();

	va_start(args, err);
	fputs("tig: ", stderr);
	vfprintf(stderr, err, args);
	fputs("\n", stderr);
	va_end(args);

	exit(1);
}

void
warn(const char *msg, ...)
{
	va_list args;

	va_start(args, msg);
	fputs("tig warning: ", stderr);
	vfprintf(stderr, msg, args);
	fputs("\n", stderr);
	va_end(args);
}

void
string_ncopy_do(char *dst, size_t dstlen, const char *src, size_t srclen)
{
	if (srclen > dstlen - 1)
		srclen = dstlen - 1;

	strncpy(dst, src, srclen);
	dst[srclen] = 0;
}

bool
string_nformat(char *buf, size_t bufsize, size_t *bufpos, const char *fmt, ...)
{
	va_list args;
	size_t pos = bufpos ? *bufpos : 0;
	int retval;

	va_start(args, fmt);
	retval = vsnprintf(buf + pos, bufsize - pos, fmt, args);
	va_end(args);

	if (bufpos)
		*bufpos = retval < 0 ? pos : pos + retval;
	if (retval < 0)
		return false;
	return pos + retval < bufsize;
}

int
strcmp_null(const char *s1, const char *s2)
{
	if (!s1 || !s2)
		return (!!s1) - (!!s2);
	return strcmp(s1, s2);
}

int
strcmp_numeric(const char *s1, const char *s2)
{
	int number = 0;
	int num1, num2;

	for (; *s1 && *s2; s1++, s2++) {
		int c1 = *s1, c2 = *s2;

		if (isdigit(c1) && isdigit(c2)) {
			num1 = atoi(s1);
			num2 = atoi(s2);
			if (num1 != num2)
				return num1 - num2;
			while (isdigit(*s1) && isdigit(s1[1])) s1++;
			while (isdigit(*s2) && isdigit(s2[1])) s2++;
			continue;
		}
		if (c1 != c2)
			return c1 - c2;
	}
	return *s1 - *s2;
}

bool
string_isnumber(const char *str)
{
	int pos;

	for (pos = 0; str[pos]; pos++) {
		if (!isdigit(str[pos]))
			return false;
	}
	return pos > 0;
}

bool
iscommit(const char *str)
{
	int pos;

	for (pos = 0; str[pos]; pos++) {
		if (!isxdigit(str[pos]))
			return false;
	}
	return 7 <= pos && pos < SIZEOF_REV;
}

char *
chomp_string(char *name)
{
	int namelen;

	while (isspace(*name))
		name++;

	namelen = strlen(name) - 1;
	while (namelen > 0 && isspace(name[namelen]))
		name[namelen--] = 0;

	return name;
}

bool
suffixcmp(const char *str, int slen, const char *suffix)
{
	size_t len = slen >= 0 ? slen : strlen(str);
	size_t suffixlen = strlen(suffix);

	return suffixlen < len ? strcmp(str + len - suffixlen, suffix) : -1;
}

bool
parse_ulong(unsigned long *value, const char *str, const char **end)
{
	char *e;
	unsigned long v;

	if (!str || !*str)
		return false;
	errno = 0;
	v = strtoul(str, &e, 10);
	if (errno || e == str)
		return false;
	*value = v;
	if (end)
		*end = e;
	return true;
}

/*
 * Enumerations
 */

int
enum_equals(const char *name, size_t namelen, const char *str, size_t len)
{
	size_t i;

	if (namelen != len)
		return 0;
	for (i = 0; i < len; i++) {
		int c1 = tolower((unsigned char) name[i]);
		int c2 = tolower((unsigned char) str[i]);
		if (c1 == '_' || c1 == '.') c1 = '-';
		if (c2 == '_' || c2 == '.') c2 = '-';
		if (c1 != c2)
			return 0;
	}
	return 1;
}

char *
enum_name_copy(char *buf, size_t bufsize, const char *name)
{
	int bufpos;

	for (bufpos = 0; name[bufpos] && bufpos < bufsize - 1; bufpos++) {
		buf[bufpos] = tolower((unsigned char) name[bufpos]);
		if (buf[bufpos] == '_')
			buf[bufpos] = '-';
	}
	buf[bufpos] = 0;
	return buf;
}

const char *
enum_name(const char *name)
{
	static char buf[SIZEOF_STR];

	return enum_name_copy(buf, sizeof(buf), name);
}

bool
enum_name_prefixed(char *buf, size_t bufsize, const char *prefix, const char *name)
{
	char prefixed[SIZEOF_STR];

	if (*prefix) {
		if (!string_format(prefixed, "%s-%s", prefix, name))
			return false;
		name = prefixed;
	}
	return enum_name_copy(buf, bufsize, name) != NULL;
}

bool
map_enum_do(const struct enum_map_entry *map, size_t map_size, int *value, const char *name)
{
	size_t namelen = strlen(name);
	int i;

	for (i = 0; i < map_size; i++)
		if (enum_equals(map[i].name, map[i].namelen, name, namelen)) {
			*value = map[i].value;
			return true;
		}

	return false;
}

