int
strcmp_null(const char *s1, const char *s2)
{
	if (!s1 || !s2)
		return (!!s1) - (!!s2);
	return strcmp(s1, s2);
}

int
strcmp_numeric(const char *s1, const char *s2)
{
	int number = 0;
	int num1, num2;

	for (; *s1 && *s2; s1++, s2++) {
		int c1 = *s1, c2 = *s2;

		if (isdigit(c1) && isdigit(c2)) {
			num1 = atoi(s1);
			num2 = atoi(s2);
			if (num1 != num2)
				return num1 - num2;
			while (isdigit(*s1) && isdigit(s1[1])) s1++;
			while (isdigit(*s2) && isdigit(s2[1])) s2++;
			continue;
		}
		if (c1 != c2)
			return c1 - c2;
	}
	return *s1 - *s2;
}

