#include "tig.h"

/*
 * Requests
 */

static const struct request_info req_info[] = {
#define REQ_GROUP(help)	{ 0, NULL, 0, (help) },
#define REQ_(req, help)	{ REQ_##req, (#req), STRING_SIZE(#req), (help) }
	REQ_INFO
#undef	REQ_GROUP
#undef	REQ_
};

enum request
get_request(const char *name)
{
	int namelen = strlen(name);
	int i;

	for (i = 0; i < ARRAY_SIZE(req_info); i++)
		if (enum_equals(req_info[i].name, req_info[i].namelen, name, namelen))
			return req_info[i].request;

	return REQ_UNKNOWN;
}

const char *
get_request_name(enum request request)
{
	int i;

	for (i = 0; i < ARRAY_SIZE(req_info); i++)
		if (req_info[i].request == request)
			return enum_name(req_info[i].name);
	return "unknown";
}

bool
foreach_request(request_visitor_fn visitor, void *data)
{
	const char *group = NULL;
	int i;

	for (i = 0; i < ARRAY_SIZE(req_info); i++) {
		if (!req_info[i].request) {
			group = req_info[i].help;
			continue;
		}

		if (!visitor(data, &req_info[i], group))
			return false;
	}

	return true;
}

/*
 * Keymaps
 */

static struct keymap keymaps[] = {
	{ "generic" },
	{ "search" },
#define VIEW_KEYMAP(id, name) { #name }
	VIEW_KEYMAP(MAIN, main),
	VIEW_KEYMAP(DIFF, diff),
	VIEW_KEYMAP(LOG, log),
	{ "reflog" },
	VIEW_KEYMAP(HELP, help),
	VIEW_KEYMAP(PAGER, pager),
	VIEW_KEYMAP(STATUS, status),
	VIEW_KEYMAP(STAGE, stage),
	VIEW_KEYMAP(TREE, tree),
	VIEW_KEYMAP(BLOB, blob),
	VIEW_KEYMAP(BLAME, blame),
	VIEW_KEYMAP(REFS, refs),
	VIEW_KEYMAP(STASH, stash),
	VIEW_KEYMAP(GREP, grep),
};

static struct keymap *generic_keymap = &keymaps[0];
static struct keymap *search_keymap = &keymaps[1];

bool
keymap_is_generic(const struct keymap *keymap)
{
	return keymap == generic_keymap;
}

struct keymap *
get_keymap_by_index(int i)
{
	return 0 <= i && i < ARRAY_SIZE(keymaps) ? &keymaps[i] : NULL;
}

int
get_keymap_count(void)
{
	return ARRAY_SIZE(keymaps);
