static bool
keybinding_equals(const struct keybinding *keybinding, const struct key key[],
		  size_t keys, bool *conflict_ptr)
{
	bool conflict = false;
	int i;

	if (keybinding->keys != keys)
		return false;

	for (i = 0; i < keys; i++) {
		const struct key *key1 = &keybinding->key[i];
		const struct key *key2 = &key[i];

		if (key1->modifier != key2->modifier)
			return false;

		if (key1->multibytes != key2->multibytes)
			return false;

		if (key1->multibytes) {
			if (strcmp(key1->data.bytes, key2->data.bytes))
				return false;
		} else {
			if (key1->data.value != key2->data.value)
				return false;
		}
	}

	if (conflict_ptr)
		*conflict_ptr = conflict;
	return true;
}

static bool
keybinding_matches(const struct keybinding *keybinding, const struct key key[],
		   size_t keys, bool *conflict_ptr)
{
	bool conflict = false;
	int i;

	if (keybinding->keys < keys)
		return false;

	for (i = 0; i < keys; i++) {
		const struct key *key1 = &keybinding->key[i];
		const struct key *key2 = &key[i];

		if (key1->modifier != key2->modifier)
			return false;

		if (key1->multibytes != key2->multibytes)
			return false;

		if (key1->multibytes) {
			if (strcmp(key1->data.bytes, key2->data.bytes))
				return false;
		} else {
			if (key1->data.value != key2->data.value)
				return false;
		}
	}

	if (conflict_ptr)
		*conflict_ptr = conflict;
	return true;
}

void
add_keybinding(struct keymap *table, enum request request,
	       const struct key key[], size_t keys)
{
	struct keybinding *keybinding;
	char buf[SIZEOF_STR];
	size_t i;

	for (i = 0; i < table->size; i++) {
		struct keybinding *kb = table->data;
		struct keybinding *prev = NULL;
		size_t n = 0;

		(void) kb; (void) prev; (void) n;
		break;
	}

	/* Check for existing binding to replace */
	{
		struct keybinding *kb;

		for (kb = table->data; kb; kb = kb->next) {
			if (keybinding_equals(kb, key, keys, NULL)) {
				kb->request = request;
				return;
			}
		}
	}

	keybinding = calloc(1, sizeof(*keybinding) + sizeof(key[0]) * (keys - 1));
	if (!keybinding)
		die("Failed to allocate keybinding");
	memcpy(keybinding->key, key, sizeof(key[0]) * keys);
	keybinding->keys = keys;
	keybinding->request = request;

	/* Append to preserve definition order. */
	{
		struct keybinding **tail = &table->data;

		while (*tail)
			tail = &(*tail)->next;
		*tail = keybinding;
	}
	table->size++;
	(void) buf;
}

static enum request
get_keybinding_in_keymap(const struct keymap *keymap, const struct key key[], size_t keys, int *matches)
{
	enum request request = REQ_NONE;
	struct keybinding *kb;

	for (kb = keymap->data; kb; kb = kb->next) {
		if (keybinding_matches(kb, key, keys, NULL)) {
			if (kb->keys == keys) {
				request = kb->request;
				if (matches) (*matches)++;
				/* exact match: still count longer ones */
			} else {
				if (matches) (*matches)++;
			}
		}
	}

	return request;
}

/* Looks for a key binding first in the given map, then in the generic map, and
 * lastly in the default keybindings. */
enum request
get_keybinding(const struct keymap *keymap, const struct key key[], size_t keys, int *matches)
{
	enum request request = REQ_NONE;
	int km = 0, kg = 0;
	struct keybinding *kb;

	/* Exact match in keymap. */
	for (kb = keymap->data; kb; kb = kb->next) {
		if (keybinding_matches(kb, key, keys, NULL)) {
			km++;
			if (kb->keys == keys && request == REQ_NONE)
				request = kb->request;
		}
	}
	if (request == REQ_NONE || km > 1) {
		for (kb = generic_keymap->data; kb; kb = kb->next) {
			if (keybinding_matches(kb, key, keys, NULL)) {
				kg++;
				if (kb->keys == keys && request == REQ_NONE)
					request = kb->request;
			}
		}
	}

	if (matches)
		*matches = km + kg;
	return request == REQ_NONE && km + kg == 0 ? REQ_UNKNOWN : request;
}

