static const struct key_mapping *
get_key_mapping(const char *name, size_t namelen)
{
	int i;

	for (i = 0; i < ARRAY_SIZE(key_mappings); i++) {
		if (namelen == strlen(key_mappings[i].name) &&
		    !strncasecmp(key_mappings[i].name, name, namelen))
			return &key_mappings[i];
	}

	return NULL;
}

static int
parse_key_value(struct key *key, const char **name_ptr, size_t offset,
		const char *replacement, const char *end)
{
	const char *name = replacement ? replacement : *name_ptr + offset;
	size_t namelen = utf8_char_length(name);

	if (end && name + namelen != end)
		return -1;

	key->data.value = 0;
	key->modifier = KEY_MOD_NONE;
	key->multibytes = false;
	if (namelen == 1) {
		key->data.value = *name;
		if (!replacement)
			*name_ptr = name + namelen;
	} else {
		if (namelen > sizeof(key->data.bytes) - 1)
			return -1;
		strncpy(key->data.bytes, name, namelen);
		key->data.bytes[namelen] = 0;
		key->multibytes = true;
		if (!replacement)
			*name_ptr = name + namelen;
	}
	if (replacement)
		*name_ptr = end ? end + 1 : *name_ptr + offset + strlen(replacement);

	return 0;
}

int
get_key_value(const char **name_ptr, struct key *key)
{
	const char *name = *name_ptr;
	const char *end = NULL;

	memset(key, 0, sizeof(*key));

	if (*name == '<') {
		end = strchr(name + 1, '>');
		if (!end)
			return -1;

		if (!strncasecmp(name + 1, "Ctrl-", 5)) {
			char ctrl = *(name + 6);

			if (name + 7 != end)
				return -1;
			if (!isalpha((unsigned char) ctrl) && ctrl != '@' && !strchr("[\\]^_", ctrl))
				return -1;
			key->modifier = KEY_MOD_CTRL;
			key->data.value = toupper((unsigned char) ctrl);
			*name_ptr = end + 1;
			return 0;

		} else if (!strncasecmp(name + 1, "Esc", 3) && end - name > 4 && *end == '>' && end[1]) {
			/* <Esc>key combo. */
			const struct key_mapping *mapping = get_key_mapping(name + 1, end - name - 1);

			if (mapping && mapping->value == KEY_ESC) {
				const char *rest = end + 1;

				if (*rest == '<')
					return -1;
				key->modifier = KEY_MOD_ESC;
				{
					size_t len = utf8_char_length(rest);
					if (len == 1) {
						key->data.value = *rest;
					} else {
						if (len > sizeof(key->data.bytes) - 1)
							return -1;
						strncpy(key->data.bytes, rest, len);
						key->data.bytes[len] = 0;
						key->multibytes = true;
					}
					*name_ptr = rest + len;
				}
				return 0;
			}
			/* fall through to normal mapping */
		}

		{
			const struct key_mapping *mapping = get_key_mapping(name + 1, end - name - 1);

			if (!mapping)
				return -1;
			key->modifier = KEY_MOD_NONE;
			key->data.value = mapping->value;
			*name_ptr = end + 1;
			return 0;
		}
	}

	{
		size_t len = utf8_char_length(name);

		if (len == 1) {
			key->data.value = *name;
		} else {
			if (len > sizeof(key->data.bytes) - 1)
				return -1;
			strncpy(key->data.bytes, name, len);
			key->data.bytes[len] = 0;
			key->multibytes = true;
		}
		*name_ptr = name + len;
	}

	return 0;
}

const char *
get_key_name(const struct key key[], size_t keys, bool quote_comma)
{
	static char buf[SIZEOF_STR];
	size_t pos = 0;
	int i;

	for (i = 0; i < keys; i++) {
		const struct key *k = &key[i];
		const char *modifier = "";
		const char *name = NULL;
		int value = k->data.value;
		char tmp[8];

		if (k->modifier == KEY_MOD_ESC)
			modifier = "<Esc>";

		if (k->modifier == KEY_MOD_CTRL) {
			if (!string_format_from(buf, &pos, "<Ctrl-%c>", toupper(value)))
				return "(no key)";
			continue;
		}

		if (k->multibytes) {
			if (!string_format_from(buf, &pos, "%s%s", modifier, k->data.bytes))
				return "(no key)";
			continue;
		}

		{
			int j;

			for (j = 0; j < ARRAY_SIZE(key_mappings); j++) {
				if (key_mappings[j].value == value) {
					name = key_mappings[j].name;
					break;
				}
			}
		}

		if (name) {
			if (!string_format_from(buf, &pos, "%s<%s>", modifier, name))
				return "(no key)";
		} else if (value == ',' && quote_comma) {
			if (!string_format_from(buf, &pos, "%s','", modifier))
				return "(no key)";
		} else if (value >= 0 && value < 32 && value != KEY_TAB && value != KEY_RETURN && value != KEY_ESC) {
			if (!string_format_from(buf, &pos, "%s<Ctrl-%c>", modifier, value + 'A' - 1))
				return "(no key)";
		} else {
			tmp[0] = value;
			tmp[1] = 0;
			if (!string_format_from(buf, &pos, "%s%s", modifier, tmp))
				return "(no key)";
		}
	}

	return buf;
}

static bool
append_key(char *buf, size_t *pos, const struct keybinding *keybinding, bool all)
{
	const char *sep = *pos > 0 ? ", " : "";
	const char *keyname = get_key_name(keybinding->key, keybinding->keys, true);

	return string_nformat(buf, SIZEOF_STR, pos, "%s%s", sep, keyname);
}

static bool
append_keymap_request_keys(char *buf, size_t *pos, enum request request,
			   const struct keymap *keymap, bool all)
{
	struct keybinding *kb;

	for (kb = keymap->data; kb; kb = kb->next) {
		if (kb->request == request) {
			if (!append_key(buf, pos, kb, all))
				return false;
			if (!all)
				break;
		}
	}

	return true;
}

const char *
get_keys(const struct keymap *keymap, enum request request, bool all)
{
	static char buf[SIZEOF_STR];
	size_t pos = 0;

	buf[pos] = 0;

	if (!append_keymap_request_keys(buf, &pos, request, keymap, all))
		return "Too many keybindings!";
	if (pos > 0 && !all)
		return buf;

	if (!keymap_is_generic(keymap)) {
		/* Only the generic keymap includes the default keybindings when
		 * listing all keys. */
		if (all)
			return buf;

		if (!append_keymap_request_keys(buf, &pos, request, generic_keymap, all))
			return "Too many keybindings!";
		if (pos)
			return buf;
	}

	return buf;
}

/*
 * Run requests
 */

static struct run_request *run_request;
static size_t run_requests;

DEFINE_ENUM_MAP(run_request_flag_dummy, ((struct enum_map_entry[]){ ENUM_MAP_ENTRY("x", 0) }));

bool
parse_run_request_flags(struct run_request_flags *flags, const char **argv)
{
	memset(flags, 0, sizeof(*flags));

	if (!strchr("!?@<>+", *argv[0])) {
		flags->internal = *argv[0] == ':';
		return !!flags->internal;
	}

	while (*argv[0]) {
		if (*argv[0] == '@') {
			flags->silent = true;
		} else if (*argv[0] == '?') {
			flags->confirm = true;
		} else if (*argv[0] == '<') {
			flags->exit = true;
		} else if (*argv[0] == '>') {
			flags->quick = true;
		} else if (*argv[0] == '+') {
			flags->echo = true;
		} else if (*argv[0] != '!') {
			break;
		}
		argv[0]++;
	}

	return true;
}

const char *
format_run_request_flags(const struct run_request *req)
{
	static char flags[8];
	int flagspos = 0;

	memset(flags, 0, sizeof(flags));

	if (req->flags.internal)
		flags[flagspos++] = ':';
	else
		flags[flagspos] = '!';

	if (req->flags.silent)
		flags[flagspos++] = '@';
	if (req->flags.confirm)
		flags[flagspos++] = '?';
	if (req->flags.exit)
		flags[flagspos++] = '<';
	if (req->flags.quick)
		flags[flagspos++] = '>';
	if (req->flags.echo)
		flags[flagspos++] = '+';
	if (flagspos > 1)
		flags[flagspos++] = 0;

	return flags;
}

enum request
add_run_request(struct keymap *keymap, const struct key key[], size_t keys, const char **argv)
{
	struct run_request *req;
	struct run_request_flags flags;

	if (!parse_run_request_flags(&flags, argv))
		return REQ_NONE;

	if (!argv[0] || !*argv[0]) {
		/* flags only, e.g. "!" */
	}

	{
		struct run_request *tmp = realloc(run_request, (run_requests + 1) * sizeof(*run_request));
		if (!tmp)
			return REQ_NONE;
		run_request = tmp;
	}

	req = &run_request[run_requests++];
	req->keymap = keymap;
	req->flags = flags;
	req->argv = NULL;

	if (!argv_append_array(&req->argv, argv))
		return REQ_NONE;

	add_keybinding(keymap, REQ_RUN_REQUESTS + run_requests, key, keys);

	return REQ_RUN_REQUESTS + run_requests;
}

struct run_request *
get_run_request(enum request request)
{
	if (request <= REQ_RUN_REQUESTS || request > REQ_RUN_REQUESTS + run_requests)
		return NULL;
	return &run_request[request - REQ_RUN_REQUESTS - 1];
}

int
get_run_request_count(void)
{
	return run_requests;
}

struct run_request *
get_run_request_by_index(int i)
{
	return &run_request[i];
}

/*
 * Key visitor
 */

static const char *
run_request_group(const struct run_request *req)
{
	if (req->flags.internal) {
		if (req->argv[0] && !strcmp(req->argv[0], ":toggle"))
			return "Option toggling:";
		return "Internal commands:";
	}
	return "External commands:";
}

bool
foreach_key(key_visitor_fn visitor, void *data, bool combine_keys)
{
	int i;

	for (i = 0; i < ARRAY_SIZE(keymaps); i++) {
		struct keymap *keymap = &keymaps[i];
		struct keybinding *kb;
		const char *group;
		int j;

		if (!keymap->data)
			continue;

		/* Built-in requests grouped by request group in request order. */
		for (j = 0; j < ARRAY_SIZE(req_info); j++) {
			if (!req_info[j].request) {
				group = req_info[j].help;
				continue;
			}
			if (combine_keys) {
				const char *keys = get_keys(keymap, req_info[j].request, true);
				bool found = false;

				for (kb = keymap->data; kb; kb = kb->next)
					if (kb->request == req_info[j].request)
						found = true;
				if (!found)
					continue;
				if (!visitor(data, group, keymap, req_info[j].request, keys, &req_info[j], NULL))
					return false;
			} else {
				for (kb = keymap->data; kb; kb = kb->next) {
					if (kb->request != req_info[j].request)
						continue;
					if (!visitor(data, group, keymap, kb->request,
						     get_key_name(kb->key, kb->keys, false), &req_info[j], NULL))
						return false;
				}
			}
		}

		/* Run requests: toggles, internal, external. */
		{
			static const char *groups[] = { "Option toggling:", "Internal commands:", "External commands:" };
			int g;

			for (g = 0; g < 3; g++) {
				for (kb = keymap->data; kb; kb = kb->next) {
					struct run_request *req = get_run_request(kb->request);

					if (!req || strcmp(run_request_group(req), groups[g]))
						continue;
					if (!visitor(data, groups[g], keymap, kb->request,
						     get_key_name(kb->key, kb->keys, false), NULL, req))
						return false;
				}
			}
		}
	}

	return true;
}

