static const struct key_mapping *
get_key_mapping(const char *name, size_t namelen)
{
	int i;

	for (i = 0; i < ARRAY_SIZE(key_mappings); i++) {
		if (namelen == strlen(key_mappings[i].name) &&
		    !strncasecmp(key_mappings[i].name, name, namelen))
			return &key_mappings[i];
	}

	return NULL;
}

/* Parse a single key from the name; advances *name_ptr. */
int
get_key_value(const char **name_ptr, struct key *key)
{
	const char *name = *name_ptr;
	size_t len;

	memset(key, 0, sizeof(*key));

	if (*name == '<') {
		const char *end = strchr(name + 1, '>');

		if (!end)
			return -1;

		if (!strncasecmp(name + 1, "Ctrl-", 5)) {
			char ctrl = name[6];

			if (name + 7 != end)
				return -1;
			if (!isalpha((unsigned char) ctrl) && !strchr("@[\\\\]^_", ctrl))
				return -1;
			key->ctrl = true;
			key->value = ctrl;
			*name_ptr = end + 1;
			return 0;
		} else {
			const struct key_mapping *mapping = get_key_mapping(name + 1, end - name - 1);

			if (!mapping)
				return -1;
			key->value = mapping->value;
			*name_ptr = end + 1;
			return 0;
		}
	}

	len = utf8_char_length(name);
	if (len == 1) {
		key->value = (unsigned char) *name;
	} else {
		if (len > sizeof(key->bytes) - 1 || strlen(name) < len)
			return -1;
		strncpy(key->bytes, name, len);
		key->bytes[len] = 0;
		key->multibytes = true;
	}
	*name_ptr = name + len;
	return 0;
}

const char *
get_key_name(const struct key key[], size_t keys, bool quote_comma)
{
	static char buf[SIZEOF_STR];
	size_t pos = 0;
	int i;

	buf[0] = 0;
	for (i = 0; i < keys; i++) {
		const struct key *k = &key[i];
		const char *name = NULL;
		int value = k->value;
		int j;

		if (k->ctrl) {
			if (!string_format_from(buf, &pos, "<Ctrl-%c>", value))
				return "(no key)";
			continue;
		}

		if (k->multibytes) {
			if (!string_format_from(buf, &pos, "%s", k->bytes))
				return "(no key)";
			continue;
		}

		for (j = 0; j < ARRAY_SIZE(key_mappings); j++) {
			if (key_mappings[j].value == value) {
				name = key_mappings[j].name;
				break;
			}
		}

		if (name) {
			if (!string_format_from(buf, &pos, "<%s>", name))
				return "(no key)";
		} else if (value == ',' && quote_comma) {
			if (!string_format_from(buf, &pos, "','"))
				return "(no key)";
		} else if (value >= 0 && value < 32) {
			if (!string_format_from(buf, &pos, "<Ctrl-%c>", value + '@'))
				return "(no key)";
		} else if (value == 127) {
			if (!string_format_from(buf, &pos, "<Backspace>"))
				return "(no key)";
		} else {
			if (!string_format_from(buf, &pos, "%c", value))
				return "(no key)";
		}
	}

	return buf;
}

