static bool
keybinding_equals(const struct keybinding *keybinding, const struct key key[], size_t keys)
{
	int i;

	if (keybinding->keys != keys)
		return false;
	for (i = 0; i < keys; i++)
		if (!key_equals(&keybinding->key[i], &key[i]))
			return false;
	return true;
}

static bool
keybinding_matches(const struct keybinding *keybinding, const struct key key[], size_t keys)
{
	int i;

	if (keybinding->keys < keys)
		return false;
	for (i = 0; i < keys; i++)
		if (!key_equals(&keybinding->key[i], &key[i]))
			return false;
	return true;
}

void
add_keybinding(struct keymap *table, enum request request,
	       const struct key key[], size_t keys)
{
	struct keybinding *keybinding;
	struct keybinding **tail;

	for (keybinding = table->data; keybinding; keybinding = keybinding->next) {
		if (keybinding_equals(keybinding, key, keys)) {
			keybinding->request = request;
			return;
		}
	}

	keybinding = calloc(1, sizeof(*keybinding) + sizeof(key[0]) * (keys > 0 ? keys - 1 : 0));
	if (!keybinding)
		die("Failed to allocate keybinding");
	memcpy(keybinding->key, key, sizeof(key[0]) * keys);
	keybinding->keys = keys;
	keybinding->request = request;

	tail = &table->data;
	while (*tail)
		tail = &(*tail)->next;
	*tail = keybinding;
	table->size++;
}

/* Looks for a key binding first in the given map, then in the generic map.
 * Returns REQ_UNKNOWN when nothing matches, REQ_NONE when only a longer
 * binding could match (matches > 0). */
enum request
get_keybinding(const struct keymap *keymap, const struct key key[], size_t keys, int *matches)
{
	enum request request = REQ_UNKNOWN;
	int count = 0;
	const struct keymap *maps[2] = { keymap, generic_keymap };
	int m;

	for (m = 0; m < 2; m++) {
		struct keybinding *kb;

		if (m == 1 && keymap == generic_keymap)
			break;
		for (kb = maps[m]->data; kb; kb = kb->next) {
			if (!keybinding_matches(kb, key, keys))
				continue;
			if (kb->keys == keys) {
				if (request == REQ_UNKNOWN)
					request = kb->request;
			} else {
				count++;
			}
		}
		/* A view specific exact match shadows generic ones. */
		if (request != REQ_UNKNOWN && m == 0)
			break;
	}

	if (matches)
		*matches = count;
	return request;
}

