	{ "tree-view", &opt_tree_view, VC(AUTHOR) | VC(COMMITTER) | VC(DATE) | VC(ID) | VC(FILE_NAME) | VC(FILE_SIZE) | VC(LINE_NUMBER) | VC(MODE) },
