struct view_column *
get_view_column_options(const char *view_name)
{
	int i;

	for (i = 0; i < ARRAY_SIZE(view_settings); i++) {
		if (!prefixcmp(view_settings[i].name, view_name) &&
		    view_settings[i].name[strlen(view_name)] == '-')
			return *view_settings[i].columns;
	}
	return NULL;
}

static void
free_view_columns(struct view_column *column)
{
	while (column) {
		struct view_column *next = column->next;

		free(column);
		column = next;
	}
}

enum status_code
parse_view_settings(struct view_column **columns_ptr, const char *name, const char *argv[])
{
	struct view_column *columns = NULL, **tail = &columns;
	const char *view_name = name;
	size_t view_namelen;
	unsigned int supported = 0;
	int i;

	for (i = 0; i < ARRAY_SIZE(view_settings); i++) {
		if (!strcmp(view_settings[i].name, name)) {
			supported = view_settings[i].supported;
			break;
		}
	}
	view_namelen = strlen(name) - STRING_SIZE("-view");

	for (i = 0; argv[i]; i++) {
		struct view_column *column = calloc(1, sizeof(*column));
		enum status_code code;

		if (!column) {
			free_view_columns(columns);
			return ERROR_OUT_OF_MEMORY;
		}

		code = parse_view_column_spec(column, argv[i]);
		if (code != SUCCESS) {
			free(column);
			free_view_columns(columns);
			return code;
		}

		if (!(supported & (1 << column->type))) {
			enum view_column_type type = column->type;

			free(column);
			free_view_columns(columns);
			return error("The %.*s view does not support %s column", (int) view_namelen, view_name, view_column_name(type));
		}

		if (columns && (*tail == NULL)) {
			/* find last */
		}
		/* commit-title must be last */
		{
			struct view_column *c;

			for (c = columns; c; c = c->next) {
				if (c->type == VIEW_COLUMN_COMMIT_TITLE) {
					free(column);
					free_view_columns(columns);
					return error("The commit-title column must always be last");
				}
			}
		}

		*tail = column;
		tail = &column->next;
	}

	free_view_columns(*columns_ptr);
	*columns_ptr = columns;
	return SUCCESS;
}

static const char *
format_column_display(struct view_column *column, const struct column_option_def *def, char *buf, size_t bufsize)
{
	void *ptr = column_opt_ptr(column, def);

	switch (def->type) {
	case COPT_BOOL:
		return *(bool *) ptr ? "yes" : "no";
	case COPT_INT:
	case COPT_INT_OR_PERCENT:
	case COPT_BOOL_OR_INT:
		string_nformat(buf, bufsize, NULL, "%d", *(int *) ptr);
		return buf;
	case COPT_ENUM:
	case COPT_GRAPH:
	case COPT_DATE_DISPLAY:
		{
			int i, v = *(int *) ptr;

			for (i = 0; i < def->map->size; i++)
				if (def->map->entries[i].value == v)
					return def->map->entries[i].name;
			return "unknown";
		}
	case COPT_STRING:
		string_nformat(buf, bufsize, NULL, "\"%s\"", (char *) ptr);
		return buf;
	}
	return "";
}

const char *
format_view_columns(struct view_column *column, char *buf, size_t bufsize)
{
	size_t pos = 0;

	buf[0] = 0;
	for (; column; column = column->next) {
		const struct column_option_def *defs = column_option_defs[column->type].opts;
		size_t count = column_option_defs[column->type].count;
		char vbuf[SIZEOF_STR];
		char opts[SIZEOF_STR] = "";
		size_t optpos = 0;
		size_t i;
		const char *display;
		bool display_is_yes;

		if (pos && !string_nformat(buf, bufsize, &pos, " "))
			return buf;
		if (!string_nformat(buf, bufsize, &pos, "%s", view_column_name(column->type)))
			return buf;

		display = format_column_display(column, &defs[0], vbuf, sizeof(vbuf));
		display_is_yes = defs[0].type == COPT_BOOL && !strcmp(display, "yes");

		for (i = 1; i < count; i++) {
			const struct column_option_def *def = &defs[i];
			void *ptr = column_opt_ptr(column, def);
			char vbuf2[SIZEOF_STR];

			if ((def->type == COPT_INT || def->type == COPT_INT_OR_PERCENT || def->type == COPT_BOOL_OR_INT) && *(int *) ptr == 0)
				continue;
			if (def->type == COPT_STRING && !*(char *) ptr)
				continue;
			string_nformat(opts, sizeof(opts), &optpos, ",%s=%s", def->name,
				       format_column_display(column, def, vbuf2, sizeof(vbuf2)));
		}

		if (display_is_yes && !*opts)
			continue;
		if (!string_nformat(buf, bufsize, &pos, ":%s%s", display, opts))
			return buf;
	}
	return buf;
}

