/*
 * Git config
 */

static int
read_git_color_option(const char *name, char *value)
{
	return 0;
}

static enum status_code
set_git_color_option(const char *name, char *value)
{
	const char *argv[SIZEOF_ARGV];
	int argc = 0;
	int i;

	if (!opt_git_colors)
		return SUCCESS;

	for (i = 0; opt_git_colors[i]; i++) {
		const char *mapping = opt_git_colors[i];
		const char *eq = strchr(mapping, '=');

		if (!eq)
			continue;
		if (strncasecmp(mapping, name, eq - mapping) || name[eq - mapping])
			continue;
		{
			char tmp[SIZEOF_STR];
			const char *cargv[SIZEOF_ARGV + 1];
			int cargc = 0, j;

			string_ncopy(tmp, value, strlen(value));
			if (!argv_from_string(argv, &argc, tmp))
				return SUCCESS;
			cargv[cargc++] = eq + 1;
			for (j = 0; j < argc && cargc < SIZEOF_ARGV; j++)
				cargv[cargc++] = argv[j];
			cargv[cargc] = NULL;
			if (cargc >= 3 || cargc == 2) {
				/* Git colors: "fg [bg] [attrs]"; for one value treat bg as default */
				const char *fixed[SIZEOF_ARGV + 2];
				int fc = 0;

				fixed[fc++] = cargv[0];
				fixed[fc++] = cargv[1];
				if (cargc == 2) {
					fixed[fc++] = "default";
				} else {
					int k;
					/* Git color syntax: fg bg attrs...; but attrs may appear as second value */
					for (k = 2; k < cargc; k++)
						fixed[fc++] = cargv[k];
				}
				fixed[fc] = NULL;
				option_color_command(fc, fixed);
			}
		}
	}
	return SUCCESS;
}

static enum status_code
set_encoding(char *opt, const char *arg, size_t optsize)
{
	parse_string(opt, arg, optsize);
	if (!strcasecmp(opt, "utf-8") || !strcasecmp(opt, "utf8"))
		string_ncopy_do(opt, optsize, "UTF-8", 5);
	return SUCCESS;
}

enum status_code
set_repo_config_option(char *name, char *value, option_fn cmd)
{
	const char *argv[SIZEOF_ARGV] = { name, "=" };
	int argc = 1 + (cmd == option_set_command);
	enum status_code code;

	if (!argv_from_string(argv, &argc, value))
		code = error("Too many arguments");
	else
		code = cmd(argc, argv);

	return code;
}

static enum status_code
set_option_fn(const char *argv[])
