/*
 * Line infos
 */

static struct line_info *line_infos;	/* array indexed by type for builtin types */
static struct line_info **custom_infos;	/* appended custom infos (in definition order) */
static size_t custom_infos_count;

struct builtin_line_def {
	const char *name;
	const char *prefix;
	int fg, bg, attr;
};

static const struct builtin_line_def builtin_lines[] = {
#define DEFINE_LINE_DEF(type, line, fg, bg, attr) { #type, line, fg, bg, attr }
	LINE_INFO(DEFINE_LINE_DEF)
};

struct line_info *
get_line_info(const char *keymap, enum line_type type)
{
	struct line_info *info;

	if (type < LINE_NONE) {
		info = &line_infos[type];
	} else {
		size_t idx = type - LINE_NONE;

		if (idx >= custom_infos_count)
			return &line_infos[LINE_DEFAULT];
		info = custom_infos[idx];
	}

	if (keymap) {
		struct line_info *vinfo;

		for (vinfo = info->next; vinfo; vinfo = vinfo->next)
			if (vinfo->keymap && !strcasecmp(vinfo->keymap, keymap))
				return vinfo;
	}
	return info;
}

static struct line_info *
get_base_line_info(enum line_type type)
{
	if (type < LINE_NONE)
		return &line_infos[type];
	if (type - LINE_NONE < custom_infos_count)
		return custom_infos[type - LINE_NONE];
	return NULL;
}

const char *
get_line_type_name(enum line_type type)
{
	struct line_info *info = get_base_line_info(type);

	if (!info)
		return "";
	if (!info->name)
		return "";
	return enum_name(info->name);
}

static void
init_line_infos(void)
{
	int i;

	if (line_infos)
		return;
	line_infos = calloc(LINE_NONE, sizeof(*line_infos));
	for (i = 0; i < LINE_NONE; i++) {
		line_infos[i].name = builtin_lines[i].name;
		line_infos[i].prefix = builtin_lines[i].prefix;
		line_infos[i].prefixlen = strlen(builtin_lines[i].prefix);
		line_infos[i].fg = builtin_lines[i].fg;
		line_infos[i].bg = builtin_lines[i].bg;
		line_infos[i].attr = builtin_lines[i].attr;
	}
}

static size_t
line_info_count(void)
{
	return LINE_NONE + custom_infos_count;
}

static enum line_type
line_info_type(struct line_info *info)
{
	size_t i;

	if (info >= line_infos && info < line_infos + LINE_NONE)
		return info - line_infos;
	for (i = 0; i < custom_infos_count; i++)
		if (custom_infos[i] == info)
			return LINE_NONE + i;
	return LINE_DEFAULT;
}

/* Find a line info by name (type name) or by exact prefix match when quoted. */
struct line_info *
find_line_info(const char *keymap, const char *name, size_t namelen, bool line_only)
{
	size_t i, count = line_info_count();

	for (i = 0; i < count; i++) {
		struct line_info *info = get_base_line_info(i);

		if (!line_only && info->name && enum_equals(info->name, strlen(info->name), name, namelen))
			goto found;
		if (info->prefix && *info->prefix && info->prefixlen == namelen &&
		    !strncmp(info->prefix, name, namelen))
			goto found;
		continue;
found:
		if (keymap) {
			struct line_info *vinfo;

			for (vinfo = info->next; vinfo; vinfo = vinfo->next)
				if (vinfo->keymap && !strcasecmp(vinfo->keymap, keymap))
					return vinfo;
			return NULL;
		}
		return info;
	}

	return NULL;
}

struct line_info *
add_line_info(const char *name, size_t namelen, const char *line, size_t linelen)
{
	struct line_info *info = calloc(1, sizeof(*info));
	struct line_info **tmp;

	if (!info)
		return NULL;
	if (name && namelen) {
		char *n = malloc(namelen + 1);
		strncpy(n, name, namelen);
		n[namelen] = 0;
		info->name = n;
	}
	if (line) {
		char *l = malloc(linelen + 1);
		strncpy(l, line, linelen);
		l[linelen] = 0;
		info->prefix = l;
		info->prefixlen = linelen;
	} else {
		info->prefix = "";
	}
	info->fg = COLOR_DEFAULT;
	info->bg = COLOR_DEFAULT;

	tmp = realloc(custom_infos, (custom_infos_count + 1) * sizeof(*custom_infos));
	if (!tmp)
		return NULL;
	custom_infos = tmp;
	custom_infos[custom_infos_count++] = info;
	return info;
}

static struct line_info *
add_view_line_info(struct line_info *base, const char *keymap)
{
	struct line_info *info = calloc(1, sizeof(*info));

	if (!info)
		return NULL;
	*info = *base;
	info->next = NULL;
	info->keymap = str_dup(keymap);
	info->regex = base->regex;
	/* append */
	{
		struct line_info **tail = &base->next;

		while (*tail)
			tail = &(*tail)->next;
		*tail = info;
	}
	return info;
}

static bool
line_info_is_regex(struct line_info *info)
{
	return info->regex != NULL;
}

int
find_custom_line_type(const char *line, const char *keymap)
{
	size_t i;

	for (i = 0; i < custom_infos_count; i++) {
		struct line_info *info = custom_infos[i];

		if (info->regex) {
			if (!regexec(info->regex, line, 0, NULL, 0))
				return LINE_NONE + i;
		} else if (info->prefixlen && !strncmp(info->prefix, line, info->prefixlen)) {
			return LINE_NONE + i;
		}
	}
	return -1;
}

enum line_type
get_line_type(const char *line)
{
	int linelen = strlen(line);
	enum line_type type;
	int custom;

	for (type = 0; type < LINE_NONE; type++) {
		struct line_info *info = &line_infos[type];

		/* Case insensitive search matches Signed-off-by lines better. */
		if (info->prefixlen && linelen >= info->prefixlen &&
		    !strncasecmp(info->prefix, line, info->prefixlen))
			return type;
	}

	custom = find_custom_line_type(line, NULL);
	if (custom >= 0)
		return custom;

	return LINE_DEFAULT;
}

enum line_type
get_line_type_from_ref(const struct ref *ref)
{
	switch (ref->type) {
	case REFERENCE_HEAD: return LINE_MAIN_HEAD;
	case REFERENCE_BRANCH: return LINE_MAIN_REF;
	case REFERENCE_TRACKED_REMOTE: return LINE_MAIN_TRACKED;
	case REFERENCE_REMOTE: return LINE_MAIN_REMOTE;
	case REFERENCE_TAG: return LINE_MAIN_TAG;
	case REFERENCE_LOCAL_TAG: return LINE_MAIN_LOCAL_TAG;
	case REFERENCE_STASH: return LINE_MAIN_STASH;
	case REFERENCE_REPLACE: return LINE_MAIN_REPLACE;
	case REFERENCE_NOTE: return LINE_MAIN_NOTE;
	case REFERENCE_PREFETCH: return LINE_MAIN_PREFETCH;
	default: return LINE_MAIN_OTHER;
	}
}

bool opt_no_color = false;
static int color_pairs_used = 0;

static void
init_line_info_color(struct line_info *info)
{
	int fg = info->fg;
	int bg = info->bg;

	if (fg == COLOR_DEFAULT)
		fg = -1;
	if (bg == COLOR_DEFAULT)
		bg = -1;
	info->color_pair = ++color_pairs_used;
	if (info->color_pair < COLOR_PAIRS)
		init_pair(info->color_pair, fg, bg);
}

void
init_colors(void)
{
	size_t i, count = line_info_count();
	bool colors = has_colors() && !opt_no_color;

	color_pairs_used = 0;
	if (colors) {
		start_color();
		use_default_colors();
	}
	for (i = 0; i < count; i++) {
		struct line_info *info = get_base_line_info(i);

		for (; info; info = info->next) {
			if (colors)
				init_line_info_color(info);
			else
				info->color_pair = 0;
		}
	}
}

int
get_line_color(const char *keymap, enum line_type type)
{
	return get_line_info(keymap, type)->color_pair;
}

int
get_line_attr(const char *keymap, enum line_type type)
{
	struct line_info *info = get_line_info(keymap, type);

	return COLOR_PAIR(info->color_pair) | info->attr;
}

/*
 * Parsing helpers
 */

enum status_code
parse_bool_matched(bool *opt, const char *arg, bool *matched)
{
	*matched = true;
	if (!strcmp(arg, "1") || !strcmp(arg, "true") || !strcmp(arg, "yes")) {
		*opt = true;
		return SUCCESS;
	}
	if (!strcmp(arg, "0") || !strcmp(arg, "false") || !strcmp(arg, "no")) {
		*opt = false;
		return SUCCESS;
	}
	*matched = false;
	*opt = false;
	return SUCCESS;
}

enum status_code
parse_bool(bool *opt, const char *arg)
{
	bool matched;
	enum status_code code = parse_bool_matched(opt, arg, &matched);

	if (!matched && code == SUCCESS && *arg)
		return error("Non-boolean value treated as false: %s", arg);
	if (!matched && code == SUCCESS)
		return SUCCESS;
	return code;
}

enum status_code
parse_enum(const char *name, unsigned int *opt, const char *arg, const struct enum_map *map)
{
	bool is_true;
	int value;

	if (map_enum_do(map->entries, map->size, &value, arg)) {
		*opt = value;
		return SUCCESS;
	}

	if (!strcmp(arg, "1") || !strcmp(arg, "true") || !strcmp(arg, "yes")) {
		*opt = 1;
		return SUCCESS;
	}
	if (!strcmp(arg, "0") || !strcmp(arg, "false") || !strcmp(arg, "no")) {
		*opt = 0;
		return SUCCESS;
	}

	(void) is_true;
	*opt = 0;
	return error("'%s' is not a valid value for %s; using %s", arg, name, map->entries[0].name);
}

static enum status_code
parse_date_display(unsigned int *opt, const char *arg)
{
	int value;

	if (map_enum_do(date_display_map->entries, date_display_map->size, &value, arg)) {
		*opt = value;
		return SUCCESS;
	}
	if (!strcmp(arg, "1") || !strcmp(arg, "true") || !strcmp(arg, "yes")) {
		*opt = DATE_DISPLAY_DEFAULT;
		return SUCCESS;
	}
	if (!strcmp(arg, "0") || !strcmp(arg, "false") || !strcmp(arg, "no")) {
		*opt = DATE_DISPLAY_NO;
		return SUCCESS;
	}
	*opt = DATE_DISPLAY_NO;
	if (!strcmp(arg, "short"))
		return error("'%s' is no longer supported for date-display, use the 'custom' display mode and set 'date-format'", arg);
	return error("'%s' is no longer supported for date-display", arg);
}

enum status_code
parse_int(int *opt, const char *arg, int min, int max)
{
	int value = atoi(arg);

	if (min <= value && value <= max) {
		*opt = value;
		return SUCCESS;
	}

	return error("Value must be between %d and %d", min, max);
}

static enum status_code
parse_int_or_percent(int *opt, const char *arg, int min, int max)
{
	int value = atoi(arg);

	if (strchr(arg, '%') && value >= 0 && value <= 100) {
		*opt = -value;
		return SUCCESS;
	}
	if (min <= value && value <= max) {
		*opt = value;
		return SUCCESS;
	}
	return error("Value must be between %d and %d", min, max);
}

enum status_code
parse_step(double *opt, const char *arg)
{
	int value = atoi(arg);

	if (!value && !isdigit((unsigned char) *arg))
		return error("Invalid double or percentage");

	*opt = value;
	if (strchr(arg, '%')) {
		if (*opt > 100)
			return error("Percentage is larger than 100%%");
		*opt /= 100;
	}
	return SUCCESS;
}

static enum status_code
parse_string(char *opt, const char *arg, size_t optsize)
{
	int arglen = strlen(arg);

	switch (arg[0]) {
	case '\"':
	case '\'':
		if (arglen == 1 || arg[arglen - 1] != arg[0]) {
			/* Unterminated quote: accept content */
			string_ncopy_do(opt, optsize, arg + 1, arglen - 1);
			return SUCCESS;
		}
		if (arglen > 1)
			string_ncopy_do(opt, optsize, arg + 1, arglen - 2);
		else
			opt[0] = 0;
		return SUCCESS;
	default:
		string_ncopy_do(opt, optsize, arg, arglen);
		return SUCCESS;
	}
}

static enum status_code
parse_encoding(char *opt, const char *arg, size_t optsize)
{
	return parse_string(opt, arg, optsize);
}

enum status_code
parse_args(const char ***args, const char *argv[])
{
	argv_free(*args);
	if (!argv_copy(args, argv))
		return ERROR_OUT_OF_MEMORY;
	return SUCCESS;
}

/*
 * Reference formats
 */

static struct ref_format *ref_formats[REFERENCE_OTHER + 1];

const struct ref_format *
get_ref_format(const struct ref *ref)
{
	static const struct ref_format default_format = { "", "", false };

	if (ref_formats[ref->type])
		return ref_formats[ref->type];

	if (ref->type == REFERENCE_LOCAL_TAG && ref_formats[REFERENCE_TAG])
		return ref_formats[REFERENCE_TAG];
	if (ref->type == REFERENCE_TRACKED_REMOTE && ref_formats[REFERENCE_REMOTE])
		return ref_formats[REFERENCE_REMOTE];
	if (ref->type != REFERENCE_BRANCH && ref->type != REFERENCE_TAG &&
	    ref->type != REFERENCE_REMOTE && ref_formats[REFERENCE_BRANCH])
		return ref_formats[REFERENCE_BRANCH];

	return &default_format;
}

static enum status_code
parse_ref_format_arg(const char *arg, const struct enum_map *map)
{
	size_t arglen = strlen(arg);
	const char *begin = NULL, *end = NULL;
	bool hidden = false;
	int i;

	if (!prefixcmp(arg, "hide:")) {
		hidden = true;
		arg += STRING_SIZE("hide:");
		arglen = strlen(arg);
	}

	for (i = 0; i < map->size; i++) {
		const struct enum_map_entry *entry = &map->entries[i];
		const char *mapped = strstr(arg, entry->name);

		if (mapped && arglen >= entry->namelen) {
			struct ref_format *format;
			size_t before = mapped - arg;

			if (strlen(mapped) != entry->namelen + (arglen - entry->namelen - before)) {
				/* name must be exactly in the middle */
			}
			if (mapped + entry->namelen > arg + arglen)
				continue;
			if (strncmp(mapped, entry->name, entry->namelen))
				continue;
			/* Ensure the remainder after the name is the end part */
			begin = arg;
			end = mapped + entry->namelen;
			format = calloc(1, sizeof(*format));
			if (!format)
				return ERROR_OUT_OF_MEMORY;
			format->start = strndup(begin, mapped - begin);
			format->end = str_dup(end);
			format->hidden = hidden;
			free(ref_formats[entry->value]);
			ref_formats[entry->value] = format;
			return SUCCESS;
		}
	}

	return error("Unknown ref format: %s", arg);
}

int
parse_ref_formats(const char *argv[])
{
	int i;

	for (i = 0; argv[i]; i++) {
		enum status_code code = parse_ref_format_arg(argv[i], reference_type_map);

		if (code != SUCCESS)
			return code;
	}

	return SUCCESS;
}

int
format_ref_formats(char buf[], size_t bufsize)
{
	size_t pos = 0;
	const char *sep = "";
	int i;

	buf[0] = 0;
	for (i = 0; i < reference_type_map->size; i++) {
		const struct enum_map_entry *entry = &reference_type_map->entries[i];
		struct ref_format *format = ref_formats[entry->value];

		if (!format)
			continue;

		if (!string_nformat(buf, bufsize, &pos, "%s%s%s%s%s",
				    sep, format->hidden ? "hide:" : "",
				    format->start, entry->name, format->end))
			return ERROR_OUT_OF_MEMORY;
		sep = " ";
	}

	return SUCCESS;
}

