static void *
column_opt_ptr(struct view_column *column, const struct column_option_def *def)
{
	return ((char *) &column->opt) + def->offset;
}

static enum status_code
parse_column_option_value(struct view_column *column, const struct column_option_def *def, const char *value)
{
	void *ptr = column_opt_ptr(column, def);
	char name[SIZEOF_STR];

	switch (def->type) {
	case COPT_BOOL:
		return parse_bool((bool *) ptr, value);
	case COPT_INT:
		return parse_int((int *) ptr, value, def->min, def->max);
	case COPT_INT_OR_PERCENT:
		return parse_int_or_percent((int *) ptr, value, def->min, def->max);
	case COPT_ENUM:
		string_format(name, "%s-%s", view_column_name(column->type), def->name);
		return parse_enum(name, (unsigned int *) ptr, value, def->map);
	case COPT_GRAPH:
		string_format(name, "%s-%s", view_column_name(column->type), def->name);
		{
			int v;
			if (map_enum_do(def->map->entries, def->map->size, &v, value)) {
				*(int *) ptr = v;
				return SUCCESS;
			}
			if (!strcmp(value, "1") || !strcmp(value, "true") || !strcmp(value, "yes")) {
				*(int *) ptr = GRAPH_DISPLAY_V2;
				return SUCCESS;
			}
			if (!strcmp(value, "0") || !strcmp(value, "false") || !strcmp(value, "no")) {
				*(int *) ptr = GRAPH_DISPLAY_NO;
				return SUCCESS;
			}
			*(int *) ptr = GRAPH_DISPLAY_NO;
			return error("'%s' is not a valid value for %s; using %s", value, name, def->map->entries[0].name);
		}
	case COPT_DATE_DISPLAY:
		return parse_date_display((unsigned int *) ptr, value);
	case COPT_STRING:
		return parse_string((char *) ptr, value, SIZEOF_STR);
	case COPT_BOOL_OR_INT:
		{
			bool b, matched;

			parse_bool_matched(&b, value, &matched);
			if (matched) {
				*(int *) ptr = b ? 50 : 0;
				return SUCCESS;
			}
			if (string_isnumber(value))
				return parse_int((int *) ptr, value, def->min, def->max);
			*(int *) ptr = 0;
			return SUCCESS;
		}
	}
	return SUCCESS;
}

static enum status_code
parse_view_column_option(struct view_column *column, const char *opt_name, const char *value)
{
	const struct column_option_def *defs = column_option_defs[column->type].opts;
	size_t count = column_option_defs[column->type].count;
	size_t namelen = strlen(opt_name);
	size_t i;

	for (i = 0; i < count; i++) {
		if (enum_equals(defs[i].name, strlen(defs[i].name), opt_name, namelen))
			return parse_column_option_value(column, &defs[i], value);
	}

	return error("Unknown option `%s' for column %s", opt_name, view_column_name(column->type));
}

static enum status_code
parse_view_column_spec(struct view_column *column, const char *arg)
{
	char buf[SIZEOF_STR];
	char *type_end, *opts;
	int type;

	string_ncopy(buf, arg, strlen(arg));
	type_end = strchr(buf, ':');
	if (type_end) {
		*type_end = 0;
		opts = type_end + 1;
	} else {
		opts = NULL;
	}

	if (!map_enum(&type, view_column_type_map, buf))
		return error("Failed to parse view column type: %s", buf);

	column->type = type;
	memset(&column->opt, 0, sizeof(column->opt));

	/* Default display value is "yes". */
	{
		const struct column_option_def *def = &column_option_defs[type].opts[0];
		enum status_code code = parse_column_option_value(column, def, "yes");

		if (code != SUCCESS)
			return code;
		/* Hmm: enum display "yes" -> 1 */
	}

	if (opts) {
		char *opt = opts;
		bool first = true;

		while (opt) {
			char *next = strchr(opt, ',');
			char *value;
			enum status_code code;

			if (next)
				*next++ = 0;

			if (first) {
				first = false;
				if (*opt) {
					code = parse_column_option_value(column, &column_option_defs[type].opts[0], opt);
					if (code != SUCCESS)
						return code;
				}
				opt = next;
				continue;
			}

			value = strchr(opt, '=');
			if (value)
				*value++ = 0;
			else
				value = "";
			code = parse_view_column_option(column, opt, value);
			if (code != SUCCESS)
				return code;
			opt = next;
		}
	}

	return SUCCESS;
}

