static struct option_info *
find_option_info(const char *prefix, const char *name)
{
	size_t namelen = strlen(name);
	char prefixed[SIZEOF_STR];
	int i;

	if (prefix && *prefix) {
		string_format(prefixed, "%s-%s", prefix, name);
		name = prefixed;
		namelen = strlen(name);
	}

	for (i = 0; i < ARRAY_SIZE(option_info); i++)
		if (enum_equals(option_info[i].name, strlen(option_info[i].name), name, namelen))
			return &option_info[i];

	return NULL;
}

static enum status_code
parse_option(struct option_info *option, const char *prefix, const char *argv[], int argc)
{
	char name[SIZEOF_STR];

	if (option->type != OPT_ARGS && option->type != OPT_VIEW && option->type != OPT_REF_FORMAT && argc > 1)
		return error("Option %s only takes one value", option->name);

	if (option->type != OPT_ARGS && option->type != OPT_VIEW && option->type != OPT_REF_FORMAT && argc < 1)
		return error("No value assigned to %s", option->name);

	string_format(name, "%s", option->name);

	switch (option->type) {
	case OPT_BOOL:
		return parse_bool(option->value, argv[0]);
	case OPT_INT:
		return parse_int(option->value, argv[0], option->min, option->max);
	case OPT_ID_WIDTH:
		return parse_int(option->value, argv[0], option->min, option->max);
	case OPT_DOUBLE:
		return parse_step(option->value, argv[0]);
	case OPT_STRING:
		return parse_string(option->value, argv[0], SIZEOF_STR);
	case OPT_ENUM:
		return parse_enum(name, option->value, argv[0], option->map);
	case OPT_COMMIT_ORDER:
		return parse_enum(name, option->value, argv[0], option->map);
	case OPT_ARGS:
		return parse_args(option->value, argv);
	case OPT_VIEW:
		return parse_view_settings(option->value, option->name, argv);
	case OPT_REF_FORMAT:
		{
			enum status_code code = parse_ref_formats(argv);
			if (code == SUCCESS)
				return parse_args(option->value, argv);
			return code;
		}
	case OPT_SHOW_NOTES:
		{
			bool matched;
			bool *opt = option->value;

			parse_bool_matched(opt, argv[0], &matched);
			if (matched) {
				string_copy(opt_notes_arg, "--show-notes");
				return SUCCESS;
			}
			*opt = true;
			string_format(opt_notes_arg, "--show-notes=%s", argv[0]);
			return SUCCESS;
		}
	case OPT_DIFF_HIGHLIGHT:
		{
			bool matched, b;

			parse_bool_matched(&b, argv[0], &matched);
			if (matched) {
				if (b)
					string_copy(opt_diff_highlight, "diff-highlight");
				else
					opt_diff_highlight[0] = 0;
				return SUCCESS;
			}
			return parse_string(opt_diff_highlight, argv[0], sizeof(opt_diff_highlight));
		}
	case OPT_TRUNCATION_DELIMITER:
		{
			char buf[SIZEOF_STR];

			parse_string(buf, argv[0], sizeof(buf));
			if (!strcmp(buf, "utf-8")) {
				string_copy(opt_truncation_delimiter, "utf-8");
				return SUCCESS;
			}
			if (utf8_width_of(buf, -1, -1) == 1 && (int) strlen(buf) == utf8_char_length(buf)) {
				string_ncopy(opt_truncation_delimiter, buf, strlen(buf));
				return SUCCESS;
			}
			return SUCCESS;
		}
	}
	return SUCCESS;
}

static enum status_code
format_option(struct option_info *option, char *buf, size_t bufsize)
{
	switch (option->type) {
	case OPT_BOOL:
		string_nformat(buf, bufsize, NULL, "%s", *(bool *) option->value ? "yes" : "no");
		return SUCCESS;
	case OPT_INT:
	case OPT_ID_WIDTH:
		string_nformat(buf, bufsize, NULL, "%d", *(int *) option->value);
		return SUCCESS;
	case OPT_DOUBLE:
		{
			double v = *(double *) option->value;

			if (v >= 1)
				string_nformat(buf, bufsize, NULL, "%d", (int) v);
			else
				string_nformat(buf, bufsize, NULL, "%d%%", (int) (v * 100));
			return SUCCESS;
		}
	case OPT_STRING:
	case OPT_DIFF_HIGHLIGHT:
	case OPT_TRUNCATION_DELIMITER:
		string_nformat(buf, bufsize, NULL, "\"%s\"", (char *) option->value);
		return SUCCESS;
	case OPT_ENUM:
	case OPT_COMMIT_ORDER:
		{
			int i, v = *(int *) option->value;

			for (i = 0; i < option->map->size; i++)
				if (option->map->entries[i].value == v) {
					string_nformat(buf, bufsize, NULL, "%s", option->map->entries[i].name);
					return SUCCESS;
				}
			buf[0] = 0;
			return SUCCESS;
		}
	case OPT_ARGS:
		{
			const char **argv = *(const char ***) option->value;

			buf[0] = 0;
			if (argv)
				argv_to_string(argv, buf, bufsize, " ");
			return SUCCESS;
		}
	case OPT_VIEW:
		format_view_columns(*(struct view_column **) option->value, buf, bufsize);
		return SUCCESS;
	case OPT_REF_FORMAT:
		format_ref_formats(buf, bufsize);
		return SUCCESS;
	case OPT_SHOW_NOTES:
		string_nformat(buf, bufsize, NULL, "%s", *(bool *) option->value ? "yes" : "no");
		return SUCCESS;
	}
	return SUCCESS;
}

enum status_code
format_option_value(const char *name, char *buf, size_t bufsize)
{
	struct option_info *option = find_option_info(NULL, name);

	if (!option)
		return error("Unknown option name: %s", name);
	return format_option(option, buf, bufsize);
}

/* Parse "<view>-view-<column>[-<option>]" shorthands. */
enum status_code
parse_view_column_config(const char *view_name, enum view_column_type type, const char *option_name, const char *argv[])
{
	struct view_column *columns = get_view_column_options(view_name);
	struct view_column *column;
	const struct column_option_def *defs = column_option_defs[type].opts;
	size_t count = column_option_defs[type].count;
	size_t i;

	for (column = columns; column; column = column->next)
		if (column->type == type)
			break;
	if (!column)
		return error("The %s view does not have a %s column", view_name, view_column_name(type));

	if (!option_name || !*option_name) {
		/* display option */
		return parse_column_option_value(column, &defs[0], argv[0]);
	}

	for (i = 0; i < count; i++) {
		if (enum_equals(defs[i].name, strlen(defs[i].name), option_name, strlen(option_name)))
			return parse_column_option_value(column, &defs[i], argv[0]);
	}
	return error("Unknown option `%s' for column %s", option_name, view_column_name(type));
}

static enum status_code
parse_view_config_name(const char *name, const char *argv[], int argc)
{
	/* name is like main-view-date-format */
	int i;

	for (i = 0; i < ARRAY_SIZE(view_settings); i++) {
		const char *vname = view_settings[i].name;
		size_t vlen = strlen(vname);

		if (!strncmp(name, vname, vlen) && name[vlen] == '-') {
			const char *rest = name + vlen + 1;
			char view[SIZEOF_STR];
			int j;

			string_ncopy(view, vname, vlen - STRING_SIZE("-view"));
			/* Find column type: longest match */
			for (j = 0; j < view_column_type_map->size; j++) {
				const struct enum_map_entry *entry = &view_column_type_map->entries[j];

				if (!strncmp(rest, entry->name, entry->namelen) &&
				    (rest[entry->namelen] == 0 || rest[entry->namelen] == '-')) {
					const char *opt = rest[entry->namelen] ? rest + entry->namelen + 1 : "";

					if (!(view_settings[i].supported & (1 << entry->value)))
						return error("The %s view does not support %s column", view, entry->name);
					if (argc < 1)
						return error("No value assigned to %s", name);
					if (argc > 1)
						return error("Option %s only takes one value", name);
					return parse_view_column_config(view, entry->value, opt, argv);
				}
			}
			/* Fall back: treat as view spec */
			return parse_view_settings(view_settings[i].columns, vname, argv);
		}
	}

	return error("Unknown option name: %s", name);
}

enum status_code
set_option(const char *opt, int argc, const char *argv[])
{
	struct option_info *option = find_option_info(NULL, opt);

	if (option) {
		option->seen = true;
		return parse_option(option, "", argv, argc);
	}

	if (strstr(opt, "-view-"))
		return parse_view_config_name(opt, argv, argc);

	return error("Unknown option name: %s", opt);
}

enum status_code
option_set_command(int argc, const char *argv[])
{
	if (argc < 3)
		return ERROR_INVALID_SET_COMMAND;

	if (strcmp(argv[1], "="))
		return error("No value assigned to %s", argv[0]);

	return set_option(argv[0], argc - 2, argv + 2);
}

