static const char *
obsolete_replacement(const char *name, const char **message)
{
	static char buf[SIZEOF_STR];
	int i;

	for (i = 0; i < ARRAY_SIZE(obsolete_requests); i++) {
		if (enum_equals(obsolete_requests[i].name, strlen(obsolete_requests[i].name), name, strlen(name))) {
			const char *msg = obsolete_requests[i].message;
			const char *tick = strchr(msg, '`');

			*message = msg;
			if (tick) {
				const char *end = strchr(tick + 1, '\'');
				string_ncopy(buf, tick + 1, end ? end - tick - 1 : strlen(tick + 1));
				return buf;
			}
			if (!strcmp(obsolete_requests[i].name, "view-branch"))
				return "view-refs";
			return NULL;
		}
	}
	return NULL;
}

enum status_code
option_bind_command(int argc, const char *argv[])
{
	struct key key[16];
	size_t keys = 0;
	enum request request;
	struct keymap *keymap;
	const char *key_arg;
	const char *obsolete_msg = NULL;
	const char *replacement = NULL;

	if (argc < 3)
		return ERROR_INVALID_KEY_BINDING;

	if (!(keymap = get_keymap(argv[0], strlen(argv[0]))))
		return error("Unknown key map: %s", argv[0]);

	for (key_arg = argv[1]; *key_arg && keys < ARRAY_SIZE(key); keys++) {
		if (get_key_value(&key_arg, &key[keys]) < 0)
			return error("Unknown key mapping: %s", argv[1]);
	}

	if (*key_arg && keys == ARRAY_SIZE(key))
		return error("Except for <Esc> combos only one key is allowed "
			     "in key combos: %s", argv[1]);

	request = get_request(argv[2]);
	if (request == REQ_UNKNOWN) {
		replacement = obsolete_replacement(argv[2], &obsolete_msg);
		if (obsolete_msg) {
			if (replacement) {
				if (*replacement == ':') {
					char cmd[SIZEOF_STR];
					const char *cmd_argv[SIZEOF_ARGV];
					int cmd_argc = 0;

					string_ncopy(cmd, replacement, strlen(replacement));
					if (!argv_from_string(cmd_argv, &cmd_argc, cmd))
						return error("%s", obsolete_msg);
					add_run_request(keymap, key, keys, cmd_argv);
				} else {
					request = get_request(replacement);
					if (request != REQ_UNKNOWN)
						add_keybinding(keymap, request, key, keys);
				}
			}
			return error("%s", obsolete_msg);
		}
	}

	if (request == REQ_UNKNOWN) {
		struct run_request_flags flags;
		const char *first = argv[2];

		if (!strchr(":!?@<>+", *first))
			return error("Unknown command flag '%c'; expected one of :!?@<+>", *first);
		if (!parse_run_request_flags(&flags, argv + 2))
			return error("Unknown command flag '%c'; expected one of :!?@<+>", *first);
		request = add_run_request(keymap, key, keys, argv + 2);
		if (request == REQ_NONE)
			return ERROR_OUT_OF_MEMORY;
		return SUCCESS;
	}

	add_keybinding(keymap, request, key, keys);

	return SUCCESS;
}

/*
 * Color command
 */

static enum status_code
parse_color(int *color, const char *arg)
{
	int value;

	if (map_enum(color, color_map, arg))
		return SUCCESS;

	if (!prefixcmp(arg, "color")) {
		arg += STRING_SIZE("color");
	}
	if (!string_isnumber(arg))
		return error("Unknown color: %s", arg);
	value = atoi(arg);
	if (value < 0 || value >= 256)
		return error("Unknown color: %s", arg);
	*color = value;
	return SUCCESS;
}

static enum status_code
parse_attr(int *attr, const char *arg)
{
	int value;

	if (!map_enum(&value, attr_map, arg))
		return error("Unknown color attribute: %s", arg);
	*attr |= value;
	return SUCCESS;
}

enum status_code
option_color_command(int argc, const char *argv[])
{
	struct line_info *info = NULL;
	const char *keymap_name = NULL;
	char keymap_buf[SIZEOF_STR];
	const char *area = argv[0];
	enum status_code code;
	int fg, bg, attr = 0;
	int i;

	if (argc < 3)
		return ERROR_INVALID_COLOR_MAPPING;

	/* view-specific prefix: "view.name" where view is a keymap */
	{
		const char *dot = strchr(area, '.');

		if (dot && area[0] != '"' && area[0] != '\'' && area[0] != '/') {
			struct keymap *keymap;

			string_ncopy(keymap_buf, area, dot - area);
			keymap = get_keymap(keymap_buf, strlen(keymap_buf));
			if (!keymap)
				return error("Unknown key map: %s", keymap_buf);
			keymap_name = keymap->name;
			area = dot + 1;
		}
	}

	if (*area == '"' || *area == '\'') {
		size_t arealen = strlen(area);
		char quote = *area;
		const char *line = area + 1;
		size_t linelen = arealen > 1 && area[arealen - 1] == quote ? arealen - 2 : arealen - 1;
		bool is_regex = linelen > 1 && line[0] == '/' && line[linelen - 1] == '/';
		regex_t *regex = NULL;

		if (is_regex) {
			char pattern[SIZEOF_STR];
			int err;

			line++;
			linelen -= 2;
			string_ncopy(pattern, line, linelen);
			regex = calloc(1, sizeof(*regex));
			err = regcomp(regex, pattern, REG_EXTENDED);
			if (err) {
				char buf[SIZEOF_STR];

				regerror(err, regex, buf, sizeof(buf));
				free(regex);
				return error("Invalid color mapping: %s", buf);
			}
		}

		info = find_line_info(NULL, line, linelen, true);
		if (!info) {
			info = add_line_info(NULL, 0, line, linelen);
			if (!info)
				return ERROR_OUT_OF_MEMORY;
			info->regex = regex;
		} else if (regex) {
			regfree(regex);
			free(regex);
		}
	} else {
		info = find_line_info(NULL, area, strlen(area), false);
		if (!info) {
			/* Obsolete names */
			static const struct { const char *name; const char *repl; const char *quoted; } obsolete[] = {
				{ "diff-deleted-file-mode", "'deleted file mode '", "deleted file mode " },
				{ "diff-dissimilarity", "'dissimilarity '", "dissimilarity " },
				{ "diff-copy-from", "'copy from '", "copy from " },
				{ "diff-copy-to", "'copy to '", "copy to " },
				{ "diff-rename-from", "'rename from '", "rename from " },
				{ "diff-rename-to", "'rename to '", "rename to " },
				{ "diff-tree", "'diff-tree '", "diff-tree " },
				{ "pp-author", "'Author: '", "Author: " },
				{ "pp-commit", "'Commit: '", "Commit: " },
				{ "pp-date", "'Date: '", "Date: " },
				{ "pp-adate", "'AuthorDate: '", "AuthorDate: " },
				{ "pp-cdate", "'CommitDate: '", "CommitDate: " },
				{ "signoff", "'    Signed-off-by'", "    Signed-off-by" },
				{ "acked", "'    Acked-by'", "    Acked-by" },
				{ "reviewed", "'    Reviewed-by'", "    Reviewed-by" },
				{ "tested", "'    Tested-by'", "    Tested-by" },
				{ "tree-dir", "tree.directory", NULL },
				{ "tree-file", "tree.file", NULL },
				{ "tree-head", "tree.header", NULL },
			};
			int j;

			for (j = 0; j < ARRAY_SIZE(obsolete); j++) {
				if (enum_equals(obsolete[j].name, strlen(obsolete[j].name), area, strlen(area))) {
					if (keymap_name)
						return error("Unknown color name: %s.%s", keymap_name, area);
					return error("%s has been replaced by %s", area, obsolete[j].repl);
				}
			}
			if (keymap_name)
				return error("Unknown color name: %s.%s", keymap_name, area);
			return error("Unknown color name: %s", area);
		}
	}

	if (keymap_name) {
		struct line_info *vinfo;

		for (vinfo = info->next; vinfo; vinfo = vinfo->next)
			if (vinfo->keymap && !strcasecmp(vinfo->keymap, keymap_name))
				break;
		if (!vinfo)
			vinfo = add_view_line_info(info, keymap_name);
		if (!vinfo)
			return ERROR_OUT_OF_MEMORY;
		info = vinfo;
	}

	code = parse_color(&fg, argv[1]);
	if (code != SUCCESS)
		return code;
	code = parse_color(&bg, argv[2]);
	if (code != SUCCESS)
		return code;

	for (i = 3; i < argc; i++) {
		code = parse_attr(&attr, argv[i]);
		if (code != SUCCESS)
			return code;
	}

	info->fg = fg;
	info->bg = bg;
	info->attr = attr;
	return SUCCESS;
}

/*
 * Source / config loading
 */

static enum status_code
set_option_command(int argc, const char *argv[])
{
	return option_set_command(argc, argv);
}

static int config_lineno;
static bool config_errors;
static const char *config_path;

enum status_code
option_source_command(int argc, const char *argv[])
{
	enum status_code code;
	bool quiet = false;

	if (argc > 0 && !strcmp(argv[0], "-q")) {
		quiet = true;
		argv++;
		argc--;
	}

	if (argc < 1 || argc > 1)
		return error("Invalid source command: source [-q] <path>");

	code = load_option_file(argv[0]);
	if (code == ERROR_CUSTOM && quiet)
		return SUCCESS;
	return code;
}

static enum status_code
run_option_command(int argc, const char *argv[])
{
	if (!strcmp(argv[0], "set"))
		return option_set_command(argc - 1, argv + 1);
	if (!strcmp(argv[0], "bind"))
		return option_bind_command(argc - 1, argv + 1);
	if (!strcmp(argv[0], "color"))
		return option_color_command(argc - 1, argv + 1);
	if (!strcmp(argv[0], "source"))
		return option_source_command(argc - 1, argv + 1);
	return error("Unknown option command: %s", argv[0]);
}

static enum status_code
read_option(char *opt, size_t optlen, char *value, size_t valuelen, void *data)
{
	const char *argv[SIZEOF_ARGV];
	int argc = 0;
	enum status_code status;

	config_lineno++;

	/* Check for comment markers, since read_properties() will
	 * only ensure opt and value are split at first " \t". */
	optlen = strcspn(opt, "#");
	if (optlen == 0)
		return SUCCESS;

	if (opt[optlen] == 0) {
		/* Look for comment endings in the value. */
		size_t len = strcspn(value, "#");

		if (len < valuelen) {
			valuelen = len;
			value[valuelen] = 0;
		}
	}

	value = chomp_string(value);
	if (!argv_from_string(argv, &argc, value))
		status = error("Too many option arguments for %s", opt);
	else
		status = run_option_command_opt(opt, argc, argv);

	if (status != SUCCESS) {
		warn("%s:%d: %s", config_path, config_lineno, get_status_message(status));
		config_errors = true;
	}

	/* Always keep going if errors are encountered. */
	return SUCCESS;
}

static enum status_code
run_option_command_opt(const char *opt, int argc, const char *argv[])
{
	if (!strcmp(opt, "set"))
		return option_set_command(argc, argv);
	if (!strcmp(opt, "bind"))
		return option_bind_command(argc, argv);
	if (!strcmp(opt, "color"))
		return option_color_command(argc, argv);
	if (!strcmp(opt, "source"))
		return option_source_command(argc, argv);
	return error("Unknown option command: %s", opt);
}

static bool
read_option_line(char *name, size_t namelen, char *value, size_t valuelen, void *data)
{
	return read_option(name, namelen, value, valuelen, data) == SUCCESS;
}

static enum status_code
load_option_io(struct io *io, const char *path)
{
	const char *saved_path = config_path;
	int saved_lineno = config_lineno;
	bool saved_errors = config_errors;
	enum status_code code;

	config_path = path;
	config_lineno = 0;
	config_errors = false;

	{
		/* Handle multi-line commands terminated by backslash. */
		char *line;
		char buf[SIZEOF_STR * 4] = "";
		size_t bufpos = 0;
		bool continued = false;

		while ((line = io_get(io, '\n', true))) {
			size_t len;
			char *tmp;

			config_lineno++;
			tmp = chomp_string(line);
			len = strlen(tmp);
			if (len && tmp[len - 1] == '\\') {
				tmp[len - 1] = 0;
				string_nformat(buf, sizeof(buf), &bufpos, "%s", tmp);
				continued = true;
				continue;
			}
			if (continued) {
				string_nformat(buf, sizeof(buf), &bufpos, "%s", tmp);
				tmp = buf;
				continued = false;
			}
			{
				char *opt = chomp_string(tmp);
				size_t optlen = strcspn(opt, " \t");
				char *value;
				size_t valuelen;

				if (opt[optlen]) {
					opt[optlen] = 0;
					value = chomp_string(opt + optlen + 1);
				} else {
					value = "";
				}
				valuelen = strlen(value);
				config_lineno--;
				read_option(opt, optlen, value, valuelen, NULL);
			}
			bufpos = 0;
			buf[0] = 0;
		}
		io_done(io);
	}

	code = config_errors ? error("Errors while loading %s.", path) : SUCCESS;

	config_path = saved_path;
	config_lineno = saved_lineno;
	config_errors = saved_errors;

	return code;
}

enum status_code
load_option_file(const char *path)
{
	struct io io;
	char buf[SIZEOF_STR];

	/* Expand ~ */
	if (path[0] == '~' && (path[1] == '/' || path[1] == 0)) {
		const char *home = getenv("HOME");

		if (home) {
			string_format(buf, "%s%s", home, path + 1);
			path = buf;
		}
	}

	if (!io_open(&io, "%s", path))
		return error("File does not exist: %s", path);

	return load_option_io(&io, path);
}

static enum status_code
load_builtin_config(void);

const char *default_system_tigrc = "/etc/tigrc";

/*
 * Git config
 */

static int
read_git_color_option(const char *name, char *value)
{
	return 0;
}

static enum status_code
set_git_color_option(const char *name, char *value)
{
	const char *argv[SIZEOF_ARGV];
	int argc = 0;
	int i;

	if (!opt_git_colors)
		return SUCCESS;

	for (i = 0; opt_git_colors[i]; i++) {
		const char *mapping = opt_git_colors[i];
		const char *eq = strchr(mapping, '=');

		if (!eq)
			continue;
		if (strncasecmp(mapping, name, eq - mapping) || name[eq - mapping])
			continue;
		{
			char tmp[SIZEOF_STR];
			const char *cargv[SIZEOF_ARGV + 1];
			int cargc = 0, j;

			string_ncopy(tmp, value, strlen(value));
			if (!argv_from_string(argv, &argc, tmp))
				return SUCCESS;
			cargv[cargc++] = eq + 1;
			for (j = 0; j < argc && cargc < SIZEOF_ARGV; j++)
				cargv[cargc++] = argv[j];
			cargv[cargc] = NULL;
			if (cargc >= 3 || cargc == 2) {
				/* Git colors: "fg [bg] [attrs]"; for one value treat bg as default */
				const char *fixed[SIZEOF_ARGV + 2];
				int fc = 0;

				fixed[fc++] = cargv[0];
				fixed[fc++] = cargv[1];
				if (cargc == 2) {
					fixed[fc++] = "default";
				} else {
					int k;
					/* Git color syntax: fg bg attrs...; but attrs may appear as second value */
					for (k = 2; k < cargc; k++)
						fixed[fc++] = cargv[k];
				}
				fixed[fc] = NULL;
				option_color_command(fc, fixed);
			}
		}
	}
	return SUCCESS;
}

static enum status_code
set_encoding(char *opt, const char *arg, size_t optsize)
{
	parse_string(opt, arg, optsize);
	if (!strcasecmp(opt, "utf-8") || !strcasecmp(opt, "utf8"))
		string_ncopy_do(opt, optsize, "UTF-8", 5);
	return SUCCESS;
}

enum status_code
set_repo_config_option(char *name, char *value, option_fn cmd)
{
	const char *argv[SIZEOF_ARGV] = { name, "=" };
	int argc = 1 + (cmd == option_set_command);
	enum status_code code;

	if (!argv_from_string(argv, &argc, value))
		code = error("Too many arguments");
	else
		code = cmd(argc, argv);

	return code;
}

static enum status_code
set_option_fn(const char *argv[])
{
	return SUCCESS;
}

static bool
read_repo_config_option(char *name, size_t namelen, char *value, size_t valuelen, void *data)
{
	if (!strcmp(name, "i18n.commitencoding"))
		set_encoding(opt_encoding, value, sizeof(opt_encoding));

	else if (!strcmp(name, "gui.encoding"))
		set_encoding(opt_encoding, value, sizeof(opt_encoding));

	else if (!strcmp(name, "core.editor"))
		string_ncopy(opt_editor, value, valuelen);

	else if (!strcmp(name, "core.worktree"))
		string_ncopy(repo.worktree, value, valuelen);

	else if (!strcmp(name, "core.abbrev"))
		parse_int(&opt_core_abbrev, value, 0, 40);

	else if (!prefixcmp(name, "tig.color."))
		set_repo_config_option(name + 10, value, (option_fn) option_color_command_wrap);

	else if (!prefixcmp(name, "tig.bind."))
		set_repo_config_option(name + 9, value, (option_fn) option_bind_command_wrap);

	else if (!prefixcmp(name, "tig."))
		set_repo_config_option(name + 4, value, (option_fn) option_set_command_wrap);

	else if (!prefixcmp(name, "color."))
		set_git_color_option(name + STRING_SIZE("color."), value);

	else if (*repo.head && !prefixcmp(name, "branch.") &&
		 !strncmp(name + 7, repo.head, strlen(repo.head)))
		set_remote_branch(name + 7 + strlen(repo.head), value, valuelen);

	return true;
}

