static bool
save_option_settings(FILE *file)
{
	char buf[SIZEOF_STR * 4];
	int i;

	if (fprintf(file, "\n## Settings\n\n") < 0)
		return false;

	for (i = 0; i < ARRAY_SIZE(option_info); i++) {
		struct option_info *option = &option_info[i];

		if (!strcmp(option->name, "file-args") || !strcmp(option->name, "rev-args") ||
		    !strcmp(option->name, "cmdline-args"))
			continue;

		buf[0] = 0;
		format_option(option, buf, sizeof(buf));
		if (fprintf(file, "set %-26s = %s\n", option->name, buf) < 0)
			return false;
	}

	return true;
}

