static enum status_code
toggle_bool(bool *opt, const char *name, char *msg, size_t msgsize)
{
	*opt = !*opt;
	string_nformat(msg, msgsize, NULL, ":set %s = %s", name, *opt ? "yes" : "no");
	return SUCCESS;
}

static enum status_code
toggle_int(int *opt, const char *name, const char *arg, int min, int max, char *msg, size_t msgsize)
{
	if (arg) {
		int value = atoi(arg);

		if (!value && !strchr("-+", *arg) && !isdigit((unsigned char) *arg))
			return error("Invalid step value: %s", arg);
		if (*arg == '-' || *arg == '+')
			value = *opt + value;
		if (value < min || value > max)
			return error("Value must be between %d and %d", min, max);
		*opt = value;
	} else {
		*opt = *opt ? 0 : 1;
	}
	string_nformat(msg, msgsize, NULL, ":set %s = %d", name, *opt);
	return SUCCESS;
}

static enum status_code
toggle_enum(int *opt, const char *name, const struct enum_map *map, const char *arg, char *msg, size_t msgsize)
{
	int i;

	if (arg) {
		int value;

		if (!map_enum(&value, map, arg))
			return error("'%s' is not a valid value for %s", arg, name);
		*opt = value;
	} else {
		*opt = (*opt + 1) % map->size;
	}
	for (i = 0; i < map->size; i++)
		if (map->entries[i].value == *opt) {
			string_nformat(msg, msgsize, NULL, ":set %s = %s", name, map->entries[i].name);
			break;
		}
	return SUCCESS;
}

static enum status_code
toggle_column_option(struct view_column *column, const char *view_name, const struct column_option_def *def, const char *arg, char *msg, size_t msgsize)
{
	void *ptr = column_opt_ptr(column, def);
	char name[SIZEOF_STR];

	string_format(name, "%s-view-%s-%s", view_name, view_column_name(column->type), def->name);

	switch (def->type) {
	case COPT_BOOL:
		return toggle_bool((bool *) ptr, name, msg, msgsize);
	case COPT_INT:
	case COPT_INT_OR_PERCENT:
	case COPT_BOOL_OR_INT:
		return toggle_int((int *) ptr, name, arg, def->min, def->max, msg, msgsize);
	case COPT_ENUM:
	case COPT_DATE_DISPLAY:
	case COPT_GRAPH:
		return toggle_enum((int *) ptr, name, def->map, arg, msg, msgsize);
	case COPT_STRING:
		if (!arg)
			return error("Cannot toggle %s", name);
		parse_string((char *) ptr, arg, SIZEOF_STR);
		string_nformat(msg, msgsize, NULL, ":set %s = \"%s\"", name, (char *) ptr);
		return SUCCESS;
	}
	return SUCCESS;
}

/* name is e.g. "date", "author-display", "commit-title-graph", "line-number-interval" */
enum status_code
toggle_option(struct view_column **columns, const char *view_name, const char *name, const char *argv[], char *msg, size_t msgsize)
{
	struct option_info *option;
	const char *arg = argv && argv[0] ? argv[0] : NULL;
	int i;

	if (!name || !*name)
		return error("No option name given to :toggle");

	/* View column options */
	if (columns) {
		/* Column name alone => display option. */
		for (i = 0; i < view_column_type_map->size; i++) {
			const struct enum_map_entry *entry = &view_column_type_map->entries[i];
			struct view_column *column;
			size_t namelen = strlen(name);
			const char *suffix = NULL;

			if (enum_equals(entry->name, entry->namelen, name, namelen)) {
				suffix = "display";
			} else if (namelen > entry->namelen + 1 && !strncmp(name, entry->name, entry->namelen) && name[entry->namelen] == '-') {
				suffix = name + entry->namelen + 1;
			} else if (!strcmp(name, "author-display") || !strcmp(name, "date-display")) {
				/* handled above */
			}
			if (!suffix)
				continue;

			for (column = *columns; column; column = column->next)
				if (column->type == entry->value)
					break;
			if (!column) {
				/* Not in this view: check other names like "show-..." below */
				if (!strcmp(suffix, "display") || true) {
					/* Check if the option exists at all for this column type */
					const struct column_option_def *defs = column_option_defs[entry->value].opts;
					size_t count = column_option_defs[entry->value].count;
					size_t j;
					bool known = false;

					for (j = 0; j < count; j++)
						if (enum_equals(defs[j].name, strlen(defs[j].name), suffix, strlen(suffix)))
							known = true;
					if (known)
						return error("Toggling of %s is not supported in this view", name);
				}
				continue;
			}

			{
				const struct column_option_def *defs = column_option_defs[column->type].opts;
				size_t count = column_option_defs[column->type].count;
				size_t j;

				for (j = 0; j < count; j++)
					if (enum_equals(defs[j].name, strlen(defs[j].name), suffix, strlen(suffix)))
						return toggle_column_option(column, view_name, &defs[j], arg, msg, msgsize);
			}
		}
	}

	option = find_option_info(NULL, name);
	if (!option) {
		/* "show-" prefixed names */
		if (!prefixcmp(name, "show-"))
			option = find_option_info(NULL, name + 5);
	}
	if (!option) {
		/* Check if it's a column toggle not supported by this view */
		for (i = 0; i < view_column_type_map->size; i++) {
			const struct enum_map_entry *entry = &view_column_type_map->entries[i];

			if (enum_equals(entry->name, entry->namelen, name, strlen(name)) ||
			    (!strncmp(name, entry->name, entry->namelen) && name[entry->namelen] == '-'))
				return error("Toggling of %s is not supported in this view", name);
		}
		return error("`:toggle %s` not supported", name);
	}

	switch (option->type) {
	case OPT_BOOL:
	case OPT_SHOW_NOTES:
		return toggle_bool(option->value, option->name, msg, msgsize);
	case OPT_INT:
	case OPT_ID_WIDTH:
		return toggle_int(option->value, option->name, arg, option->min, option->max, msg, msgsize);
	case OPT_ENUM:
	case OPT_COMMIT_ORDER:
		return toggle_enum(option->value, option->name, option->map, arg, msg, msgsize);
	case OPT_DOUBLE:
		{
			double *opt = option->value;

			if (!arg)
				return error("Cannot toggle %s", option->name);
			{
				double step;
				enum status_code code = parse_step(&step, arg + (*arg == '-' || *arg == '+'));

				if (code != SUCCESS)
					return code;
				if (*arg == '-')
					*opt -= step;
				else if (*arg == '+')
					*opt += step;
				else
					*opt = step;
				if (*opt < 0)
					*opt = 0;
			}
			{
				char buf[SIZEOF_STR];

				format_option(option, buf, sizeof(buf));
				string_nformat(msg, msgsize, NULL, ":set %s = %s", option->name, buf);
			}
			return SUCCESS;
		}
	case OPT_ARGS:
		{
			const char ***args = option->value;
			char buf[SIZEOF_STR];

			if (!arg)
				return error("Cannot toggle %s", option->name);
			if (argv_contains(*args, arg)) {
				const char **tmp = NULL;
				int j;

				for (j = 0; (*args)[j]; j++)
					if (strcmp((*args)[j], arg))
						argv_append(&tmp, (*args)[j]);
				argv_free(*args);
				free(*args);
				*args = tmp;
			} else {
				argv_append(args, arg);
			}
			buf[0] = 0;
			if (*args)
				argv_to_string(*args, buf, sizeof(buf), " ");
			string_nformat(msg, msgsize, NULL, ":set %s = %s", option->name, buf);
			return SUCCESS;
		}
	default:
		return error("`:toggle %s` not supported", name);
	}
}

