static int config_lineno;
static bool config_errors;
static const char *config_path;

static enum status_code
run_option_command_opt(const char *opt, int argc, const char *argv[])
{
	if (!strcmp(opt, "set"))
		return option_set_command(argc, argv);
	if (!strcmp(opt, "bind"))
		return option_bind_command(argc, argv);
	if (!strcmp(opt, "color"))
		return option_color_command(argc, argv);
	if (!strcmp(opt, "source"))
		return option_source_command(argc, argv);
	return error("Unknown option command: %s", opt);
}

enum status_code
option_source_command(int argc, const char *argv[])
{
	enum status_code code;
	bool quiet = false;

	if (argc > 0 && !strcmp(argv[0], "-q")) {
		quiet = true;
		argv++;
		argc--;
	}

	if (argc != 1)
		return error("Invalid source command: source [-q] <path>");

	code = load_option_file(argv[0]);
	if (code != SUCCESS && quiet && !strncmp(config_msg, "File does not exist", 19))
		return SUCCESS;
	return code;
}

static void
read_option_line(char *line)
{
	const char *argv[SIZEOF_ARGV];
	int argc = 0;
	enum status_code status;
	char *opt, *value;
	size_t optlen;

	opt = chomp_string(line);
	optlen = strcspn(opt, " \t");
	if (opt[optlen]) {
		opt[optlen] = 0;
		value = chomp_string(opt + optlen + 1);
	} else {
		value = opt + optlen;
	}

	/* Check for comment markers. */
	optlen = strcspn(opt, "#");
	if (optlen == 0)
		return;
	if (opt[optlen] == 0) {
		char *hash = value;
		bool quoted = false;
		char quote = 0;

		/* Look for comment endings in the value, skipping quoted strings. */
		for (; *hash; hash++) {
			if (quoted) {
				if (*hash == quote)
					quoted = false;
			} else if (*hash == '"' || *hash == '\'') {
				quoted = true;
				quote = *hash;
			} else if (*hash == '#') {
				*hash = 0;
				break;
			}
		}
	} else {
		opt[optlen] = 0;
		value = opt + optlen;
	}

	value = chomp_string(value);
	if (!argv_from_string(argv, &argc, value))
		status = error("Too many option arguments for %s", opt);
	else
		status = run_option_command_opt(opt, argc, argv);

	if (status != SUCCESS) {
		warn("%s:%d: %s", config_path, config_lineno, get_status_message(status));
		config_errors = true;
	}
}

static enum status_code
load_option_io(struct io *io, const char *path)
{
	const char *saved_path = config_path;
	int saved_lineno = config_lineno;
	bool saved_errors = config_errors;
	enum status_code code;
	char *line;
	char buf[SIZEOF_STR * 8] = "";
	size_t bufpos = 0;
	bool continued = false;
	int start_lineno = 0;

	config_path = path;
	config_lineno = 0;
	config_errors = false;

	while ((line = io_get(io, '\n', true))) {
		size_t len;
		char *tmp;

		config_lineno++;
		tmp = line;
		len = strlen(tmp);
		while (len && (tmp[len - 1] == '\r' || tmp[len - 1] == ' ' || tmp[len - 1] == '\t'))
			tmp[--len] = 0;
		if (len && tmp[len - 1] == '\\') {
			tmp[len - 1] = 0;
			if (!continued)
				start_lineno = config_lineno;
			string_nformat(buf, sizeof(buf), &bufpos, "%s", tmp);
			continued = true;
			continue;
		}
		if (continued) {
			int saved = config_lineno;

			string_nformat(buf, sizeof(buf), &bufpos, "%s", tmp);
			config_lineno = start_lineno;
			read_option_line(buf);
			config_lineno = saved;
			continued = false;
			bufpos = 0;
			buf[0] = 0;
			continue;
		}
		read_option_line(tmp);
	}
	io_done(io);

	code = config_errors ? error("Errors while loading %s.", path) : SUCCESS;

	config_path = saved_path;
	config_lineno = saved_lineno;
	config_errors = saved_errors;

	return code;
}

enum status_code
load_option_file(const char *path)
{
	struct io io;
	char buf[SIZEOF_STR];
	struct stat st;

	/* Expand ~ */
	if (path[0] == '~' && (path[1] == '/' || path[1] == 0)) {
		const char *home = getenv("HOME");

		if (home) {
			string_format(buf, "%s%s", home, path + 1);
			path = buf;
		}
	}

	if (stat(path, &st) < 0 || !io_open(&io, "%s", path))
		return error("File does not exist: %s", path);

	return load_option_io(&io, path);
}

