/*
 * Git config
 */

static enum status_code
option_color_command_fn(int argc, const char *argv[])
{
	return option_color_command(argc, argv);
}

static enum status_code
set_git_color_option(const char *name, char *value)
{
	const char *argv[SIZEOF_ARGV];
	int argc = 0;
	int i;

	if (!opt_git_colors)
		return SUCCESS;

	for (i = 0; opt_git_colors[i]; i++) {
		const char *mapping = opt_git_colors[i];
		const char *eq = strchr(mapping, '=');
		char tmp[SIZEOF_STR];
		const char *cargv[SIZEOF_ARGV + 2];
		int cargc = 0, j;

		if (!eq)
			continue;
		if (strncasecmp(mapping, name, eq - mapping) || name[eq - mapping])
			continue;

		string_ncopy(tmp, value, strlen(value));
		argc = 0;
		if (!argv_from_string(argv, &argc, tmp))
			continue;
		cargv[cargc++] = eq + 1;
		for (j = 0; j < argc && cargc < SIZEOF_ARGV; j++)
			cargv[cargc++] = argv[j];
		if (cargc == 2)
			cargv[cargc++] = "default";
		cargv[cargc] = NULL;
		if (cargc >= 3)
			option_color_command(cargc, cargv);
	}
	return SUCCESS;
}

static void
set_encoding(char *opt, const char *arg, size_t optsize)
{
	parse_string(opt, arg, optsize);
	if (!strcasecmp(opt, "utf-8") || !strcasecmp(opt, "utf8"))
		string_ncopy_do(opt, optsize, "UTF-8", 5);
}

enum status_code
set_repo_config_option(char *name, char *value, option_fn cmd)
{
	(void) name; (void) value; (void) cmd;
	return SUCCESS;
}

static void
run_repo_config_command(const char *name, char *value, enum status_code (*cmd)(int, const char *[]), bool set)
{
	const char *argv[SIZEOF_ARGV];
	int argc = 0;

	argv[argc++] = name;
	if (set)
		argv[argc++] = "=";
	if (!argv_from_string(argv, &argc, value))
		return;
	cmd(argc, argv);
}

static void
set_remote_branch(const char *name, const char *value, size_t valuelen)
{
	if (!strcmp(name, ".remote")) {
		string_ncopy(repo.remote, value, valuelen);

	} else if (*repo.remote && !strcmp(name, ".merge")) {
		size_t from = strlen(repo.remote);

		if (!prefixcmp(value, "refs/heads/"))
			value += STRING_SIZE("refs/heads/");

		if (!string_format_from(repo.remote, &from, "/%s", value))
			repo.remote[0] = 0;
		string_ncopy(repo.upstream, repo.remote, strlen(repo.remote));
	}
}

static bool
read_repo_config_option(char *name, size_t namelen, char *value, size_t valuelen, void *data)
{
	if (!strcmp(name, "i18n.commitencoding"))
		set_encoding(opt_encoding, value, sizeof(opt_encoding));

	else if (!strcmp(name, "gui.encoding"))
		set_encoding(opt_encoding, value, sizeof(opt_encoding));

	else if (!strcmp(name, "core.editor"))
		string_ncopy(opt_editor, value, valuelen);

	else if (!strcmp(name, "core.worktree"))
		string_ncopy(repo.worktree, value, valuelen);

	else if (!strcmp(name, "core.abbrev"))
		parse_int(&opt_core_abbrev, value, 0, 40);

	else if (!prefixcmp(name, "tig.color."))
		run_repo_config_command(name + 10, value, option_color_command, false);

	else if (!prefixcmp(name, "tig.bind."))
		run_repo_config_command(name + 9, value, option_bind_command, false);

	else if (!prefixcmp(name, "tig."))
		run_repo_config_command(name + 4, value, option_set_command, true);

	else if (!prefixcmp(name, "color."))
		set_git_color_option(name + STRING_SIZE("color."), value);

	else if (*repo.head && !prefixcmp(name, "branch.") &&
		 !strncmp(name + 7, repo.head, strlen(repo.head)))
		set_remote_branch(name + 7 + strlen(repo.head), value, valuelen);

	return true;
}

int
load_git_config(void)
{
	const char *config_list_argv[] = { "git", "config", "--list", NULL };
	struct io io;

	return io_run_load(&io, config_list_argv, "=", read_repo_config_option, NULL);
}

