int
load_options(void)
{
	const char *tigrc_user = getenv("TIGRC_USER");
	const char *tigrc_system = getenv("TIGRC_SYSTEM");
	const char *tig_diff_opts = getenv("TIG_DIFF_OPTS");
	const bool diff_opts_from_args = !!opt_diff_options;
	bool custom_tigrc_system = !!tigrc_system;
	char buf[SIZEOF_STR];

	init_option_defaults();

	if (!custom_tigrc_system)
		tigrc_system = default_system_tigrc;

	if (!*tigrc_system ||
	    (load_option_file(tigrc_system) == ERROR_CUSTOM && !custom_tigrc_system)) {
		enum status_code code = load_builtin_config();

		if (code != SUCCESS)
			die("Error in built-in config");
	}

	if (!tigrc_user) {
		const char *xdg_config_home = getenv("XDG_CONFIG_HOME");
		const char *home = getenv("HOME");

		if (xdg_config_home && *xdg_config_home) {
			string_format(buf, "%s/tig/config", xdg_config_home);
			tigrc_user = buf;
		} else if (home) {
			struct stat st;

			string_format(buf, "%s/.config/tig/config", home);
			if (stat(buf, &st) < 0)
				string_format(buf, "%s/.tigrc", home);
			tigrc_user = buf;
		}
	}
	if (tigrc_user && *tigrc_user) {
		struct stat st;

		if (stat(tigrc_user, &st) == 0)
			load_option_file(tigrc_user);
	}

	if (!diff_opts_from_args && tig_diff_opts && *tig_diff_opts) {
		static const char *diff_opts[SIZEOF_ARG] = { NULL };
		char buf2[SIZEOF_STR];
		int argc = 0;

		string_ncopy(buf2, tig_diff_opts, strlen(tig_diff_opts));
		if (!argv_from_string(diff_opts, &argc, buf2))
			die("TIG_DIFF_OPTS contains too many arguments");
		else if (!argv_copy(&opt_diff_options, diff_opts))
			die("Failed to format TIG_DIFF_OPTS arguments");
	}

	return SUCCESS;
}

/*
 * Save options
 */

static bool
save_option_settings(FILE *file)
{
	char buf[SIZEOF_STR * 4];
	int i;

	if (fprintf(file, "\n## Settings\n\n") < 0)
		return false;

	for (i = 0; i < ARRAY_SIZE(option_info); i++) {
		struct option_info *option = &option_info[i];

		if (!strcmp(option->name, "file-args") || !strcmp(option->name, "rev-args") ||
		    !strcmp(option->name, "cmdline-args"))
			continue;

		buf[0] = 0;
		format_option(option, buf, sizeof(buf));
		if (fprintf(file, "set %-26s = %s\n", option->name, buf) < 0)
			return false;
	}

	return true;
}

struct save_keys_data {
	FILE *file;
	const char *group;
	struct keymap *keymap;
	bool ok;
};

static bool
save_option_keybinding(void *data, const char *group, struct keymap *keymap,
		       enum request request, const char *key,
		       const struct request_info *req_info, const struct run_request *run_req)
{
	struct save_keys_data *skd = data;
	const char *sep;

	if (group != skd->group || keymap != skd->keymap) {
		skd->group = group;
		skd->keymap = keymap;
		if (fprintf(skd->file, "# %s\n", group) < 0)
			return skd->ok = false;
	}

	if (req_info) {
		if (fprintf(skd->file, "bind %-10s %-15s %s\n", keymap->name, key, enum_name(req_info->name)) < 0)
			return skd->ok = false;
	} else if (run_req) {
		char buf[SIZEOF_STR];
		const char *flags = format_run_request_flags(run_req);

		if (!argv_to_string(run_req->argv, buf, sizeof(buf), " "))
			return skd->ok = false;
		if (run_req->flags.internal) {
			if (fprintf(skd->file, "bind %-10s %-15s %s\n", keymap->name, key, buf) < 0)
				return skd->ok = false;
		} else {
			if (fprintf(skd->file, "bind %-10s %-15s %s%s\n", keymap->name, key, flags, buf) < 0)
				return skd->ok = false;
		}
	}

	(void) sep;
	return true;
}

static bool
save_option_keybindings(FILE *file)
{
	struct save_keys_data data = { file, NULL, NULL, true };

	if (fprintf(file, "\n## Keybindings\n\n") < 0)
		return false;

	foreach_key(save_option_keybinding, &data, false);
	return data.ok;
}

static const char *
color_name(int color, char *buf, size_t bufsize)
{
	int i;

	for (i = 0; i < color_map->size; i++)
		if (color_map->entries[i].value == color)
			return color_map->entries[i].name;
	string_nformat(buf, bufsize, NULL, "color%d", color);
	return buf;
}

static const char *
attr_names(int attr, char *buf, size_t bufsize)
{
	size_t pos = 0;
	int i;

	buf[0] = 0;
	for (i = 0; i < attr_map->size; i++) {
		int value = attr_map->entries[i].value;

		if (value && (attr & value) == value)
			string_nformat(buf, bufsize, &pos, "%s%s", pos ? " " : "", attr_map->entries[i].name);
	}
	return buf;
}

static bool
save_line_info(FILE *file, struct line_info *info, struct line_info *base)
{
	char name[SIZEOF_STR];
	char fg[32], bg[32], attr[SIZEOF_STR];
	const char *prefix = info->keymap ? info->keymap : "";
	const char *dot = info->keymap ? "." : "";

	if (base->prefix && *base->prefix)
		string_format(name, "%s%s\"%s\"", prefix, dot, base->prefix);
	else if (base->name)
		string_format(name, "%s%s%s", prefix, dot, enum_name(base->name));
	else
		string_format(name, "%s%s\"\"", prefix, dot);

	return fprintf(file, "color %-30s %-8s %-8s %s\n", name,
		       color_name(info->fg, fg, sizeof(fg)),
		       color_name(info->bg, bg, sizeof(bg)),
		       attr_names(info->attr, attr, sizeof(attr))) >= 0;
}

static bool
save_option_colors(FILE *file)
{
	size_t i, count = line_info_count();

	if (fprintf(file, "\n## Colors\n\n") < 0)
		return false;

	for (i = 0; i < count; i++) {
		struct line_info *base = get_base_line_info(i);
		struct line_info *info;

		for (info = base; info; info = info->next)
			if (!save_line_info(file, info, base))
				return false;
	}

	return true;
}

bool
save_options(const char *path)
{
	int fd = open(path, O_WRONLY | O_CREAT | O_EXCL, 0666);
	FILE *file;
	bool ok;

	if (fd < 0)
		return false;
	file = fdopen(fd, "w");
	if (!file) {
		close(fd);
		return false;
	}

	ok = fprintf(file, "# Saved by Tig\n") >= 0
	  && save_option_settings(file)
	  && save_option_keybindings(file)
	  && save_option_colors(file);

	fclose(file);
	return ok;
}

