#include "tig.h"

#define VIEW_MAX_LEN(view) ((view)->width + (view)->pos.col - (view)->col)

void
set_view_attr(struct view *view, enum line_type type)
{
	if (!view->curline->selected && view->curtype != type) {
		(void) wattrset(view->win, get_line_attr(view->keymap->name, type));
		wchgat(view->win, -1, 0, get_line_color(view->keymap->name, type), NULL);
		view->curtype = type;
	}
}

static size_t
string_expand(char *dst, size_t dstlen, const char *src, int srclen, int tabsize)
{
	size_t size, pos;

	for (size = pos = 0; size < dstlen - 1 && (srclen < 0 || pos < srclen) && src[pos]; pos++) {
		if (src[pos] == '\t') {
			size_t expanded = tabsize - (size % tabsize);

			if (expanded + size >= dstlen - 1)
				expanded = dstlen - size - 1;
			memcpy(dst + size, "        ", expanded);
			size += expanded;
		} else {
			dst[size++] = src[pos];
		}
	}

	dst[size] = 0;
	return pos;
}

bool
draw_chars(struct view *view, enum line_type type, const char *string, int length,
	   int max_width, bool use_tilde)
{
	int len = 0;
	int col = 0;
	int trimmed = false;
	size_t skip = view->pos.col > view->col ? view->pos.col - view->col : 0;

	if (max_width <= 0)
		return VIEW_MAX_LEN(view) <= 0;

	len = utf8_length(&string, length, skip, &col, max_width, &trimmed, use_tilde, opt_tab_size);

	set_view_attr(view, type);
	if (len > 0)
		waddnstr(view->win, string, len);

	if (trimmed && use_tilde) {
		set_view_attr(view, LINE_DELIMITER);
		if (!strcmp(opt_truncation_delimiter, "utf-8"))
			waddstr(view->win, "\xE2\x8B\xAF");
		else
			waddstr(view->win, opt_truncation_delimiter);
		col++;
	}

	view->col += col + skip;
	return VIEW_MAX_LEN(view) <= 0;
}

bool
draw_space(struct view *view, enum line_type type, int max_width, int spaces)
{
	static char space[] = "                    ";

	spaces = MIN(max_width, spaces);

	while (spaces > 0) {
		int len = MIN(spaces, sizeof(space) - 1);

		if (draw_chars(view, type, space, -1, len, false))
			return true;
		spaces -= len;
	}

	return VIEW_MAX_LEN(view) <= 0;
}

static bool
draw_text_expanded(struct view *view, enum line_type type, const char *string, int length, int max_width, bool use_tilde)
{
	static char text[SIZEOF_STR];

	do {
		size_t pos = string_expand(text, sizeof(text), string, length, opt_tab_size);

		if (draw_chars(view, type, text, -1, max_width, use_tilde))
			return true;
		string += pos;
		length -= pos;
	} while (*string && length > 0);

	return VIEW_MAX_LEN(view) <= 0;
}

static inline bool
draw_textn(struct view *view, enum line_type type, const char *string, int length)
{
	return draw_text_expanded(view, type, string, length, VIEW_MAX_LEN(view), false);
}

bool
draw_text(struct view *view, enum line_type type, const char *string)
{
	return draw_textn(view, type, string, -1);
}

bool
draw_text_overflow(struct view *view, enum line_type type, const char *text, bool on, int overflow)
{
	if (on) {
		int max = MIN(VIEW_MAX_LEN(view), overflow);
		int len = strlen(text);

		if (draw_text_expanded(view, type, text, -1, max, false))
			return true;

		text = len > overflow ? text + overflow : "";
		type = LINE_OVERFLOW;
	}

	if (*text && draw_text(view, type, text))
		return true;

	return VIEW_MAX_LEN(view) <= 0;
}

bool
draw_box(struct view *view, const struct box *box)
{
	size_t i;
	const char *text = box->text;

	for (i = 0; i < box->cells; i++) {
		const struct box_cell *cell = &box->cell[i];

		if (draw_textn(view, cell->type, text, cell->length))
			return true;
		text += cell->length;
	}
	return VIEW_MAX_LEN(view) <= 0;
}

static bool
draw_graphic(struct view *view, enum line_type type, const chtype graphic[], size_t size, bool separator)
{
	size_t skip = view->pos.col > view->col ? view->pos.col - view->col : 0;
	int max = VIEW_MAX_LEN(view) - 1;
	int i;

	if (max < size)
		size = max;

	set_view_attr(view, type);
	/* Using waddch() instead of waddnstr() ensures that
	 * they'll be rendered correctly for the cursor line. */
	for (i = skip; i < size; i++)
		waddch(view->win, graphic[i]);

	view->col += size;
	if (separator) {
		if (size < max && skip <= size)
			waddch(view->win, ' ');
		view->col++;
	}

	return VIEW_MAX_LEN(view) <= 0;
}

bool
draw_field(struct view *view, enum line_type type, const char *text, int width, enum align align, bool trim)
{
	int max = MIN(VIEW_MAX_LEN(view), width + 1);
	int col = view->col;

	if (!text)
		return draw_space(view, type, max, max);

	if (align == ALIGN_RIGHT) {
		int textlen = utf8_width_of(text, -1, -1);
		int leftpad = width - textlen;

		if (leftpad > 0) {
			if (draw_space(view, type, leftpad, leftpad))
				return true;
			max -= leftpad;
		}
	}

	return draw_chars(view, type, text, -1, max - 1, trim)
	    || draw_space(view, LINE_DEFAULT, max - (view->col - col), max);
}

bool
draw_date(struct view *view, struct view_column *column, const struct time *time)
{
	struct date_options *opt = &column->opt.date;
	const char *date = mkdate(time, opt->display, opt->local, opt->format);
	int width = column->width;
	enum align align = opt->display == DATE_DISPLAY_RELATIVE_COMPACT ||
			   opt->display == DATE_DISPLAY_RELATIVE ? ALIGN_RIGHT : ALIGN_LEFT;

	if (opt->display == DATE_DISPLAY_NO)
		return false;

	return draw_field(view, LINE_DATE, date, width, align, false);
}

const char *
mkauthor_ident(const struct ident *author, int cols, int display)
{
	bool trim = cols < 10;
	bool abbreviate = display == AUTHOR_DISPLAY_ABBREVIATED || trim;

	if (display == AUTHOR_DISPLAY_NO)
		return "";
	if (!author)
		return "";
	if (display == AUTHOR_DISPLAY_EMAIL && author->email)
		return author->email;
	if (display == AUTHOR_DISPLAY_EMAIL_USER && author->email)
		return get_email_user(author->email);
	if (abbreviate && author->name)
		return get_author_initials(author->name);
	return author->name;
}

bool
draw_author(struct view *view, struct view_column *column, const struct ident *author)
{
	struct author_options *opt = &column->opt.author;
	bool trim = column->width >= 10;
	const char *text = mkauthor_ident(author, column->width, opt->display);
	enum line_type type = column->type == VIEW_COLUMN_COMMITTER ? LINE_COMMITTER : LINE_AUTHOR;

	if (opt->display == AUTHOR_DISPLAY_NO)
		return false;

	return draw_field(view, type, text, column->width, ALIGN_LEFT, trim);
}

bool
draw_id(struct view *view, struct view_column *column, const char *id)
{
	struct id_options *opt = &column->opt.id;
	enum line_type type = LINE_ID;

	if (!opt->display)
		return false;

	if (opt->color && id) {
		hashval_t color = iterative_hash(id, SIZEOF_REV - 1, 0);

		type = palette(color);
	}

	return draw_field(view, type, id, column->width, ALIGN_LEFT, false);
}

bool
draw_filesize(struct view *view, struct view_column *column, const unsigned long *size)
{
	const char *str = size ? mkfilesize(*size, column->opt.file_size.display) : NULL;

	if (!column->opt.file_size.display)
		return false;

	return draw_field(view, LINE_FILE_SIZE, str, column->width, ALIGN_RIGHT, false);
}

bool
draw_mode(struct view *view, struct view_column *column, const mode_t *mode)
{
	const char *str = mode ? mkmode(*mode) : NULL;

	if (!column->opt.mode.display)
		return false;

	return draw_field(view, LINE_MODE, str, column->width, ALIGN_LEFT, false);
}

bool
draw_lineno_custom(struct view *view, struct view_column *column, unsigned int lineno)
{
	char number[10];
	unsigned long digits3 = view->digits < 3 ? 3 : view->digits;
	int max = MIN(VIEW_MAX_LEN(view), digits3);
	char *text = NULL;
	chtype separator = opt_line_graphics ? ACS_VLINE : '|';
	struct line_number_options *opts = &column->opt.line_number;
	int interval = opts->interval > 0 ? opts->interval : 5;

	if (!opts->display)
		return false;

	if (lineno == 1 || (lineno % interval) == 0) {
		static char fmt[] = "%ld";

		fmt[1] = '0' + (digits3 <= 9 ? digits3 : 1);
		if (string_format(number, fmt, (long) lineno))
			text = number;
	}
	if (text)
		draw_chars(view, LINE_LINE_NUMBER, text, -1, max, true);
	else
		draw_space(view, LINE_LINE_NUMBER, max, digits3);
	return draw_graphic(view, LINE_DEFAULT, &separator, 1, true);
}

bool
draw_lineno(struct view *view, struct view_column *column, unsigned int lineno)
{
	if (!column->opt.line_number.display)
		return false;
	return draw_lineno_custom(view, column, lineno);
}

bool
draw_refs(struct view *view, struct view_column *column, const struct ref *refs)
{
	size_t sep = 0;
	const struct ref *ref;

	if (!column->opt.commit_title.refs || !refs)
		return false;

	for (ref = refs; ref; ref = ref->next) {
		enum line_type type = get_line_type_from_ref(ref);
		const struct ref_format *format = get_ref_format(ref);

		if (!strcmp(format->start, "hide:") && !*format->end)
			continue;

		if (sep && draw_space(view, LINE_DEFAULT, 1, 1))
			return true;

		if (draw_formatted(view, type, "%s%s%s", format->start, ref->name, format->end))
			return true;
		sep = 1;
	}

	if (sep)
		return draw_space(view, LINE_DEFAULT, 1, 1);
	return false;
}

bool
draw_formatted(struct view *view, enum line_type type, const char *format, ...)
{
	char text[SIZEOF_STR];
	int retval;
	va_list args;

	va_start(args, format);
	retval = vsnprintf(text, sizeof(text), format, args);
	va_end(args);

	return retval >= 0 ? draw_text(view, type, text) : VIEW_MAX_LEN(view) <= 0;
}

bool
draw_status(struct view *view, struct view_column *column, const char *status)
{
	struct status_options *opt = &column->opt.status;
	const char *str = status ? mkstatus(*status, opt->display) : "";
	int width = column->width;

	if (!opt->display)
		return false;

	return draw_field(view, LINE_DEFAULT, str, width, ALIGN_LEFT, false);
}

bool
draw_filename(struct view *view, struct view_column *column, const char *filename, mode_t mode)
{
	size_t width = filename ? utf8_width_of(filename, -1, -1) : 0;
	bool trim = width >= column->width;
	enum line_type type = S_ISDIR(mode) ? LINE_DIRECTORY : LINE_FILE;
	int column_width = column->width ? column->width : width;

	if (column->opt.file_name.display == FILENAME_DISPLAY_NO)
		return false;

	return draw_field(view, type, filename, column_width, ALIGN_LEFT, trim);
}

bool
draw_commit_title(struct view *view, struct view_column *column, const char *text, const struct ref *refs)
{
	struct commit_title_options *opt = &column->opt.commit_title;

	if (!opt->display)
		return false;
	if (draw_refs(view, column, refs))
		return true;
	return draw_text_overflow(view, LINE_DEFAULT, text, opt->overflow > 0, opt->overflow);
}

/*
 * Graph drawing
 */

static const chtype *
graph_symbols_default(void);

bool
draw_graph(struct view *view, const struct graph *graph, const struct graph_canvas *canvas)
{
	return graph_draw(view, graph, canvas);
}

/*
 * Line drawing
 */

bool
draw_view_line(struct view *view, unsigned int lineno)
{
	struct line *line;
	bool selected = (view->pos.offset + lineno == view->pos.lineno);

	/* FIXME: Disabled during code split.
	assert(view_is_displayed(view));
	*/

	if (view->pos.offset + lineno >= view->lines)
		return false;

	line = &view->line[view->pos.offset + lineno];

	wmove(view->win, lineno, 0);
	if (line->cleareol)
		wclrtoeol(view->win);
	view->col = 0;
	view->curline = line;
	view->curtype = LINE_NONE;
	line->selected = false;
	line->dirty = line->cleareol = 0;

	if (selected) {
		set_view_attr(view, LINE_CURSOR);
		line->selected = true;
		view->ops->select(view, line);
	}

	return view->ops->draw(view, line, lineno);
}

void
redraw_view_dirty(struct view *view)
{
	bool dirty = false;
	int lineno;

	for (lineno = 0; lineno < view->height; lineno++) {
		if (view->pos.offset + lineno >= view->lines)
			break;
		if (!view->line[view->pos.offset + lineno].dirty)
			continue;
		dirty = true;
		if (!draw_view_line(view, lineno))
			break;
	}

	if (!dirty)
		return;
	wnoutrefresh(view->win);
}

void
redraw_view_from(struct view *view, int lineno)
{
	assert(0 <= lineno && lineno < view->height);

	if (view->columns && view_column_info_changed_(view, true)) {
		int i;

		view_column_reset_(view);
		for (i = 0; i < view->lines; i++) {
			view_column_info_update(view, &view->line[i]);
		}
	}

	for (; lineno < view->height; lineno++) {
		if (!draw_view_line(view, lineno))
			break;
	}

	wnoutrefresh(view->win);
}

void
redraw_view(struct view *view)
{
	wbkgd(view->win, get_line_attr(view->keymap->name, LINE_DEFAULT));
	werase(view->win);
	redraw_view_from(view, 0);
}
