		{ "main", NULL },
	};

	(void) map; (void) i;
	return get_view_columns_ptr(view->name);
}

static struct view_column **
get_view_columns_ptr(const char *name)
{
	if (!strcmp(name, "blame")) return &opt_blame_view;
	if (!strcmp(name, "blob")) return &opt_blob_view;
	if (!strcmp(name, "diff")) return &opt_diff_view;
	if (!strcmp(name, "grep")) return &opt_grep_view;
	if (!strcmp(name, "log")) return &opt_log_view;
	if (!strcmp(name, "reflog")) return &opt_reflog_view;
	if (!strcmp(name, "main")) return &opt_main_view;
	if (!strcmp(name, "pager")) return &opt_pager_view;
	if (!strcmp(name, "refs")) return &opt_refs_view;
	if (!strcmp(name, "stage")) return &opt_stage_view;
	if (!strcmp(name, "stash")) return &opt_stash_view;
	if (!strcmp(name, "status")) return &opt_status_view;
	if (!strcmp(name, "tree")) return &opt_tree_view;
	return NULL;
}

/* Returns true if the column configuration changed since last check. */
bool
view_column_info_changed_(struct view *view, bool update)
{
	struct view_column **opt = get_view_columns_ptr(view->name);
	struct view_column *column;
	int count = 0;
	bool changed = false;

	if (!opt)
		return false;

	if (view->columns != *opt) {
		view->columns = *opt;
		changed = true;
	}

	for (column = view->columns; column; column = column->next)
		count++;

	if (count != view->columns_count) {
		changed = true;
	} else if (view->column_info) {
		int i = 0;

		for (column = view->columns; column; column = column->next, i++) {
			struct view_column *saved = &view->column_info[i].column;

			if (saved->type != column->type ||
			    memcmp(&saved->opt, &column->opt, sizeof(column->opt))) {
				changed = true;
				break;
			}
		}
	} else {
		changed = true;
	}

	if (changed && update) {
		int i = 0;

		free(view->column_info);
		view->column_info = calloc(count ? count : 1, sizeof(*view->column_info));
		view->columns_count = count;
		for (column = view->columns; column; column = column->next, i++) {
			view->column_info[i].column = *column;
			view->column_info[i].column.next = NULL;
		}
	}

	return changed;
}

void
view_column_reset_(struct view *view)
{
	struct view_column *column;

	for (column = view->columns; column; column = column->next)
		column->width = 0;
}

struct view_column *
get_view_column(struct view *view, enum view_column_type type)
{
	struct view_column *column;

	for (column = view->columns; column; column = column->next)
		if (column->type == type)
			return column;
	return NULL;
}

static int
apply_step_int(int step, int value)
{
	if (step >= 0)
		return step;
	return MAX(value * -step / 100, 1);
}

static int
column_max_width(struct view *view, int maxwidth)
{
	if (maxwidth == 0)
		return 0;
	if (maxwidth < 0)
		return view->width * -maxwidth / 100;
	return maxwidth;
}

bool
view_column_info_update(struct view *view, struct line *line)
{
	struct view_column_data column_data = {0};
	struct view_column *column;
	bool changed = false;

	if (!view->columns || !view->ops->get_column_data)
		return false;
	if (!view->ops->get_column_data(view, line, &column_data))
		return false;

	for (column = view->columns; column; column = column->next) {
		const char *text = NULL;
		int width = -1;
		char buf[SIZEOF_STR];
		int maxwidth = 0;

		switch (column->type) {
		case VIEW_COLUMN_AUTHOR:
			if (column->opt.author.width) {
				width = column->opt.author.width;
				break;
			}
			if (column->opt.author.display == AUTHOR_DISPLAY_NO)
				break;
			text = mkauthor_ident(column_data.author, column->opt.author.width ? column->opt.author.width : 100, column->opt.author.display);
			maxwidth = column_max_width(view, column->opt.author.maxwidth);
			break;

		case VIEW_COLUMN_COMMITTER:
			if (column->opt.committer.width) {
				width = column->opt.committer.width;
				break;
			}
			if (column->opt.committer.display == AUTHOR_DISPLAY_NO)
				break;
			text = mkauthor_ident(column_data.author, column->opt.committer.width ? column->opt.committer.width : 100, column->opt.committer.display);
			maxwidth = column_max_width(view, column->opt.committer.maxwidth);
			break;

		case VIEW_COLUMN_DATE:
			if (column->opt.date.width) {
				width = column->opt.date.width;
				break;
			}
			if (column->opt.date.display == DATE_DISPLAY_NO)
				break;
			text = mkdate(column_data.date, column->opt.date.display, column->opt.date.local, column->opt.date.format);
			break;

		case VIEW_COLUMN_FILE_NAME:
			if (column->opt.file_name.width) {
				width = column->opt.file_name.width;
				break;
			}
			if (column->opt.file_name.display == FILENAME_DISPLAY_NO)
				break;
			text = column_data.file_name;
			maxwidth = column_max_width(view, column->opt.file_name.maxwidth);
			break;

		case VIEW_COLUMN_FILE_SIZE:
			if (column->opt.file_size.width) {
				width = column->opt.file_size.width;
				break;
			}
			if (!column->opt.file_size.display)
				break;
			text = column_data.file_size ? mkfilesize(*column_data.file_size, column->opt.file_size.display) : NULL;
			break;

		case VIEW_COLUMN_ID:
			if (column->opt.id.width) {
				width = column->opt.id.width;
				break;
			}
			if (!column->opt.id.display)
				break;
			if (opt_id_width) {
				width = opt_id_width;
				break;
			}
			if (column_data.reflog) {
				text = column_data.reflog;
				break;
			}
			if (column_data.id && !iscommit(column_data.id)) {
				text = column_data.id;
				break;
			}
			width = opt_core_abbrev ? opt_core_abbrev : 7;
			if (column->width < width)
				changed = true;
			if (column->width < width)
				column->width = width;
			width = -1;
			break;

		case VIEW_COLUMN_LINE_NUMBER:
			if (column->opt.line_number.width) {
				width = column->opt.line_number.width;
				break;
			}
			break;

		case VIEW_COLUMN_MODE:
			if (column->opt.mode.width) {
				width = column->opt.mode.width;
				break;
			}
			if (!column->opt.mode.display)
				break;
			text = column_data.mode ? mkmode(*column_data.mode) : NULL;
			break;

		case VIEW_COLUMN_REF:
			if (column->opt.ref.width) {
				width = column->opt.ref.width;
				break;
			}
			if (!column->opt.ref.display)
				break;
			text = column_data.ref ? column_data.ref->name : NULL;
			maxwidth = column_max_width(view, column->opt.ref.maxwidth);
			break;

		case VIEW_COLUMN_STATUS:
			if (!column->opt.status.display)
				break;
			text = column_data.status ? mkstatus(*column_data.status, column->opt.status.display) : NULL;
			break;

		case VIEW_COLUMN_COMMIT_TITLE:
		case VIEW_COLUMN_TEXT:
			break;
		}

		if (width >= 0) {
			if (column->width != width) {
				column->width = width;
				changed = true;
			}
			continue;
		}

		if (text) {
			int w = utf8_width_of(text, -1, -1);

			if (maxwidth && w > maxwidth)
				w = maxwidth;
			if (w > column->width) {
				column->width = w;
				changed = true;
			}
		}
		(void) buf;
	}

	return changed;
}

bool
view_column_info_changed(struct view_column *column, bool update)
{
	return false;
}

void
view_set_columns(struct view *view, struct view_column *columns)
{
	view->columns = columns;
}

bool
view_column_grep(struct view *view, struct line *line)
{
	struct view_column_data column_data = {0};
	bool ok = view->ops->get_column_data(view, line, &column_data);
	const char *text[] = {
		column_data.author ? mkauthor_ident(column_data.author, 100, AUTHOR_DISPLAY_FULL) : "",
		column_data.commit_title ? column_data.commit_title : "",
		column_data.date ? mkdate(column_data.date, DATE_DISPLAY_DEFAULT, false, "") : "",
		column_data.file_name ? column_data.file_name : "",
		column_data.file_size ? mkfilesize(*column_data.file_size, FILE_SIZE_DISPLAY_DEFAULT) : "",
		column_data.id ? column_data.id : "",
		column_data.mode ? mkmode(*column_data.mode) : "",
		column_data.ref ? column_data.ref->name : "",
		column_data.status ? mkstatus(*column_data.status, STATUS_DISPLAY_LONG) : "",
		column_data.text ? column_data.text : "",
		NULL
	};

	if (!ok)
		return false;
	{
		const struct ref *ref;

		for (ref = column_data.refs; ref; ref = ref->next) {
			const char *t[] = { ref->name, NULL };
			if (grep_text(view, t))
				return true;
		}
	}
	return grep_text(view, text);
}

bool
view_columns_draw(struct view *view, struct line *line, unsigned int lineno)
{
	struct view_column *column = view->columns;
	struct view_column_data column_data = {0};

	if (!view->ops->get_column_data(view, line, &column_data))
		return true;

	if (column_data.section)
		column = column_data.section;

	for (; column; column = column->next) {
		mode_t mode = column_data.mode ? *column_data.mode : 0;

		if (column->hidden)
			continue;

		switch (column->type) {
		case VIEW_COLUMN_DATE:
			if (draw_date(view, column, column_data.date))
				return true;
			continue;

		case VIEW_COLUMN_AUTHOR:
			if (draw_author(view, column, column_data.author))
				return true;
			continue;

		case VIEW_COLUMN_COMMITTER:
			if (draw_author(view, column, column_data.author))
				return true;
			continue;

		case VIEW_COLUMN_REF:
			if (draw_ref(view, column, column_data.ref))
				return true;
			continue;

		case VIEW_COLUMN_ID:
			if (draw_id(view, column, column_data.reflog ? column_data.reflog : column_data.id))
				return true;
			continue;

		case VIEW_COLUMN_LINE_NUMBER:
			if (draw_lineno(view, column, column_data.line_number ? *column_data.line_number : lineno))
				return true;
			continue;

		case VIEW_COLUMN_MODE:
			if (draw_mode(view, column, column_data.mode))
				return true;
			continue;

		case VIEW_COLUMN_FILE_SIZE:
			if (draw_filesize(view, column, column_data.file_size))
				return true;
			continue;

		case VIEW_COLUMN_COMMIT_TITLE:
			if (column_data.graph && column->opt.commit_title.graph) {
				if (draw_graph(view, column_data.graph, column_data.graph_canvas))
					return true;
			}
			if (draw_commit_title(view, column, column_data.commit_title, column_data.refs))
				return true;
			continue;

		case VIEW_COLUMN_FILE_NAME:
			if (draw_filename(view, column, column_data.file_name, mode))
				return true;
			continue;

		case VIEW_COLUMN_STATUS:
			if (draw_status(view, column, column_data.status))
				return true;
			continue;

		case VIEW_COLUMN_TEXT:
			if (column_data.box) {
				if (draw_box(view, column_data.box))
					return true;
			} else if (draw_text(view, line->type, column_data.text ? column_data.text : "")) {
				return true;
			}
			continue;
		}
	}

	return true;
}

bool
draw_ref(struct view *view, struct view_column *column, const struct ref *ref)
{
	enum line_type type = !ref || !ref->valid ? LINE_DEFAULT : get_line_type_from_ref(ref);
	const char *name = ref ? ref->name : NULL;

	if (!column->opt.ref.display)
		return false;

	return draw_field(view, type, name, column->width, ALIGN_LEFT, false);
}

/*
 * Argv formatting
 */

static bool
argv_append_env(const char ***dst_argv, const char *arg, size_t argend, const char *value)
{
	char buf[SIZEOF_STR];

	(void) arg; (void) argend;
	string_ncopy(buf, value, strlen(value));
	return argv_append(dst_argv, buf);
}

struct argv_env_var {
	const char *name;
	const char *value;
};

static const char *
argv_env_var_value(struct argv_env *env, const char *name, size_t namelen, char *buf, size_t bufsize)
{
#define ENV_STR(n, v) if (namelen == STRING_SIZE(n) && !strncmp(name, n, namelen)) return v;
	ENV_STR("head", env->head);
	ENV_STR("commit", env->commit);
	ENV_STR("blob", env->blob);
	ENV_STR("branch", env->branch);
	ENV_STR("remote", env->remote);
	ENV_STR("tag", env->tag);
	ENV_STR("refname", env->refname);
	ENV_STR("stash", env->stash);
	ENV_STR("directory", *env->directory ? env->directory : ".");
	ENV_STR("file", env->file);
	ENV_STR("file_old", env->file_old);
	ENV_STR("ref", *env->ref ? env->ref : "HEAD");
	ENV_STR("text", env->text);
	ENV_STR("repo:head", repo.head);
	ENV_STR("repo:head-id", repo.head_id);
	ENV_STR("repo:remote", repo.remote);
	ENV_STR("repo:upstream", repo.upstream);
	ENV_STR("repo:cdup", repo.cdup);
	ENV_STR("repo:prefix", repo.prefix);
	ENV_STR("repo:git-dir", repo.git_dir);
	ENV_STR("repo:worktree", repo.worktree);
	ENV_STR("repo:is-inside-work-tree", repo.is_inside_work_tree ? "true" : "false");
#undef ENV_STR
	if (namelen == STRING_SIZE("lineno") && !strncmp(name, "lineno", namelen)) {
		string_nformat(buf, bufsize, NULL, "%lu", env->lineno);
		return buf;
	}
	if (namelen == STRING_SIZE("lineno_old") && !strncmp(name, "lineno_old", namelen)) {
		string_nformat(buf, bufsize, NULL, "%lu", env->lineno_old);
		return buf;
	}
	return NULL;
}

static bool
format_append_argv(const char ***dst_argv, const char **src_argv)
{
	return argv_append_array(dst_argv, src_argv);
}

bool
argv_format(struct argv_env *argv_env, const char ***dst_argv, const char *src_argv[], bool first, bool file_filter)
{
	char buf[SIZEOF_STR];
	int argc;

	argv_free(*dst_argv);

	for (argc = 0; src_argv[argc]; argc++) {
		const char *arg = src_argv[argc];
		size_t bufpos = 0;

		if (!strcmp(arg, "%(fileargs)")) {
			if (file_filter && !argv_append_array(dst_argv, opt_file_args))
				break;
			continue;

		} else if (!strcmp(arg, "%(diffargs)")) {
			if (!format_append_argv(dst_argv, opt_diff_options))
				break;
			continue;

		} else if (!strcmp(arg, "%(blameargs)")) {
			if (!format_append_argv(dst_argv, opt_blame_options))
				break;
			continue;

		} else if (!strcmp(arg, "%(logargs)")) {
			if (!format_append_argv(dst_argv, opt_log_options))
				break;
			continue;

		} else if (!strcmp(arg, "%(mainargs)")) {
			if (!format_append_argv(dst_argv, opt_main_options))
				break;
			continue;

		} else if (!strcmp(arg, "%(cmdlineargs)")) {
			if (!format_append_argv(dst_argv, opt_cmdline_args))
				break;
			continue;

		} else if (!strcmp(arg, "%(revargs)") ||
			   (first && !strcmp(arg, "%(commit)"))) {
			if (!argv_append_array(dst_argv, opt_rev_args))
				break;
			continue;
		}

		while (arg) {
			char *next = strstr(arg, "%(");
			int len = next ? next - arg : strlen(arg);
			const char *value = NULL;
			char vbuf[SIZEOF_STR];

			if (len && !string_nformat(buf, sizeof(buf), &bufpos, "%.*s", len, arg))
				return false;

			if (!next)
				break;

			if (!prefixcmp(next, "%(prompt")) {
				const char *prompt_start = next + STRING_SIZE("%(prompt");
				const char *end = strchr(prompt_start, ')');
				char prompt[SIZEOF_STR] = "Command argument: ";
				char *response;

				if (!end)
					return false;
				if (*prompt_start == ' ' && end > prompt_start + 1)
					string_ncopy(prompt, prompt_start + 1, end - prompt_start - 1);
				response = read_prompt(prompt);
				if (!response)
					return false;
				value = response;
				arg = end + 1;
			} else {
				const char *end = strchr(next, ')');

				if (!end)
					return false;
				value = argv_env_var_value(argv_env, next + 2, end - next - 2, vbuf, sizeof(vbuf));
				if (!value) {
					/* Unknown variable: keep as is */
					if (!string_nformat(buf, sizeof(buf), &bufpos, "%.*s", (int) (end - next + 1), next))
						return false;
					arg = end + 1;
					continue;
				}
				arg = end + 1;
			}

			if (!string_nformat(buf, sizeof(buf), &bufpos, "%s", value))
				return false;
		}

		if (!argv_append(dst_argv, buf))
			break;
	}

	return src_argv[argc] == NULL;
}

/*
 * Views registry
