/*
 * Line management
 */

static void
reset_view_lines(struct view *view)
{
	size_t i;

	for (i = 0; i < view->lines; i++)
		free(view->line[i].data);
	free(view->line);
	view->line = NULL;
	view->lines = 0;
	view->custom_lines = 0;
}

void
reset_view(struct view *view)
{
	if (view->ops->done)
		view->ops->done(view);
	reset_view_lines(view);
	view->prev_pos = view->pos;
	view->pos.offset = view->pos.lineno = view->pos.col = 0;
	view->digits = 0;
	view->update_secs = 0;
	view->vid[0] = 0;
	view_column_reset_(view);
}

static bool
realloc_lines(struct view *view, size_t line_size)
{
	size_t needed = view->lines + 1;
	size_t alloc = 0;
	struct line *tmp;

	if (line_size >= needed)
		return true;

	alloc = (needed + 255) & ~255;
	tmp = realloc(view->line, alloc * sizeof(*tmp));
	if (!tmp)
		return false;
	view->line = tmp;
	return true;
}

static size_t view_line_alloc[64];

static size_t *
view_alloc_ptr(struct view *view)
{
	int i;

	for (i = 0; i < views_count; i++)
		if (views[i] == view)
			return &view_line_alloc[i];
	return &view_line_alloc[63];
}

static bool
ensure_lines(struct view *view)
{
	size_t *alloc = view_alloc_ptr(view);

	if (view->lines + 1 > *alloc) {
		size_t newalloc = ((view->lines + 1) + 255) & ~255;
		struct line *tmp = realloc(view->line, newalloc * sizeof(*tmp));

		if (!tmp)
			return false;
		view->line = tmp;
		*alloc = newalloc;
	}
	return true;
}

static void
view_digits_update(struct view *view)
{
	size_t lines = view->lines;
	unsigned int digits = 0;

	for (; lines; lines /= 10)
		digits++;
	if (digits > view->digits) {
		view->digits = digits;
		if (view_is_displayed(view))
			view->force_redraw = true;
	}
}

struct line *
add_line_at(struct view *view, unsigned long pos, const void *data, enum line_type type, size_t data_size, bool custom)
{
	struct line *line;
	unsigned long lineno;

	if (!ensure_lines(view))
		return NULL;

	if (data_size) {
		void *alloc_data = calloc(1, data_size);

		if (!alloc_data)
			return NULL;

		if (data)
			memcpy(alloc_data, data, data_size);
		data = alloc_data;
	}

	if (pos < view->lines) {
		view->lines++;
		line = view->line + pos;
		lineno = line->lineno;

		memmove(line + 1, line, (view->lines - pos - 1) * sizeof(*view->line));
		while (pos < view->lines) {
			view->line[pos].lineno++;
			view->line[pos++].dirty = 1;
		}
	} else {
		line = view->line + view->lines++;
		lineno = view->lines - view->custom_lines;
	}

	memset(line, 0, sizeof(*line));
	line->type = type;
	line->data = (void *) data;
	line->dirty = 1;

	if (custom) {
		view->custom_lines++;
		line->custom = 1;
		line->lineno = view->lines;
	} else {
		line->lineno = view->lines;
	}
	(void) lineno;

	view_digits_update(view);
	view_column_info_update(view, line);

	return line;
}

struct line *
add_line(struct view *view, const void *data, enum line_type type, size_t data_size, bool custom)
{
	return add_line_at(view, view->lines, data, type, data_size, custom);
}

struct line *
add_line_alloc_(struct view *view, void **ptr, enum line_type type, size_t data_size, bool custom)
{
	struct line *line = add_line(view, NULL, type, data_size, custom);

	if (line)
		*ptr = line->data;
	return line;
}

struct line *
add_line_nodata(struct view *view, enum line_type type)
{
	return add_line(view, NULL, type, 0, false);
}

struct line *
add_line_text_at_(struct view *view, unsigned long pos, const char *text, enum line_type type, size_t cells, bool custom)
{
	struct box *box;
	size_t textlen = strlen(text);
	struct line *line = add_line_at(view, pos, NULL, type, sizeof(*box) + textlen + cells * sizeof(struct box_cell), custom);

	if (line) {
		box = line->data;
		box->text = (char *) &box->cell[cells + 1];
		memcpy((char *) box->text, text, textlen);
		((char *) box->text)[textlen] = 0;
		box->cells = 1;
		box->cell[0].length = textlen;
		box->cell[0].type = type;
		view_column_info_update(view, line);
	}

	return line;
}

/* Layout of box data: struct box, cells array (cells+1 entries), then text. */
struct line *
add_line_text_at(struct view *view, unsigned long pos, const char *text, enum line_type type, size_t cells)
{
	return add_line_text_at_(view, pos, text, type, cells, false);
}

struct line *
add_line_text(struct view *view, const char *text, enum line_type type)
{
	return add_line_text_at(view, view->lines, text, type, 1);
}

struct line *
add_line_format(struct view *view, enum line_type type, const char *fmt, ...)
{
	char buf[SIZEOF_STR];
	int retval;
	va_list args;

	va_start(args, fmt);
	retval = vsnprintf(buf, sizeof(buf), fmt, args);
	va_end(args);

	return retval >= 0 ? add_line_text(view, buf, type) : NULL;
}

bool
box_add_cell(struct box *box, const char *text, enum line_type type, size_t len)
{
	/* The box data is allocated with room for the required number of cells. */
	box->cell[box->cells].type = type;
	box->cell[box->cells].length = len;
	box->cells++;
	return true;
}

struct line *
find_line_by_type(struct view *view, struct line *line, enum line_type type, int direction)
{
	for (; view_has_line(view, line); line += direction)
		if (line->type == type)
			return line;

	return NULL;
}

bool
view_has_line(struct view *view, const struct line *line)
{
	return view->line <= line && line < view->line + view->lines;
}

/*
 * Navigation
 */

void
do_scroll_view(struct view *view, int lines)
{
	bool redraw_current_line = false;

	/* The rendering expects the new offset. */
	view->pos.offset += lines;

	assert(0 <= view->pos.offset && view->pos.offset < view->lines);
	assert(lines);

	/* Move current line into the view. */
	if (view->pos.lineno < view->pos.offset) {
		view->pos.lineno = view->pos.offset;
		redraw_current_line = true;
	} else if (view->pos.lineno >= view->pos.offset + view->height) {
		view->pos.lineno = view->pos.offset + view->height - 1;
		redraw_current_line = true;
	}

	assert(view->pos.offset <= view->pos.lineno && view->pos.lineno < view->lines);

	/* Redraw the whole screen if scrolling is pointless. */
	if (view->height < ABS(lines)) {
		redraw_view(view);

	} else {
		int line = lines > 0 ? view->height - lines : 0;
		int end = line + ABS(lines);

		scrollok(view->win, true);
		wscrl(view->win, lines);
		scrollok(view->win, false);

		while (line < end && draw_view_line(view, line))
			line++;

		if (redraw_current_line)
			draw_view_line(view, view->pos.lineno - view->pos.offset);
		wnoutrefresh(view->win);
	}

	view->has_scrolled = true;
	report_clear();
}

void
scroll_view(struct view *view, enum request request)
{
	int lines = 1;

	assert(view_is_displayed(view));

	if (request == REQ_SCROLL_WHEEL_DOWN || request == REQ_SCROLL_WHEEL_UP)
		lines = opt_mouse_scroll;

	switch (request) {
	case REQ_SCROLL_FIRST_COL:
		view->pos.col = 0;
		redraw_view_from(view, 0);
		report_clear();
		return;
	case REQ_SCROLL_LEFT:
		if (view->pos.col == 0) {
			report("Cannot scroll beyond the first column");
			return;
		}
		if (view->pos.col <= apply_step(opt_horizontal_scroll, view->width))
			view->pos.col = 0;
		else
			view->pos.col -= apply_step(opt_horizontal_scroll, view->width);
		redraw_view_from(view, 0);
		report_clear();
		return;
	case REQ_SCROLL_RIGHT:
		view->pos.col += apply_step(opt_horizontal_scroll, view->width);
		redraw_view(view);
		report_clear();
		return;
	case REQ_SCROLL_PAGE_DOWN:
		lines = view->height;
	case REQ_SCROLL_WHEEL_DOWN:
	case REQ_SCROLL_LINE_DOWN:
		if (view->pos.offset + lines > view->lines)
			lines = view->lines - view->pos.offset;

		if (lines == 0 || view->pos.offset + view->height >= view->lines) {
			report("Cannot scroll beyond the last line");
			return;
		}
		break;

	case REQ_SCROLL_PAGE_UP:
		lines = view->height;
	case REQ_SCROLL_LINE_UP:
	case REQ_SCROLL_WHEEL_UP:
		if (lines > view->pos.offset)
			lines = view->pos.offset;

		if (lines == 0) {
			report("Cannot scroll beyond the first line");
			return;
		}

		lines = -lines;
		break;

	case REQ_SCROLL_HALF_PAGE_DOWN:
		lines = view->height / 2;
		if (view->pos.offset + lines > view->lines)
			lines = view->lines - view->pos.offset;
		if (lines == 0 || view->pos.offset + view->height >= view->lines) {
			report("Cannot scroll beyond the last line");
			return;
		}
		break;

	case REQ_SCROLL_HALF_PAGE_UP:
		lines = view->height / 2;
		if (lines > view->pos.offset)
			lines = view->pos.offset;
		if (lines == 0) {
			report("Cannot scroll beyond the first line");
			return;
		}
		lines = -lines;
		break;

	default:
		die("request %d not handled in switch", request);
	}

	do_scroll_view(view, lines);
}

void
move_view(struct view *view, enum request request)
{
	int scroll_steps = 0;
	int steps;

	switch (request) {
	case REQ_MOVE_FIRST_LINE:
		steps = -view->pos.lineno;
		break;

	case REQ_MOVE_LAST_LINE:
		steps = view->lines - view->pos.lineno - 1;
		break;

	case REQ_MOVE_PAGE_UP:
		steps = view->height > view->pos.lineno
		      ? -view->pos.lineno : -view->height;
		break;

	case REQ_MOVE_PAGE_DOWN:
		steps = view->pos.lineno + view->height >= view->lines
		      ? view->lines - view->pos.lineno - 1 : view->height;
		break;

	case REQ_MOVE_HALF_PAGE_UP:
		steps = view->height / 2 > view->pos.lineno
		      ? -view->pos.lineno : -(view->height / 2);
		break;

	case REQ_MOVE_HALF_PAGE_DOWN:
		steps = view->pos.lineno + view->height / 2 >= view->lines
		      ? view->lines - view->pos.lineno - 1 : view->height / 2;
		break;

	case REQ_MOVE_WHEEL_UP:
		steps = view->pos.lineno < opt_mouse_scroll ? -view->pos.lineno : -opt_mouse_scroll;
		break;

	case REQ_MOVE_WHEEL_DOWN:
		steps = view->pos.lineno + opt_mouse_scroll >= view->lines
		      ? view->lines - view->pos.lineno - 1 : opt_mouse_scroll;
		break;

	case REQ_MOVE_UP:
	case REQ_PREVIOUS:
		steps = -1;
		break;

	case REQ_MOVE_DOWN:
	case REQ_NEXT:
		steps = 1;
		break;

	default:
		die("request %d not handled in switch", request);
	}

	if (steps <= 0 && view->pos.lineno == 0) {
		report("Cannot move beyond the first line");
		return;

	} else if (steps >= 0 && view->pos.lineno + 1 >= view->lines) {
		report("Cannot move beyond the last line");
		return;
	}

	/* Move the current line */
	view->pos.lineno += steps;
	if (view->pos.lineno < 0)
		view->pos.lineno = 0;
	if (view->pos.lineno >= view->lines)
		view->pos.lineno = view->lines - 1;

	/* Check whether the view needs to be scrolled */
	if (view->pos.lineno < view->pos.offset ||
	    view->pos.lineno >= view->pos.offset + view->height) {
		scroll_steps = steps;
		if (steps < 0 && -steps > view->pos.offset) {
			scroll_steps = -view->pos.offset;

		} else if (steps > 0) {
			if (view->pos.lineno == view->lines - 1 &&
			    view->lines > view->height) {
				scroll_steps = view->lines - view->pos.offset - 1;
				if (scroll_steps >= view->height)
					scroll_steps -= view->height - 1;
			}
		}
	}

	if (!view_is_displayed(view)) {
		view->pos.offset += scroll_steps;
		assert(0 <= view->pos.offset && view->pos.offset < view->lines);
		view->ops->select(view, &view->line[view->pos.lineno]);
		return;
	}

	/* Repaint the old "current" line if we be scrolling */
	if (ABS(steps) < view->height)
		draw_view_line(view, view->pos.lineno - steps - view->pos.offset);

	if (scroll_steps) {
		do_scroll_view(view, scroll_steps);
		return;
	}

	/* Draw the current line */
	draw_view_line(view, view->pos.lineno - view->pos.offset);

	wnoutrefresh(view->win);
	report_clear();
}

void
select_view_line(struct view *view, unsigned long lineno)
{
	struct position old = view->pos;

	if (goto_view_line(view, view->pos.offset, lineno)) {
		if (view_is_displayed(view)) {
			if (old.offset != view->pos.offset) {
				redraw_view(view);
			} else {
				draw_view_line(view, old.lineno - view->pos.offset);
				draw_view_line(view, view->pos.lineno - view->pos.offset);
				wnoutrefresh(view->win);
			}
		} else {
			view->ops->select(view, &view->line[view->pos.lineno]);
		}
	}
}

bool
goto_view_line(struct view *view, unsigned long offset, unsigned long lineno)
{
	if (lineno >= view->lines)
		lineno = view->lines > 0 ? view->lines - 1 : 0;

	if (offset > lineno || offset + view->height <= lineno) {
		unsigned long half = view->height / 2;

		if (lineno > half)
			offset = lineno - half;
		else
			offset = 0;
	}

	if (offset != view->pos.offset || lineno != view->pos.lineno) {
		view->pos.offset = offset;
		view->pos.lineno = lineno;
		return true;
	}

	return false;
}

/*
 * Searching
 */

bool
grep_text(struct view *view, const char *text[])
{
	regmatch_t pmatch;
	size_t i;

	for (i = 0; text[i]; i++)
		if (*text[i] && !regexec(view->regex, text[i], 1, &pmatch, 0))
			return true;
	return false;
}

void
reset_search(struct view *view)
{
	free(view->matched_line);
	view->matched_line = NULL;
	view->matched_lines = 0;
}

static void
select_view_line_search(struct view *view, unsigned long lineno)
{
	select_view_line(view, lineno);
}

static bool
find_matches(struct view *view)
{
	size_t lineno;

	/* Note, in order to allow line numbers to be shown in the view the
	 * search must be done on all lines */
	for (lineno = 0; lineno < view->lines; lineno++) {
		struct line *line = &view->line[lineno];

		line->search_result = false;
		if (!view->ops->grep(view, line))
			continue;

		{
			unsigned int *tmp = realloc(view->matched_line, (view->matched_lines + 1) * sizeof(*tmp));

			if (!tmp)
				return false;
			view->matched_line = tmp;
			view->matched_line[view->matched_lines++] = lineno;
			line->search_result = true;
		}
	}

	return true;
}

void
find_next(struct view *view, enum request request)
{
	int direction;
	size_t i;

	if (!*view->grep) {
		if (!*argv_env.search)
			report("No previous search");
		else
			search_view(view, request);
		return;
	}

	switch (request) {
	case REQ_SEARCH:
	case REQ_FIND_NEXT:
		direction = 1;
		break;

	case REQ_SEARCH_BACK:
	case REQ_FIND_PREV:
		direction = -1;
		break;

	default:
		return;
	}

	if (!view->matched_lines && !find_matches(view)) {
		report("Allocation failure");
		return;
	}

	/* Note, `i` is unsigned and will wrap around in which case it
	 * will become bigger than view->matched_lines. */
	i = direction > 0 ? 0 : view->matched_lines - 1;
	for (; i < view->matched_lines; i += direction) {
		size_t lineno = view->matched_line[i];

		if (direction > 0 && lineno <= view->pos.lineno)
			continue;

		if (direction < 0 && lineno >= view->pos.lineno)
			continue;

		select_view_line_search(view, lineno);
		report("Line %zu matches '%s' (%zu of %zu)", lineno + 1, view->grep, i + 1, view->matched_lines);
		return;
	}

	if (view->matched_lines && opt_wrap_search) {
		/* wrap around */
		i = direction > 0 ? 0 : view->matched_lines - 1;
		{
			size_t lineno = view->matched_line[i];

			select_view_line_search(view, lineno);
			report("Line %zu matches '%s' (%zu of %zu)", lineno + 1, view->grep, i + 1, view->matched_lines);
			return;
		}
	}

	if (view->matched_lines)
		report("No more matches for '%s'", view->grep);
	else
		report("No match found for '%s'", view->grep);
}

bool
search_view(struct view *view, enum request request)
{
	int regex_err;
	int regex_flags = REG_EXTENDED;
	struct view *save_view = view;

	if (opt_ignore_case == IGNORE_CASE_YES)
		regex_flags |= REG_ICASE;
	else if (opt_ignore_case == IGNORE_CASE_SMART_CASE) {
		const char *p;
		bool has_upper = false;

		for (p = argv_env.search; *p; p++)
			if (isupper((unsigned char) *p))
				has_upper = true;
		if (!has_upper)
			regex_flags |= REG_ICASE;
	}

	if (view->regex) {
		regfree(view->regex);
		*view->grep = 0;
	} else {
		view->regex = calloc(1, sizeof(*view->regex));
		if (!view->regex)
			return false;
	}

	regex_err = regcomp(view->regex, argv_env.search, regex_flags);
	if (regex_err != 0) {
		char buf[SIZEOF_STR] = "unknown error";

		regerror(regex_err, view->regex, buf, sizeof(buf));
		report("Search failed: %s", buf);
		return false;
	}

	string_copy(view->grep, argv_env.search);

	reset_search(view);

	find_next(view, request);
	(void) save_view;
	return true;
}

/*
 * View update
 */

bool
view_is_loading(struct view *view)
{
	return view->pipe != NULL;
}

void
end_update(struct view *view, bool force)
{
	if (!view->pipe)
		return;
	while (!view->ops->read(view, NULL, force))
		if (!force)
			return;
	if (force)
		io_kill(view->pipe);
	io_done(view->pipe);
	view->pipe = NULL;
}

static void
setup_update_(struct view *view, const char *vid)
{
	reset_view(view);
	/* XXX: Do not use string_copy_rev(), it copies until first space. */
	string_ncopy(view->vid, vid, strlen(vid));
	view->pipe = &view->io;
	view->start_time = time(NULL);
}

void
setup_update(struct view *view, const char *vid)
{
	setup_update_(view, vid);
}

static bool
view_no_refresh_(struct view *view, enum open_flags flags)
{
	bool reload = !!(flags & (OPEN_RELOAD | OPEN_PREPARED));

	return (!reload && !strcmp(view->vid, view->ops->id)) ||
	       ((flags & OPEN_REFRESH) && !view_can_refresh(view));
}

bool
view_no_refresh_check(struct view *view, enum open_flags flags)
{
	return view_no_refresh_(view, flags);
}

bool
begin_update(struct view *view, const char *dir, const char **argv, enum open_flags flags)
{
	bool extra = !!(flags & (OPEN_EXTRA));
	bool refresh = flags & (OPEN_REFRESH | OPEN_PREPARED | OPEN_STDIN);
	bool forward_stdin = flags & OPEN_FORWARD_STDIN;
	int io_flags = forward_stdin ? IO_RD_WITH_STDIN : 0;

	if (flags & OPEN_WITH_STDERR)
		io_flags |= IO_RD_WITH_STDERR;

	if (view_no_refresh_(view, flags))
		return true;

	if (view->pipe) {
		if (extra)
			io_done(view->pipe);
		else
			end_update(view, true);
	}

	view->unrefreshable = open_in_pager_mode(flags);

	if (!refresh && argv) {
		bool file_filter = !view_has_flags(view, VIEW_FILE_FILTER) || opt_file_filter;

		view->dir = dir;
		if (!argv_format(view->env, &view->argv, argv, !view->prev, file_filter)) {
			report("Failed to format %s arguments", view->name);
			return false;
		}

		/* Put the current view ref value to the view title ref
		 * member. This is needed by the blob view. Most other
		 * views sets it automatically after loading because the
		 * first line is a commit line. */
		string_copy_rev(view->ref, view->ops->id);
	}

	if (view->argv && view->argv[0] &&
	    !io_exec(&view->io, IO_RD, view->dir, (char **) NULL, view->argv, io_flags))
		return false;

	if (open_from_stdin(flags)) {
		if (!io_open(&view->io, "%s", ""))
			die("Failed to open stdin");
	}

	if (!extra)
		setup_update_(view, view->ops->id);

	return true;
}

bool
update_view(struct view *view)
{
	/* Clear the view and redraw everything since the tree sorting
	 * might have rearranged things. */
	bool redraw = view->lines == 0;
	bool can_read = true;
	struct encoding *encoding = view->encoding ? view->encoding : NULL;
	struct buffer line;

	if (!view->pipe)
		return true;

	if (!io_can_read(view->pipe, false)) {
		if (view->lines == 0 && view_is_displayed(view)) {
			time_t secs = time(NULL) - view->start_time;

			if (secs > 1 && secs > view->update_secs) {
				if (view->update_secs == 0)
					redraw_view(view);
				update_view_title(view);
				view->update_secs = secs;
			}
		}
		return true;
	}

	(void) encoding;
	for (; (line.data = io_get(view->pipe, '\n', can_read)); can_read = false) {
		line.size = strlen(line.data);
		if (!view->ops->read(view, &line, false)) {
			report("Allocation failure");
			end_update(view, true);
			return false;
		}
	}

	if (io_error(view->pipe)) {
		report("Failed to read: %s", io_strerror(view->pipe));
		end_update(view, true);

	} else if (io_eof(view->pipe)) {
		end_update(view, false);
	}

	if (restore_view_position(view))
		redraw = true;

	if (!view_is_displayed(view))
		return true;

	if (view->force_redraw) {
		redraw_view_from(view, 0);
		view->force_redraw = false;
	} else if (redraw) {
		redraw_view(view);
	} else {
		redraw_view_dirty(view);
	}

	/* Update the title _after_ the redraw so that if the redraw picks up a
	 * commit reference in view->ref it'll be available here. */
	update_view_title(view);
	return true;
}

bool
restore_view_position(struct view *view)
{
	/* A view without a previous view is the first view */
	if (!view->prev && !view->prev_pos.lineno && !view->prev_pos.offset && !view->prev_pos.col)
		return false;

	/* Ensure that the view position is in a valid state. */
	if (!check_view_position(view, view->prev_pos.offset, view->prev_pos.lineno))
		return false;

	/* ... else when the view was loaded then  */
	if (view->prev_pos.lineno < view->lines) {
		view->pos.offset = view->prev_pos.offset;
		view->pos.lineno = view->prev_pos.lineno;
		view->pos.col = view->prev_pos.col;
	}

	if (view->pos.lineno >= view->lines)
		view->pos.lineno = view->lines ? view->lines - 1 : 0;
	view->prev_pos.offset = view->prev_pos.lineno = view->prev_pos.col = 0;
	return true;
}

bool
check_view_position(struct view *view, unsigned long offset, unsigned long lineno)
{
	/* Ensure that the view position is in a valid state. */
	if (view->lines == 0)
		return false;
	if (offset >= view->lines)
		return false;
	if (lineno >= view->lines)
		return false;
	if (lineno < offset || lineno >= offset + view->height)
		return false;
	return true;
}

/*
 * View opening
 */

void
split_view(struct view *prev, struct view *view)
{
	display[1] = view;
	current_view = opt_focus_child ? 1 : 0;
	view->parent = prev;
	resize_display();

	if (prev->pos.lineno - prev->pos.offset >= prev->height) {
		/* Take the title line into account. */
		int lines = prev->pos.lineno - prev->pos.offset - prev->height + 1;

		/* Scroll the view that was split if the current line is
		 * outside the new limited view. */
		do_scroll_view(prev, lines);
	}

	if (view != prev && view_is_displayed(prev)) {
		/* "Blur" the previous view. */
		update_view_title(prev);
	}
}

void
maximize_view(struct view *view, bool redraw)
{
	memset(display, 0, sizeof(display));
	current_view = 0;
	display[current_view] = view;
	resize_display();
	if (redraw) {
		redraw_display(false);
		report_clear();
	}
}

void
load_view(struct view *view, struct view *prev, enum open_flags flags)
{
	bool refresh = !view_no_refresh_(view, flags);

	/* When prev == view it means this is the first loaded view. */
	if (prev && view != prev) {
		view->prev = prev;
	}

	if (!refresh && view_can_refresh(view) && (flags & OPEN_REFRESH) == 0) {
		/* Nothing */
	}

	if (!view->ops->open(view, flags)) {
		report("Failed to load %s view", view->name);
		return;
	}

	if (prev) {
		bool split = !!(flags & OPEN_SPLIT);

		if (split) {
			split_view(prev, view);
		} else {
			maximize_view(view, false);
		}
	}

	restore_view_position(view);

	if (view->pipe && view->lines == 0) {
		/* Clear the old view and let the incremental updating refill
		 * the screen. */
		werase(view->win);
		/* Do not clear the position if it is the first view. */
		if (!(flags & (OPEN_RELOAD | OPEN_REFRESH)) && view->prev) {
			view->prev_pos = view->pos;
			view->pos.offset = view->pos.lineno = view->pos.col = 0;
		}
		report_clear();
	} else if (view_is_displayed(view)) {
		redraw_view(view);
		report_clear();
	}
}

#define refresh_view(view) load_view(view, NULL, OPEN_REFRESH)
#define reload_view(view) load_view(view, NULL, OPEN_RELOAD)

void
open_view(struct view *prev, struct view *view, enum open_flags flags)
{
	bool reload = !!(flags & (OPEN_RELOAD | OPEN_PREPARED));
	int nviews = displayed_views();

	assert(flags ^ OPEN_REFRESH);

	if (view == prev && nviews == 1 && !reload) {
		report("Already in %s view", view->name);
		return;
	}

	if (!view_has_flags(view, VIEW_NO_GIT_DIR) && !repo.git_dir[0]) {
		report("The %s view is disabled in pager mode", view->name);
		return;
	}

	if (!view->keymap)
		view->keymap = get_keymap(view->name, strlen(view->name));
	load_view(view, prev ? prev : view, flags);
}

void
open_argv(struct view *prev, struct view *view, const char *argv[], const char *dir, enum open_flags flags)
{
	if (view->pipe)
		end_update(view, true);
	view->dir = dir;

	if (!argv_format(view->env, &view->argv, argv, !view->prev, false)) {
		report("Failed to format %s arguments", view->name);
	} else {
		open_view(prev, view, flags | OPEN_PREPARED);
	}
}

void
refresh_view(struct view *view)
{
	load_view(view, NULL, OPEN_REFRESH);
}

/*
 * Various utilities.
 */

static struct view *sorting_view;

#define apply_comparator(cmp, o1, o2) \
	(!(o1) || !(o2)) ? !!(o2) - !!(o1) : cmp(o1, o2)

#define number_compare(size1, size2)	(*(size1) - *(size2))
#define mode_compare(mode1, mode2)	(S_ISDIR(*(mode1)) ? S_ISDIR(*(mode2)) ? 0 : -1 : S_ISDIR(*(mode2)) ? 1 : 0)

static int
compare_view_column(enum view_column_type column, bool use_file_mode,
		    const struct line *line1, struct view_column_data *column_data1,
		    const struct line *line2, struct view_column_data *column_data2)
{
	switch (column) {
	case VIEW_COLUMN_AUTHOR:
		return apply_comparator(ident_compare, column_data1->author, column_data2->author);

	case VIEW_COLUMN_DATE:
		return apply_comparator(timecmp, column_data1->date, column_data2->date);

	case VIEW_COLUMN_ID:
		if (column_data1->reflog && column_data2->reflog)
			return apply_comparator(strcmp, column_data1->reflog, column_data2->reflog);
		return apply_comparator(strcmp, column_data1->id, column_data2->id);

	case VIEW_COLUMN_FILE_NAME:
		if (use_file_mode && column_data1->mode && column_data2->mode &&
		    S_ISDIR(*column_data1->mode) != S_ISDIR(*column_data2->mode))
			return S_ISDIR(*column_data1->mode) ? -1 : 1;
		return apply_comparator(strcmp, column_data1->file_name, column_data2->file_name);

	case VIEW_COLUMN_FILE_SIZE:
		return apply_comparator(number_compare, column_data1->file_size, column_data2->file_size);

	case VIEW_COLUMN_LINE_NUMBER:
		return line1->lineno - line2->lineno;

	case VIEW_COLUMN_MODE:
		return apply_comparator(mode_compare, column_data1->mode, column_data2->mode);

	case VIEW_COLUMN_REF:
		return apply_comparator(ref_compare, column_data1->ref, column_data2->ref);

	case VIEW_COLUMN_COMMIT_TITLE:
		return apply_comparator(strcmp, column_data1->commit_title, column_data2->commit_title);

	case VIEW_COLUMN_STATUS:
		return apply_comparator(strcmp_null, column_data1->status, column_data2->status);

	case VIEW_COLUMN_TEXT:
		return apply_comparator(strcmp_null, column_data1->text, column_data2->text);

	case VIEW_COLUMN_COMMITTER:
		return apply_comparator(ident_compare, column_data1->author, column_data2->author);
	}

	return 0;
}

int
ident_compare(const struct ident *i1, const struct ident *i2)
{
	if (!i1 || !i2)
		return (!!i1) - (!!i2);
	if (!i1->name || !i2->name)
		return (!!i1->name) - (!!i2->name);
	return strcmp(i1->name, i2->name);
}

static int
sort_view_compare(const void *l1, const void *l2)
{
	const struct line *line1 = l1;
	const struct line *line2 = l2;
	struct view_column_data column_data1 = {0};
	struct view_column_data column_data2 = {0};
	struct sort_state *sort = &sorting_view->sort;
	enum view_column_type column = get_sort_field(sorting_view);
	int cmp;

	if (!sorting_view->ops->get_column_data(sorting_view, line1, &column_data1))
		return -1;
	else if (!sorting_view->ops->get_column_data(sorting_view, line2, &column_data2))
		return 1;

	cmp = compare_view_column(column, true, line1, &column_data1, line2, &column_data2);

	/* Ensure stable sorting by comparing the (already compared) first
	 * column. */
	if (!cmp) {
		if (sorting_view->columns)
			cmp = compare_view_column(sorting_view->columns->type, false, line1, &column_data1, line2, &column_data2);
	}
	return sort->reverse ? -cmp : cmp;
}

enum view_column_type
get_sort_field(struct view *view)
{
	return view->sort.current ? view->sort.current->type : view->columns ? view->columns->type : VIEW_COLUMN_TEXT;
}

void
sort_view(struct view *view, bool change_field)
{
	struct sort_state *state = &view->sort;

	if (change_field) {
		while (true) {
			state->current = state->current ?
				state->current->next : view->columns;
			if (get_sort_field(view) == VIEW_COLUMN_ID &&
			    !state->current->opt.id.display)
				continue;
			break;
		}
	} else {
		state->reverse = !state->reverse;
	}

	sorting_view = view;
	qsort(view->line, view->lines, sizeof(*view->line), sort_view_compare);
}

/*
 * View columns
 */

struct view_column_info {
	struct view_column column;
	int width;
};

static struct view_column **
view_columns_option(struct view *view)
{
	int i;
	static const struct { const char *name; struct view_column ***opt; } map[] = {
		{ "main", NULL },
	};

	(void) map; (void) i;
	return get_view_columns_ptr(view->name);
}

static struct view_column **
get_view_columns_ptr(const char *name)
{
	if (!strcmp(name, "blame")) return &opt_blame_view;
	if (!strcmp(name, "blob")) return &opt_blob_view;
	if (!strcmp(name, "diff")) return &opt_diff_view;
	if (!strcmp(name, "grep")) return &opt_grep_view;
	if (!strcmp(name, "log")) return &opt_log_view;
	if (!strcmp(name, "reflog")) return &opt_reflog_view;
	if (!strcmp(name, "main")) return &opt_main_view;
	if (!strcmp(name, "pager")) return &opt_pager_view;
	if (!strcmp(name, "refs")) return &opt_refs_view;
	if (!strcmp(name, "stage")) return &opt_stage_view;
	if (!strcmp(name, "stash")) return &opt_stash_view;
	if (!strcmp(name, "status")) return &opt_status_view;
	if (!strcmp(name, "tree")) return &opt_tree_view;
	return NULL;
}

/* Returns true if the column configuration changed since last check. */
bool
view_column_info_changed_(struct view *view, bool update)
{
	struct view_column **opt = get_view_columns_ptr(view->name);
	struct view_column *column;
	int count = 0;
	bool changed = false;

	if (!opt)
		return false;

	if (view->columns != *opt) {
		view->columns = *opt;
		changed = true;
	}

	for (column = view->columns; column; column = column->next)
		count++;

	if (count != view->columns_count) {
		changed = true;
	} else if (view->column_info) {
		int i = 0;

		for (column = view->columns; column; column = column->next, i++) {
			struct view_column *saved = &view->column_info[i].column;

			if (saved->type != column->type ||
			    memcmp(&saved->opt, &column->opt, sizeof(column->opt))) {
				changed = true;
				break;
			}
		}
	} else {
		changed = true;
	}

	if (changed && update) {
		int i = 0;

		free(view->column_info);
		view->column_info = calloc(count ? count : 1, sizeof(*view->column_info));
		view->columns_count = count;
		for (column = view->columns; column; column = column->next, i++) {
			view->column_info[i].column = *column;
			view->column_info[i].column.next = NULL;
		}
	}

	return changed;
}

void
view_column_reset_(struct view *view)
{
	struct view_column *column;

	for (column = view->columns; column; column = column->next)
		column->width = 0;
}

struct view_column *
get_view_column(struct view *view, enum view_column_type type)
{
	struct view_column *column;

	for (column = view->columns; column; column = column->next)
		if (column->type == type)
			return column;
	return NULL;
}

static int
apply_step_int(int step, int value)
{
	if (step >= 0)
		return step;
	return MAX(value * -step / 100, 1);
}

static int
column_max_width(struct view *view, int maxwidth)
{
	if (maxwidth == 0)
		return 0;
	if (maxwidth < 0)
		return view->width * -maxwidth / 100;
	return maxwidth;
}

bool
view_column_info_update(struct view *view, struct line *line)
{
	struct view_column_data column_data = {0};
	struct view_column *column;
	bool changed = false;

	if (!view->columns || !view->ops->get_column_data)
		return false;
	if (!view->ops->get_column_data(view, line, &column_data))
		return false;

	for (column = view->columns; column; column = column->next) {
		const char *text = NULL;
		int width = -1;
		char buf[SIZEOF_STR];
		int maxwidth = 0;

		switch (column->type) {
		case VIEW_COLUMN_AUTHOR:
			if (column->opt.author.width) {
				width = column->opt.author.width;
				break;
			}
			if (column->opt.author.display == AUTHOR_DISPLAY_NO)
				break;
			text = mkauthor_ident(column_data.author, column->opt.author.width ? column->opt.author.width : 100, column->opt.author.display);
			maxwidth = column_max_width(view, column->opt.author.maxwidth);
			break;

		case VIEW_COLUMN_COMMITTER:
			if (column->opt.committer.width) {
				width = column->opt.committer.width;
				break;
			}
			if (column->opt.committer.display == AUTHOR_DISPLAY_NO)
				break;
			text = mkauthor_ident(column_data.author, column->opt.committer.width ? column->opt.committer.width : 100, column->opt.committer.display);
			maxwidth = column_max_width(view, column->opt.committer.maxwidth);
			break;

		case VIEW_COLUMN_DATE:
			if (column->opt.date.width) {
				width = column->opt.date.width;
				break;
			}
			if (column->opt.date.display == DATE_DISPLAY_NO)
				break;
			text = mkdate(column_data.date, column->opt.date.display, column->opt.date.local, column->opt.date.format);
			break;

		case VIEW_COLUMN_FILE_NAME:
			if (column->opt.file_name.width) {
				width = column->opt.file_name.width;
				break;
			}
			if (column->opt.file_name.display == FILENAME_DISPLAY_NO)
				break;
			text = column_data.file_name;
			maxwidth = column_max_width(view, column->opt.file_name.maxwidth);
			break;

		case VIEW_COLUMN_FILE_SIZE:
			if (column->opt.file_size.width) {
				width = column->opt.file_size.width;
				break;
			}
			if (!column->opt.file_size.display)
				break;
			text = column_data.file_size ? mkfilesize(*column_data.file_size, column->opt.file_size.display) : NULL;
			break;

		case VIEW_COLUMN_ID:
			if (column->opt.id.width) {
				width = column->opt.id.width;
				break;
			}
			if (!column->opt.id.display)
				break;
			if (opt_id_width) {
				width = opt_id_width;
				break;
			}
			if (column_data.reflog) {
				text = column_data.reflog;
				break;
			}
			if (column_data.id && !iscommit(column_data.id)) {
				text = column_data.id;
				break;
			}
			width = opt_core_abbrev ? opt_core_abbrev : 7;
			if (column->width < width)
				changed = true;
			if (column->width < width)
				column->width = width;
			width = -1;
			break;

		case VIEW_COLUMN_LINE_NUMBER:
			if (column->opt.line_number.width) {
				width = column->opt.line_number.width;
				break;
			}
			break;

		case VIEW_COLUMN_MODE:
			if (column->opt.mode.width) {
				width = column->opt.mode.width;
				break;
			}
			if (!column->opt.mode.display)
				break;
			text = column_data.mode ? mkmode(*column_data.mode) : NULL;
			break;

		case VIEW_COLUMN_REF:
			if (column->opt.ref.width) {
				width = column->opt.ref.width;
				break;
			}
			if (!column->opt.ref.display)
				break;
			text = column_data.ref ? column_data.ref->name : NULL;
			maxwidth = column_max_width(view, column->opt.ref.maxwidth);
			break;

		case VIEW_COLUMN_STATUS:
			if (!column->opt.status.display)
				break;
			text = column_data.status ? mkstatus(*column_data.status, column->opt.status.display) : NULL;
			break;

		case VIEW_COLUMN_COMMIT_TITLE:
		case VIEW_COLUMN_TEXT:
			break;
		}

		if (width >= 0) {
			if (column->width != width) {
				column->width = width;
				changed = true;
			}
			continue;
		}

		if (text) {
			int w = utf8_width_of(text, -1, -1);

			if (maxwidth && w > maxwidth)
				w = maxwidth;
			if (w > column->width) {
				column->width = w;
				changed = true;
			}
		}
		(void) buf;
	}

	return changed;
}

