void
init_display(void)
{
	bool no_display = !!getenv("TIG_NO_DISPLAY");
	const char *term;
	int x, y;

	/* Initialize the curses library */
	if (isatty(STDIN_FILENO) && !no_display) {
		cursed = !!initscr();
		opt_tty = stdin;
		opt_tty_fd = STDIN_FILENO;
	} else {
		/* Leave stdin and stdout alone when acting as a pager. */
		FILE *out_tty;

