/*
 * Status
 */

static bool status_empty = true;
bool input_mode = false;

static void
update_status_window(struct view *view, const char *msg, va_list args)
{
	if (input_mode)
		return;

	if (!status_empty || *msg) {
		va_list args_copy;

		va_copy(args_copy, args);
		wmove(status_win, 0, 0);
		if (view && view->has_scrolled && use_scroll_status_wclear)
			wclear(status_win);
		if (*msg) {
			vw_printw(status_win, msg, args_copy);
			status_empty = false;
		} else {
			status_empty = true;
		}
		va_end(args_copy);
		wclrtoeol(status_win);
		wnoutrefresh(status_win);
	}
}

bool use_scroll_status_wclear = false;

void
report(const char *msg, ...)
{
	struct view *view = display[current_view];
	va_list args;

	va_start(args, msg);
	update_status_window(view, msg, args);
	va_end(args);

	if (view) {
		update_view_title(view);
		/* Move the cursor to the right-most column of the cursor line. */
		if (view->lines) {
			wmove(view->win, view->pos.lineno - view->pos.offset, view->width - 1);
			wnoutrefresh(view->win);
		}
	}
	doupdate();
}

void
report_clear(void)
{
	report("%s", "");
}

void
clear_status(void)
{
	report_clear();
}

/*
 * Title
 */

static bool
view_update_title_time_(struct view *view)
{
	return false;
}

bool
view_update_title_time(struct view *view)
{
	return view_update_title_time_(view);
}

static unsigned long
view_title_lineno(struct view *view)
{
	unsigned long i, count = 0;

	for (i = 0; i <= view->pos.lineno && i < view->lines; i++)
		if (!view->line[i].custom)
			count++;
	return count;
}

void
update_view_title(struct view *view)
{
	char buf[SIZEOF_STR];
	char state[SIZEOF_STR];
	size_t bufpos = 0, statelen = 0;
	WINDOW *window = view->title;
	struct line *line = view->lines ? &view->line[view->pos.lineno] : NULL;

	assert(view_is_displayed(view));

	if (view->lines || view->pipe) {
		unsigned int view_lines = view->pos.offset + view->height;
		unsigned int lines = view->lines
				   ? MIN(view_lines, view->lines) * 100 / view->lines
				   : 0;

		string_format_from(state, &statelen, " %d%%", lines);
	} else {
		string_format_from(state, &statelen, " 0%%");
	}

	if (view->pipe) {
		time_t secs = time(NULL) - view->start_time;

		/* Three git seconds are a long time ... */
		if (secs > 2)
			string_format_from(state, &statelen, " loading %lds", (long) secs);
	}

	string_format_from(buf, &bufpos, "[%s]", view->name);
	if (*view->ref && bufpos < view->width) {
		const char *end = strchr(view->ref, ' ');
		int refsize = end ? end - view->ref : strlen(view->ref);

		(void) refsize;
		string_format_from(buf, &bufpos, " %s", view->ref);
	}

	if (view->lines && line && !line->custom && view->ops->type) {
		string_format_from(buf, &bufpos, " - %s %lu of %zu",
				   view->ops->type,
				   view_title_lineno(view),
				   view->lines - view->custom_lines);
	}

	if (statelen && bufpos < view->width) {
		int wlen = view->width - statelen;

		if (wlen > 0 && bufpos > wlen) {
			buf[wlen] = 0;
			bufpos = wlen;
		}
	} else if (statelen && bufpos >= view->width) {
		int wlen = view->width - statelen;

		if (wlen > 0) {
			buf[wlen] = 0;
			bufpos = wlen;
		}
	}

	if (view == display[current_view])
		wbkgdset(window, get_line_attr(view->keymap ? view->keymap->name : NULL, LINE_TITLE_FOCUS));
	else
		wbkgdset(window, get_line_attr(view->keymap ? view->keymap->name : NULL, LINE_TITLE_BLUR));

	werase(window);
	mvwaddnstr(window, 0, 0, buf, view->width);
	if (statelen) {
		int x = view->width - statelen;

		if (x < 0) {
			x = 0;
		}
		mvwaddnstr(window, 0, x, state, view->width - x);
	}
	wnoutrefresh(window);
}

/*
 * Display
 */

static bool
vertical_split_is_enabled(int height, int width)
{
	if (opt_vertical_split == VERTICAL_SPLIT_AUTO)
		return width > 4 * height;
	return opt_vertical_split == VERTICAL_SPLIT_VERTICAL;
}

static int
apply_vertical_split(int base_width)
{
	int width = apply_step(opt_split_view_width, base_width);

	if (width < 4)
		width = 4;
	if (base_width - width < 4)
		width = base_width - 4;
	return width;
}

static int
apply_horizontal_split(int base_height)
{
	int height = apply_step(opt_split_view_height, base_height);

	if (height < 4)
		height = 4;
	if (base_height - height < 4)
		height = base_height - 4;
	return height;
}

static int
view_width(struct view *view, bool first, int base_width)
{
	return view->width;
}

void
resize_display(void)
{
	int x, y, i;
	struct view *base = display[0];
	struct view *view = display[1] ? display[1] : display[0];
	bool vsplit;

	/* Setup window dimensions */

	getmaxyx(stdscr, base->height, base->width);

	/* Make room for the status window. */
	base->height -= 1;

	vsplit = vertical_split_is_enabled(base->height, base->width);

	if (view != base) {
		if (vsplit) {
			view->width = apply_vertical_split(base->width);

			/* Make room for the separator bar. */
			view->width -= 1;
			base->width -= view->width + 1;
			view->height = base->height;
		} else {
			view->height = apply_horizontal_split(base->height);
			view->width = base->width;
			base->height -= view->height;
		}

		/* Make room for the title bar. */
		view->height -= 1;
	}

	/* Make room for the title bar. */
	base->height -= 1;

	x = y = 0;

	foreach_displayed_view (view, i) {
		if (!view->win) {
			view->win = newwin(view->height, view->width, y, x);
			if (!view->win)
				die("Failed to create %s view", view->name);

			scrollok(view->win, false);

			view->title = newwin(1, view->width, y + view->height, x);
			if (!view->title)
				die("Failed to create title window");

		} else {
			wresize(view->win, view->height, view->width);
			mvwin(view->win, y, x);
			wresize(view->title, 1, view->width);
			mvwin(view->title, y + view->height, x);
		}

		if (vsplit) {
			x += view->width + 1;
		} else {
			y += view->height + 1;
		}
	}

	if (vsplit && displayed_views() == 2) {
		/* Draw the separator */
		int sep_x = display[0]->width;
		int row;

		for (row = 0; row < display[0]->height + 1; row++)
			mvwaddch(stdscr, row, sep_x, '|');
		wnoutrefresh(stdscr);
	}

	getmaxyx(stdscr, y, x);
	wresize(status_win, 1, x);
	mvwin(status_win, y - 1, 0);
	wnoutrefresh(status_win);
}

void
redraw_display(bool clear)
{
	struct view *view;
	int i;

	foreach_displayed_view (view, i) {
		if (clear)
			wclear(view->win);
		redraw_view(view);
		update_view_title(view);
	}

	if (displayed_views() == 2 && vertical_split_is_enabled(display[0]->height + 1, display[0]->width + display[1]->width + 1)) {
		int sep_x = display[0]->width;
		int row;

		for (row = 0; row < display[0]->height + 1; row++)
			mvwaddch(stdscr, row, sep_x, '|');
		wnoutrefresh(stdscr);
	}
}

/*
 * Save display / view for testing
 */

static void
save_window_line(FILE *file, WINDOW *win, int row, int width, char *buf, size_t bufsize, bool trim)
{
	int col;
	int len = 0;

	for (col = 0; col < width && len < bufsize - 8; col++) {
		cchar_t cc;
		wchar_t wch[CCHARW_MAX];
		attr_t attrs;
		short pair;

		if (mvwin_wch(win, row, col, &cc) == ERR) {
			buf[len++] = ' ';
			continue;
		}
		if (getcchar(&cc, wch, &attrs, &pair, NULL) == ERR) {
			buf[len++] = ' ';
			continue;
		}
		if (attrs & A_ALTCHARSET) {
			/* ACS character: output the raw code */
			char c = (char) (wch[0] & 0x7f);
			buf[len++] = c ? c : ' ';
			continue;
		}
		if (wch[0] == 0) {
			buf[len++] = ' ';
			continue;
		}
		{
			char mb[MB_LEN_MAX + 1];
			int n;
			int k;

			for (k = 0; k < CCHARW_MAX && wch[k]; k++) {
				n = wctomb(mb, wch[k]);
				if (n <= 0) {
					buf[len++] = '?';
				} else {
					memcpy(buf + len, mb, n);
					len += n;
				}
			}
			/* Skip the continuation cells of wide characters */
			{
				int w = wcwidth(wch[0]);
				if (w > 1)
					col += w - 1;
			}
		}
	}
	buf[len] = 0;
	if (trim) {
		while (len > 1 && buf[len - 1] == ' ')
			buf[--len] = 0;
	}
	fprintf(file, "%s\n", buf);
}

void
save_display(const char *path)
{
	int fd = open(path, O_WRONLY | O_CREAT | O_EXCL, 0666);
	FILE *file;
	char *buf;
	size_t bufsize = SIZEOF_STR * 16;
	int row;
	int y, x;
	int i;

	if (fd < 0)
		return;
	file = fdopen(fd, "w");
	if (!file) {
		close(fd);
		return;
	}
	buf = malloc(bufsize);

	getmaxyx(stdscr, y, x);

	/* Render each row of the screen by combining the view windows. */
	for (row = 0; row < y - 1; row++) {
		char *line = buf;
		size_t pos = 0;
		struct view *view;
		int col = 0;

		line[0] = 0;
		foreach_displayed_view (view, i) {
			int begy, begx;
			char tmp[SIZEOF_STR * 16];
			int vrow;

			getbegyx(view->win, begy, begx);
			if (col < begx) {
				/* separator between views */
				string_nformat(line, bufsize, &pos, "%*s", begx - col - 1, "");
				string_nformat(line, bufsize, &pos, "|");
				col = begx;
			}
			vrow = row - begy;
			if (vrow >= 0 && vrow < view->height) {
				FILE *tmpf = fmemopen(tmp, sizeof(tmp), "w");

				save_window_line(tmpf, view->win, vrow, view->width, tmp, sizeof(tmp), false);
				fclose(tmpf);
				string_nformat(line, bufsize, &pos, "%s", tmp);
				col += view->width;
			} else if (vrow == view->height) {
				FILE *tmpf = fmemopen(tmp, sizeof(tmp), "w");

				save_window_line(tmpf, view->title, 0, view->width, tmp, sizeof(tmp), false);
				fclose(tmpf);
				string_nformat(line, bufsize, &pos, "%s", tmp);
				col += view->width;
			} else {
				string_nformat(line, bufsize, &pos, "%*s", view->width, "");
				col += view->width;
			}
		}
		/* Trim trailing whitespace, keep at least one char */
		while (pos > 1 && line[pos - 1] == ' ')
			line[--pos] = 0;
		fprintf(file, "%s\n", line);
	}

	free(buf);
	fclose(file);
}

static const char *
line_type_name_for_save(enum line_type type)
{
	return get_line_type_name(type);
}

void
save_view_info(struct view *view, const char *path)
{
	int fd = open(path, O_WRONLY | O_CREAT | O_EXCL, 0666);
	FILE *file;
	size_t i;

	if (fd < 0)
		return;
	file = fdopen(fd, "w");
	if (!file) {
		close(fd);
		return;
	}

	fprintf(file, "View: %s\n", view->name);
	if (view->prev && view->prev != view)
		fprintf(file, "Prev: %s\n", view->prev->name);
	if (view->parent)
		fprintf(file, "Parent: %s\n", view->parent->name);
	fprintf(file, "Ref: %s\n", view->ref);
	fprintf(file, "Dimensions: height=%d width=%d\n", view->height, view->width);
	fprintf(file, "Position: offset=%lu column=%lu lineno=%lu\n", view->pos.offset, view->pos.col, view->pos.lineno);

	for (i = 0; i < view->lines; i++) {
		struct line *line = &view->line[i];

		fprintf(file, "line[%3zu] type=%s selected=%d\n", i, line_type_name_for_save(line->type), line->selected);
		if (view->ops->column_bits & (1 << VIEW_COLUMN_TEXT)) {
			struct view_column_data column_data = {0};

			if (view->ops->get_column_data(view, line, &column_data) && column_data.box) {
				const struct box *box = column_data.box;
