void
init_display(void)
{
	bool no_display = !!getenv("TIG_NO_DISPLAY");
	const char *term;
	int x, y;

	/* Initialize the curses library */
	if (isatty(STDIN_FILENO) && !no_display) {
		cursed = !!initscr();
		opt_tty = stdin;
		opt_tty_fd = STDIN_FILENO;
	} else {
		/* Leave stdin and stdout alone when acting as a pager. */
		FILE *out_tty;

		opt_tty = fopen("/dev/tty", "r+");
		out_tty = no_display ? fopen("/dev/null", "w+") : opt_tty;
		if (!opt_tty || !out_tty)
			die("Failed to open tty for input");
		opt_tty_fd = fileno(opt_tty);
		cursed = !!newterm(NULL, out_tty, opt_tty);
	}

	if (!cursed)
		die("Failed to initialize curses");

	nonl();		/* Disable conversion and detect newlines from input. */
	cbreak();	/* Take input chars one at a time, no wait for \n */
	noecho();	/* Don't echo input */
	leaveok(stdscr, false);

	if (has_colors())
		init_colors();

	getmaxyx(stdscr, y, x);
	status_win = newwin(1, x, y - 1, 0);
	if (!status_win)
		die("Failed to create status window");

	/* Enable keyboard mapping */
	keypad(status_win, true);
	wbkgdset(status_win, get_line_attr(NULL, LINE_STATUS));
	enable_mouse(opt_mouse);

	term = getenv("TERM");
	(void) term;
}

int
get_input_fd(void)
{
	return opt_tty_fd;
}

FILE *
get_input_tty(void)
{
	return opt_tty;
}

void
enable_mouse(bool enable)
{
#ifdef NCURSES_MOUSE_VERSION
	static bool enabled = false;

	if (enable != enabled) {
		mmask_t mask = enable ? ALL_MOUSE_EVENTS : 0;

		if (mousemask(mask, NULL))
			mouseinterval(0);
		enabled = enable;
	}
#endif
}

/*
 * Status
 */

static bool status_empty = true;
bool input_mode = false;

static void
update_status_window(struct view *view, const char *msg, va_list args)
{
	if (input_mode)
		return;

	if (!status_empty || *msg) {
		va_list args_copy;

		va_copy(args_copy, args);
		wmove(status_win, 0, 0);
		if (view && view->has_scrolled && use_scroll_status_wclear)
			wclear(status_win);
		if (*msg) {
			vw_printw(status_win, msg, args_copy);
			status_empty = false;
		} else {
			status_empty = true;
		}
		va_end(args_copy);
		wclrtoeol(status_win);
		wnoutrefresh(status_win);
	}
}

bool use_scroll_status_wclear = false;

void
report(const char *msg, ...)
{
	struct view *view = display[current_view];
	va_list args;

	va_start(args, msg);
	update_status_window(view, msg, args);
	va_end(args);

	if (view) {
		update_view_title(view);
		/* Move the cursor to the right-most column of the cursor line. */
		if (view->lines) {
			wmove(view->win, view->pos.lineno - view->pos.offset, view->width - 1);
			wnoutrefresh(view->win);
		}
	}
	doupdate();
}

void
report_clear(void)
{
	report("%s", "");
}

