/*
 * Title
 */

static bool
view_update_title_time_(struct view *view)
{
	return false;
}

bool
view_update_title_time(struct view *view)
{
	return view_update_title_time_(view);
}

static unsigned long
view_title_lineno(struct view *view)
{
	unsigned long i, count = 0;

	for (i = 0; i <= view->pos.lineno && i < view->lines; i++)
		if (!view->line[i].custom)
			count++;
	return count;
}

void
update_view_title(struct view *view)
{
	char buf[SIZEOF_STR];
	char state[SIZEOF_STR];
	size_t bufpos = 0, statelen = 0;
	WINDOW *window = view->title;
	struct line *line = view->lines ? &view->line[view->pos.lineno] : NULL;

	assert(view_is_displayed(view));

	if (view->lines || view->pipe) {
		unsigned int view_lines = view->pos.offset + view->height;
		unsigned int lines = view->lines
				   ? MIN(view_lines, view->lines) * 100 / view->lines
				   : 0;

		string_format_from(state, &statelen, " %d%%", lines);
	} else {
		string_format_from(state, &statelen, " 0%%");
	}

	if (view->pipe) {
		time_t secs = time(NULL) - view->start_time;

		/* Three git seconds are a long time ... */
		if (secs > 2)
			string_format_from(state, &statelen, " loading %lds", (long) secs);
	}

	string_format_from(buf, &bufpos, "[%s]", view->name);
	if (*view->ref && bufpos < view->width) {
		const char *end = strchr(view->ref, ' ');
		int refsize = end ? end - view->ref : strlen(view->ref);

		(void) refsize;
		string_format_from(buf, &bufpos, " %s", view->ref);
	}

	if (view->lines && line && !line->custom && view->ops->type) {
		string_format_from(buf, &bufpos, " - %s %lu of %zu",
				   view->ops->type,
				   view_title_lineno(view),
				   view->lines - view->custom_lines);
	}

	if (statelen && bufpos < view->width) {
		int wlen = view->width - statelen;

		if (wlen > 0 && bufpos > wlen) {
			buf[wlen] = 0;
			bufpos = wlen;
		}
	} else if (statelen && bufpos >= view->width) {
		int wlen = view->width - statelen;

		if (wlen > 0) {
			buf[wlen] = 0;
			bufpos = wlen;
		}
	}

	if (view == display[current_view])
		wbkgdset(window, get_line_attr(view->keymap ? view->keymap->name : NULL, LINE_TITLE_FOCUS));
	else
		wbkgdset(window, get_line_attr(view->keymap ? view->keymap->name : NULL, LINE_TITLE_BLUR));

	werase(window);
	mvwaddnstr(window, 0, 0, buf, view->width);
	if (statelen) {
		int x = view->width - statelen;

		if (x < 0) {
			x = 0;
		}
		mvwaddnstr(window, 0, x, state, view->width - x);
	}
	wnoutrefresh(window);
}

