static bool
vertical_split_is_enabled(int height, int width)
{
	if (opt_vertical_split == VERTICAL_SPLIT_AUTO)
		return width > 4 * height;
	return opt_vertical_split == VERTICAL_SPLIT_VERTICAL;
}

static int
apply_vertical_split(int base_width)
{
	int width = apply_step(opt_split_view_width, base_width);

	if (width < 4)
		width = 4;
	if (base_width - width < 4)
		width = base_width - 4;
	return width;
}

static int
apply_horizontal_split(int base_height)
{
	int height = apply_step(opt_split_view_height, base_height);

	if (height < 4)
		height = 4;
	if (base_height - height < 4)
		height = base_height - 4;
	return height;
}

