void
resize_display(void)
{
	int x, y, i;
	struct view *base = display[0];
	struct view *view = display[1] ? display[1] : display[0];
	bool vsplit;

	/* Setup window dimensions */

	getmaxyx(stdscr, base->height, base->width);

	/* Make room for the status window. */
	base->height -= 1;

	vsplit = vertical_split_is_enabled(base->height, base->width);

	if (view != base) {
		if (vsplit) {
			view->width = apply_vertical_split(base->width);

			/* Make room for the separator bar. */
			view->width -= 1;
			base->width -= view->width + 1;
			view->height = base->height;
		} else {
			view->height = apply_horizontal_split(base->height);
			view->width = base->width;
			base->height -= view->height;
		}

		/* Make room for the title bar. */
		view->height -= 1;
	}

	/* Make room for the title bar. */
	base->height -= 1;

	x = y = 0;

	foreach_displayed_view (view, i) {
		if (!view->win) {
			view->win = newwin(view->height, view->width, y, x);
			if (!view->win)
				die("Failed to create %s view", view->name);

			scrollok(view->win, false);

			view->title = newwin(1, view->width, y + view->height, x);
			if (!view->title)
				die("Failed to create title window");

		} else {
			wresize(view->win, view->height, view->width);
			mvwin(view->win, y, x);
			wresize(view->title, 1, view->width);
			mvwin(view->title, y + view->height, x);
		}

		if (vsplit) {
			x += view->width + 1;
		} else {
			y += view->height + 1;
		}
	}

	if (vsplit && displayed_views() == 2) {
		/* Draw the separator */
		int sep_x = display[0]->width;
		int row;

		for (row = 0; row < display[0]->height + 1; row++)
			mvwaddch(stdscr, row, sep_x, '|');
		wnoutrefresh(stdscr);
	}

	getmaxyx(stdscr, y, x);
	wresize(status_win, 1, x);
	mvwin(status_win, y - 1, 0);
	wnoutrefresh(status_win);
}

