/*
 * Prompt
 */

typedef enum input_status (*input_handler)(struct input *input, struct key *key);

enum input_status {
	INPUT_OK,
	INPUT_SKIP,
	INPUT_DELETE,
	INPUT_STOP,
	INPUT_CANCEL
};

struct input {
	input_handler handler;
	bool allow_empty;
	void *data;
	char buf[SIZEOF_STR];
	size_t pos;
};

static enum input_status
prompt_default_handler(struct input *input, struct key *key)
{
	if (key->multibytes)
		return INPUT_OK;

	if (key->ctrl) {
		switch (toupper(key->value)) {
		case 'C':
			return INPUT_CANCEL;
		case 'U':
			input->pos = 0;
			input->buf[0] = 0;
			return INPUT_SKIP;
		case 'W':
			while (input->pos > 0 && input->buf[input->pos - 1] == ' ')
				input->buf[--input->pos] = 0;
			while (input->pos > 0 && input->buf[input->pos - 1] != ' ')
				input->buf[--input->pos] = 0;
			return INPUT_SKIP;
		case 'H':
			return INPUT_DELETE;
		}
		return INPUT_SKIP;
	}

	switch (key->value) {
	case KEY_RETURN:
	case KEY_ENTER:
	case '\n':
		return input->pos || input->allow_empty ? INPUT_STOP : INPUT_CANCEL;

	case KEY_BACKSPACE:
	case 127:
		return input->pos ? INPUT_DELETE : INPUT_CANCEL;

	case KEY_ESC:
		return INPUT_CANCEL;

	default:
		return INPUT_OK;
	}
}

static char *
prompt_input(const char *prompt, struct input *input)
{
	enum input_status status = INPUT_OK;
	unsigned long pos = 0;
	struct key key;
	size_t promptlen = strlen(prompt);

	input->buf[0] = 0;
	input->pos = 0;

	while (status == INPUT_OK || status == INPUT_SKIP || status == INPUT_DELETE) {
		int ret;

		if (status != INPUT_DELETE || true) {
			werase(status_win);
			wmove(status_win, 0, 0);
			waddstr(status_win, prompt);
			waddstr(status_win, input->buf);
			wclrtoeol(status_win);
			wnoutrefresh(status_win);
		}

		ret = get_input(promptlen + input->pos, &key);
		if (ret == ERR)
			continue;

		if (key.value == KEY_RESIZE && !key.ctrl && !key.multibytes)
			continue;

		status = input->handler(input, &key);
		switch (status) {
		case INPUT_STOP:
		case INPUT_CANCEL:
			break;
		case INPUT_SKIP:
			break;
		case INPUT_DELETE:
			if (input->pos > 0) {
				/* Remove last UTF-8 character */
				size_t p = input->pos - 1;

				while (p > 0 && ((unsigned char) input->buf[p] & 0xC0) == 0x80)
					p--;
				input->pos = p;
				input->buf[input->pos] = 0;
			}
			status = INPUT_OK;
			break;
		case INPUT_OK:
			if (key.multibytes) {
				size_t len = strlen(key.bytes);

				if (input->pos + len < sizeof(input->buf) - 1) {
					memcpy(input->buf + input->pos, key.bytes, len);
					input->pos += len;
					input->buf[input->pos] = 0;
				}
			} else if (key.value >= 32 && key.value < 256 && !key.ctrl) {
				if (input->pos < sizeof(input->buf) - 1) {
					input->buf[input->pos++] = key.value;
					input->buf[input->pos] = 0;
				}
			}
			break;
		}
	}

	/* Clear the status window */
	status_empty_clear();

	(void) pos;
	if (status == INPUT_CANCEL)
		return NULL;

	input->buf[input->pos] = 0;
	return input->buf;
}

void
status_empty_clear(void)
{
	werase(status_win);
	wmove(status_win, 0, 0);
	wnoutrefresh(status_win);
}

