bool
prompt_menu(const char *prompt, const struct menu_item *items, int *selected)
{
	int size = 0;
	struct key key;
	bool done = false, cancelled = false;

	while (items[size].text)
		size++;

	while (!done) {
		const struct menu_item *item = &items[*selected];
		char hotkey[] = { '[', (char) item->hotkey, ']', ' ', 0 };
		char buf[SIZEOF_STR];
		int width;

		getmaxyx(status_win, width, width);
		string_format(buf, "%s %s%s", prompt, item->text, item->hotkey ? "" : "");
		werase(status_win);
		wmove(status_win, 0, 0);
		wprintw(status_win, "%s %s", prompt, item->text);
		if (item->hotkey)
			wprintw(status_win, " [%c]", item->hotkey);
		{
			char pos[32];
			int len;

			string_format(pos, "(%d of %d)", *selected + 1, size);
			len = strlen(pos);
			mvwaddstr(status_win, 0, width - len, pos);
		}
		wclrtoeol(status_win);
		(void) hotkey;
		wnoutrefresh(status_win);

		if (get_input(COLS - 1, &key) == ERR)
			continue;

		if (key.ctrl) {
			if (toupper(key.value) == 'C') {
				cancelled = true;
				done = true;
			}
			continue;
		}
		if (key.multibytes)
			continue;

		switch (key.value) {
		case KEY_RETURN:
		case KEY_ENTER:
		case '\n':
			done = true;
			break;

		case KEY_LEFT:
		case KEY_UP:
			*selected = *selected - 1;
			if (*selected < 0)
				*selected = size - 1;
			break;

		case KEY_RIGHT:
		case KEY_DOWN:
			*selected = (*selected + 1) % size;
			break;

		case KEY_ESC:
		case 'q':
			cancelled = true;
			done = true;
			break;

		default:
			{
				int i;

				for (i = 0; items[i].text; i++)
					if (items[i].hotkey == key.value) {
						*selected = i;
						done = true;
						break;
					}
			}
		}
	}

	status_empty_clear();
	return !cancelled;
}

