#include "tig.h"

bool opt_script_mode = false;
bool prompt_state = false;
static struct io script_io;
static bool script_active = false;
static char *script_line = NULL;	/* current line being consumed as keys */
static const char *script_pos = NULL;

bool
open_script(const char *path)
{
	if (script_active) {
		io_done(&script_io);
		script_active = false;
	}
	if (!io_open(&script_io, "%s", path))
		return false;
	script_active = true;
	opt_script_mode = true;
	script_line = NULL;
	script_pos = NULL;
	return true;
}

static bool
script_next_line(void)
{
	char *line;

	if (!script_active)
		return false;
	line = io_get(&script_io, '\n', true);
	if (!line) {
		io_done(&script_io);
		script_active = false;
		opt_script_mode = false;
		script_line = NULL;
		script_pos = NULL;
		return false;
	}
	script_line = line;
	script_pos = line;
	return true;
}

/* Reads a key from the script. Returns false when the script is exhausted. */
static bool
script_read_key(struct key *key)
{
	while (true) {
		if (!script_pos || !*script_pos) {
			if (!script_next_line())
				return false;
			if (!*script_pos)
				continue;
		}
		if (get_key_value(&script_pos, key) < 0) {
			/* Skip bad input */
			script_pos++;
			continue;
		}
		return true;
	}
}

/* Returns the rest of the current script line (used by the prompt). */
static const char *
script_rest_of_line(void)
{
	const char *rest = script_pos ? script_pos : "";

	script_pos = NULL;
	script_line = NULL;
	return rest;
}

bool
script_line_ready(void)
{
	return script_active;
}

char *
script_read_line(void)
{
	return NULL;
}

/*
 * Input
 */

static void
update_loading_views(bool *redraw);

int
get_input_char(void)
{
	return wgetch(status_win);
}

static int
read_tty_key(struct key *key, bool prompt)
{
	int c;

	while (true) {
		c = wgetch(status_win);
		if (c == ERR)
			return ERR;
		break;
	}

	memset(key, 0, sizeof(*key));

	if (c == KEY_RESIZE) {
		key->value = KEY_RESIZE;
		return 0;
	}

	if (c == 127) {
		key->value = KEY_BACKSPACE;
		return 0;
	}

	if (c >= 0 && c < 32 && c != KEY_TAB && c != KEY_RETURN && c != KEY_ESC && c != '\n') {
		key->ctrl = true;
		key->value = c + '@';
		return 0;
	}

	if (c == '\n')
		c = KEY_RETURN;

	if (c >= 0x80 && c < 0x100) {
		/* UTF-8 multibyte */
		char bytes[8];
		int len = utf8_char_length((char[]){ (char) c, 0 });
		int i;

		bytes[0] = c;
		for (i = 1; i < len; i++) {
			int n = wgetch(status_win);

			if (n == ERR)
				break;
			bytes[i] = n;
		}
		bytes[i] = 0;
		strncpy(key->bytes, bytes, sizeof(key->bytes) - 1);
		key->multibytes = true;
		return 0;
	}

	key->value = c;
	return 0;
}

/* Wait for input, driving view updates. Returns 0 on key, ERR on resize-only
 * or timeout handled internally. */
int
get_input(int prompt_position, struct key *key)
{
	struct view *view;
	int i;
	bool loading;

	if (prompt_position)
		input_mode = true;

	while (true) {
		if (script_active) {
			if (script_read_key(key))
				return 0;
			/* Script done; fall back to the tty. */
		}

		loading = false;
		foreach_displayed_view (view, i) {
			update_view(view);
			if (view->pipe)
				loading = true;
		}
		/* Also update non displayed loading views. */
		for (i = 0; i < views_count; i++) {
			if (views[i]->pipe && !view_is_displayed(views[i])) {
				update_view(views[i]);
				if (views[i]->pipe)
					loading = true;
			}
		}

		/* Update the cursor position. */
		if (prompt_position) {
			wmove(status_win, 0, prompt_position);
		} else {
			view = display[current_view];
			if (view && view->lines)
				wmove(view->win, view->pos.lineno - view->pos.offset, view->width - 1);
		}

		doupdate();

		if (loading) {
			wtimeout(status_win, 50);
		} else if (opt_refresh_mode == REFRESH_MODE_PERIODIC) {
			wtimeout(status_win, opt_refresh_interval * 1000);
		} else {
			wtimeout(status_win, -1);
		}

		{
			int c = wgetch(status_win);

			if (c == ERR) {
				if (!loading && opt_refresh_mode == REFRESH_MODE_PERIODIC) {
					foreach_displayed_view (view, i)
						if (view_can_refresh(view))
							refresh_view(view);
				}
				continue;
			}
			ungetch(c);
		}

		if (read_tty_key(key, prompt_position) == ERR)
			continue;

		if (key->value == KEY_RESIZE && !key->ctrl && !key->multibytes) {
			int height, width;

			getmaxyx(stdscr, height, width);

			wresize(status_win, 1, width);
			mvwin(status_win, height - 1, 0);
			wnoutrefresh(status_win);
			resize_display();
			redraw_display(true);
			continue;
		}

		input_mode = false;
		return 0;
	}
}

/*
 * Prompt
 */

typedef enum input_status (*input_handler)(struct input *input, struct key *key);

enum input_status {
	INPUT_OK,
	INPUT_SKIP,
	INPUT_DELETE,
	INPUT_STOP,
	INPUT_CANCEL
};

struct input {
	input_handler handler;
	bool allow_empty;
	void *data;
	char buf[SIZEOF_STR];
	size_t pos;
};

static enum input_status
prompt_default_handler(struct input *input, struct key *key)
{
	if (key->multibytes)
		return INPUT_OK;

	if (key->ctrl) {
		switch (toupper(key->value)) {
		case 'C':
			return INPUT_CANCEL;
		case 'U':
			input->pos = 0;
			input->buf[0] = 0;
			return INPUT_SKIP;
		case 'W':
			while (input->pos > 0 && input->buf[input->pos - 1] == ' ')
				input->buf[--input->pos] = 0;
			while (input->pos > 0 && input->buf[input->pos - 1] != ' ')
				input->buf[--input->pos] = 0;
			return INPUT_SKIP;
		case 'H':
			return INPUT_DELETE;
		}
		return INPUT_SKIP;
	}

	switch (key->value) {
	case KEY_RETURN:
	case KEY_ENTER:
	case '\n':
		return input->pos || input->allow_empty ? INPUT_STOP : INPUT_CANCEL;

	case KEY_BACKSPACE:
	case 127:
		return input->pos ? INPUT_DELETE : INPUT_CANCEL;

	case KEY_ESC:
		return INPUT_CANCEL;

	default:
		return INPUT_OK;
	}
}

static char *
prompt_input(const char *prompt, struct input *input)
{
	enum input_status status = INPUT_OK;
	unsigned long pos = 0;
	struct key key;
	size_t promptlen = strlen(prompt);

	input->buf[0] = 0;
	input->pos = 0;

	while (status == INPUT_OK || status == INPUT_SKIP || status == INPUT_DELETE) {
		int ret;

		if (status != INPUT_DELETE || true) {
			werase(status_win);
			wmove(status_win, 0, 0);
			waddstr(status_win, prompt);
			waddstr(status_win, input->buf);
			wclrtoeol(status_win);
			wnoutrefresh(status_win);
		}

		ret = get_input(promptlen + input->pos, &key);
		if (ret == ERR)
			continue;

		if (key.value == KEY_RESIZE && !key.ctrl && !key.multibytes)
			continue;

		status = input->handler(input, &key);
		switch (status) {
		case INPUT_STOP:
		case INPUT_CANCEL:
			break;
		case INPUT_SKIP:
			break;
		case INPUT_DELETE:
			if (input->pos > 0) {
				/* Remove last UTF-8 character */
				size_t p = input->pos - 1;

				while (p > 0 && ((unsigned char) input->buf[p] & 0xC0) == 0x80)
					p--;
				input->pos = p;
				input->buf[input->pos] = 0;
			}
			status = INPUT_OK;
			break;
		case INPUT_OK:
			if (key.multibytes) {
				size_t len = strlen(key.bytes);

				if (input->pos + len < sizeof(input->buf) - 1) {
					memcpy(input->buf + input->pos, key.bytes, len);
					input->pos += len;
					input->buf[input->pos] = 0;
				}
			} else if (key.value >= 32 && key.value < 256 && !key.ctrl) {
				if (input->pos < sizeof(input->buf) - 1) {
					input->buf[input->pos++] = key.value;
					input->buf[input->pos] = 0;
				}
			}
			break;
		}
	}

	/* Clear the status window */
	status_empty_clear();

	(void) pos;
	if (status == INPUT_CANCEL)
		return NULL;

	input->buf[input->pos] = 0;
	return input->buf;
}

void
status_empty_clear(void)
{
	werase(status_win);
	wmove(status_win, 0, 0);
	wnoutrefresh(status_win);
}

static struct input prompt_input_state;

char *
read_prompt_incremental(const char *prompt, bool edit_mode, bool allow_empty, void *fn, void *data)
{
	struct input *input = &prompt_input_state;

	memset(input, 0, sizeof(*input));
	input->handler = prompt_default_handler;
	input->allow_empty = allow_empty;
	input->data = data;
	(void) edit_mode; (void) fn;

	return prompt_input(prompt, input);
}

char *
read_prompt(const char *prompt)
{
	return read_prompt_incremental(prompt, false, false, NULL, NULL);
}

/* Prompt used for the ':' command. In script mode the rest of the line is
 * consumed. */
static char *
read_command_prompt(void)
{
	static char buf[SIZEOF_STR];

	if (script_active && script_pos) {
		const char *rest = script_rest_of_line();

		string_ncopy(buf, rest, strlen(rest));
		return buf;
	}
	return read_prompt(":");
}

bool
prompt_yesno(const char *prompt)
{
	char prompt2[SIZEOF_STR];
	struct key key;
	bool answer = false;

	string_format(prompt2, "%s [Yy/Nn]", prompt);
	werase(status_win);
	wmove(status_win, 0, 0);
	waddstr(status_win, prompt2);
	wclrtoeol(status_win);
	wnoutrefresh(status_win);

	while (true) {
		if (get_input(strlen(prompt2), &key) == ERR)
			continue;
		if (key.ctrl || key.multibytes) {
			answer = false;
			break;
		}
		if (key.value == 'y' || key.value == 'Y') {
			answer = true;
			break;
		}
		if (key.value == 'n' || key.value == 'N' || key.value == KEY_ESC || key.value == KEY_RETURN) {
			answer = false;
			break;
		}
	}
	status_empty_clear();
	return answer;
}

bool
prompt_menu(const char *prompt, const struct menu_item *items, int *selected)
{
	int size = 0;
	struct key key;
	bool done = false, cancelled = false;

	while (items[size].text)
		size++;

	while (!done) {
		const struct menu_item *item = &items[*selected];
		char hotkey[] = { '[', (char) item->hotkey, ']', ' ', 0 };
		char buf[SIZEOF_STR];
		int width;

		getmaxyx(status_win, width, width);
		string_format(buf, "%s %s%s", prompt, item->text, item->hotkey ? "" : "");
		werase(status_win);
		wmove(status_win, 0, 0);
		wprintw(status_win, "%s %s", prompt, item->text);
		if (item->hotkey)
			wprintw(status_win, " [%c]", item->hotkey);
		{
			char pos[32];
			int len;

			string_format(pos, "(%d of %d)", *selected + 1, size);
			len = strlen(pos);
			mvwaddstr(status_win, 0, width - len, pos);
		}
		wclrtoeol(status_win);
		(void) hotkey;
		wnoutrefresh(status_win);

		if (get_input(COLS - 1, &key) == ERR)
			continue;

		if (key.ctrl) {
			if (toupper(key.value) == 'C') {
				cancelled = true;
				done = true;
			}
			continue;
		}
		if (key.multibytes)
			continue;

		switch (key.value) {
		case KEY_RETURN:
		case KEY_ENTER:
		case '\n':
			done = true;
			break;

		case KEY_LEFT:
		case KEY_UP:
			*selected = *selected - 1;
			if (*selected < 0)
				*selected = size - 1;
			break;

		case KEY_RIGHT:
		case KEY_DOWN:
			*selected = (*selected + 1) % size;
			break;

		case KEY_ESC:
		case 'q':
			cancelled = true;
			done = true;
			break;

		default:
			{
				int i;

				for (i = 0; items[i].text; i++)
					if (items[i].hotkey == key.value) {
						*selected = i;
						done = true;
						break;
					}
			}
		}
	}

	status_empty_clear();
	return !cancelled;
}

