	int hotkey;
	const char *name;
	const char *text;
};

static const struct toggle_entry toggle_entries[] = {
	{ '.', "line-number", "Toggle line numbers" },
	{ 'D', "date", "Toggle dates" },
	{ 'A', "author", "Toggle author" },
	{ 'T', "committer", "Toggle committer" },
	{ '~', "line-graphics", "Toggle graphics" },
	{ 'g', "commit-title-graph", "Toggle revision graph" },
	{ '#', "file-name", "Toggle file names" },
	{ '*', "file-size", "Toggle file sizes" },
	{ 'W', "ignore-space", "Toggle space changes" },
	{ 'l', "commit-order", "Toggle commit order" },
	{ 'F', "commit-title-refs", "Toggle reference display" },
	{ 'C', "show-changes", "Toggle local change display" },
	{ 'X', "id", "Toggle commit ID display" },
	{ '%', "file-filter", "Toggle file filtering" },
	{ '^', "rev-filter", "Toggle revision filtering" },
	{ '$', "commit-title-overflow", "Toggle commit title overflow display" },
	{ 'd', "status-show-untracked-dirs", "Toggle untracked directory info" },
	{ '|', "vertical-split", "Toggle view split" },
};

int
get_toggle_entries(const struct toggle_entry **entries)
{
	*entries = toggle_entries;
	return ARRAY_SIZE(toggle_entries);
}

static const char *
toggle_option_text(const char *text)
{
	static char buf[SIZEOF_STR];

	/* "Toggle line numbers" -> "line numbers" */
	if (!prefixcmp(text, "Toggle "))
		text += STRING_SIZE("Toggle ");
	string_format(buf, "%s", text);
	return buf;
}

void
prompt_menu_options(void)
{
	struct menu_item items[ARRAY_SIZE(toggle_entries) + 1];
	int selected = 0;
	int i;

	for (i = 0; i < ARRAY_SIZE(toggle_entries); i++) {
		items[i].hotkey = toggle_entries[i].hotkey;
		items[i].text = toggle_option_text(toggle_entries[i].text);
		items[i].text = str_dup(items[i].text);
		items[i].data = (void *) toggle_entries[i].name;
	}
	items[i].text = NULL;
	items[i].hotkey = 0;
	items[i].data = NULL;

	if (prompt_menu("Toggle option", items, &selected)) {
		const char *argv[] = { ":toggle", (const char *) items[selected].data, NULL };

		run_prompt_command(display[current_view], argv);
	}

	for (i = 0; i < ARRAY_SIZE(toggle_entries); i++)
		free((void *) items[i].text);
}

/*
 * Toggle request
 */

static enum request
run_toggle(struct view *view, const char *argv[])
{
	char msg[SIZEOF_STR] = "";
	const char *name = argv[1];
	enum status_code code;
	bool changed;

	if (!name) {
		report("No option name given to :toggle");
		return REQ_NONE;
	}

	/* Column toggles use the view name prefix for the message */
	code = toggle_option(view->columns ? &view->columns : NULL, view->name, name, argv + 2, msg, sizeof(msg));
	if (code != SUCCESS) {
		report("%s", get_status_message(code));
		return REQ_NONE;
	}

	/* Fix up the message format to use the view column names */
	changed = true;
	if (*msg)
		report("%s", msg);

	/* Options that require reloading */
	if (!strcmp(name, "commit-title-graph") || !strcmp(name, "commit-order") ||
	    !strcmp(name, "show-changes") || !strcmp(name, "ignore-space") ||
	    !strcmp(name, "diff-context") || !strcmp(name, "file-filter") ||
	    !strcmp(name, "rev-filter") || !strcmp(name, "show-untracked") ||
	    !strcmp(name, "status-show-untracked-dirs") || !strcmp(name, "status-show-untracked-files") ||
	    !strcmp(name, "diff-options") || !strcmp(name, "word-diff") ||
	    !strcmp(name, "mailmap") || !strcmp(name, "show-notes") ||
	    !strcmp(name, "diff-highlight") || !strcmp(name, "diff-noprefix")) {
		struct view *v;
		int i;

		foreach_displayed_view (v, i) {
			if (view_can_refresh(v) || v->ops->flags & VIEW_DIFF_LIKE || v->ops->flags & VIEW_LOG_LIKE || v->ops->flags & VIEW_STATUS_LIKE)
				reload_or_refresh(v);
		}
		(void) changed;
		return REQ_NONE;
	}

	if (!strcmp(name, "vertical-split")) {
		resize_display();
		redraw_display(true);
		return REQ_NONE;
	}

	if (!strcmp(name, "line-graphics") || !strcmp(name, "mouse")) {
		if (!strcmp(name, "mouse"))
			enable_mouse(opt_mouse);
		redraw_display(true);
		return REQ_NONE;
	}

	redraw_display(false);
	return REQ_NONE;
}

void
reload_or_refresh(struct view *view)
{
	if (view->ops->flags & VIEW_REFRESH)
		load_view(view, NULL, OPEN_REFRESH);
	else
		load_view(view, NULL, OPEN_RELOAD);
}

/*
 * Prompt commands
 */

static bool
prompt_open_pager(struct view *view, const char *argv[])
{
	struct view *pager = get_view_by_name("pager");

	open_argv(view, pager, argv, repo.cdup, OPEN_PREPARED | OPEN_WITH_STDERR);
	return true;
}

static enum request
run_exec(struct view *view, const char *argv[], struct run_request_flags *flags)
{
	struct run_request req = { view->keymap, *flags, NULL };
	const char **tmp = NULL;

	if (!argv_append_array(&tmp, argv))
		return REQ_NONE;
	req.argv = tmp;
	return exec_run_request(view, &req);
}

enum request
run_prompt_command(struct view *view, const char *argv[])
{
	enum request request;
	const char *cmd = argv[0];
	size_t cmdlen;

	if (!cmd)
		return REQ_NONE;
	cmdlen = strlen(cmd);

	if (string_isnumber(cmd)) {
		unsigned long lineno = atoi(cmd);

		if (!lineno || lineno > view->lines) {
			report("Unable to parse '%s' as a line number", cmd);
		} else {
			select_view_line(view, lineno - 1);
		}
		return REQ_NONE;
	}

	if (iscommit(cmd)) {
		struct view *main = get_view_by_name("main");
		const char *gargv[] = { "goto", cmd, NULL };

		(void) main;
		return run_prompt_command(view, gargv);
	}

	if (cmdlen > 1 && (cmd[0] == '/' || cmd[0] == '?')) {
		char search[SIZEOF_STR];

		string_ncopy(search, cmd + 1, cmdlen - 1);
		if (argv[1]) {
			char *tmp = argv_to_string_alloc(argv + 1, " ");

			string_format(search, "%s %s", cmd + 1, tmp);
			free(tmp);
		}
		string_copy(argv_env.search, search);
		return cmd[0] == '/' ? REQ_SEARCH : REQ_SEARCH_BACK;
	}

	if (cmd[0] == '!') {
		struct run_request_flags flags = { 0 };

		if (cmdlen == 1) {
			if (!argv[1])
				return REQ_NONE;
			argv++;
		} else {
			argv[0] = cmd + 1;
		}
		(void) flags;
		if (!*argv[0] && !argv[1])
			return REQ_NONE;
		prompt_open_pager(view, argv);
		return REQ_NONE;
	}

	if (!strcmp(cmd, "goto")) {
		if (!argv[1] || !*argv[1]) {
			report("goto requires an argument");
			return REQ_NONE;
		}
		return do_goto(view, argv[1]);
	}

	if (!strcmp(cmd, "save-display")) {
		if (!argv[1]) {
			report("save-display requires a file path");
			return REQ_NONE;
		}
		save_display(argv[1]);
		return REQ_NONE;
	}

	if (!strcmp(cmd, "save-options")) {
		if (!argv[1]) {
			report("save-options requires a file path");
			return REQ_NONE;
		}
		save_options(argv[1]);
		return REQ_NONE;
	}

	if (!strcmp(cmd, "save-view")) {
		if (!argv[1]) {
			report("save-view requires a file path");
			return REQ_NONE;
		}
		save_view_info(view, argv[1]);
		return REQ_NONE;
	}

	if (!strcmp(cmd, "script")) {
		if (!argv[1]) {
			report("script requires a file path");
			return REQ_NONE;
		}
		if (!open_script(argv[1]))
			report("Failed to open %s", argv[1]);
		return REQ_NONE;
	}

	if (!strcmp(cmd, "echo")) {
		char buf[SIZEOF_STR] = "";

		if (argv[1])
			argv_to_string(argv + 1, buf, sizeof(buf), " ");
		report("%s", buf);
		return REQ_NONE;
	}

	if (!strcmp(cmd, "exec")) {
		struct run_request_flags flags;
		const char **eargv = argv + 1;

		if (!eargv[0]) {
			report("exec requires arguments");
			return REQ_NONE;
		}
		if (!parse_run_request_flags(&flags, eargv)) {
			report("Unknown command flag");
			return REQ_NONE;
		}
		if (!*eargv[0])
			eargv++;
		return run_exec(view, eargv, &flags);
	}

	if (!strcmp(cmd, "toggle"))
		return run_toggle(view, argv);

	if (!strcmp(cmd, "set") || !strcmp(cmd, "bind") || !strcmp(cmd, "color") || !strcmp(cmd, "source")) {
		enum status_code code;
		int argc;

		for (argc = 0; argv[argc]; argc++);
		if (!strcmp(cmd, "set"))
			code = option_set_command(argc - 1, argv + 1);
		else if (!strcmp(cmd, "bind"))
			code = option_bind_command(argc - 1, argv + 1);
		else if (!strcmp(cmd, "color"))
			code = option_color_command(argc - 1, argv + 1);
		else
			code = option_source_command(argc - 1, argv + 1);

		if (code != SUCCESS) {
			report("%s", get_status_message(code));
			return REQ_NONE;
		}
		if (!strcmp(cmd, "color") || !strcmp(cmd, "source"))
			init_colors();
		if (!strcmp(cmd, "set")) {
			/* Options that alter the loaded data require reload. */
			const char *name = argv[1];
			struct view *v;
			int i;

			if (name && (!prefixcmp(name, "diff-") || !strcmp(name, "show-changes") || !strcmp(name, "show-untracked") ||
				     !strcmp(name, "commit-order") || !strcmp(name, "ignore-space") || !strcmp(name, "word-diff") ||
				     !strcmp(name, "file-filter") || !strcmp(name, "rev-filter") || !strcmp(name, "mailmap") ||
				     !strcmp(name, "show-notes") || !prefixcmp(name, "status-show") || !prefixcmp(name, "log-options") ||
				     !prefixcmp(name, "main-options") || !prefixcmp(name, "blame-options") ||
				     strstr(name, "commit-title-graph") || strstr(name, "-view") || !strcmp(name, "vertical-split") ||
				     !strcmp(name, "split-view-height") || !strcmp(name, "split-view-width"))) {
				if (!strcmp(name, "vertical-split") || !strcmp(name, "split-view-height") || !strcmp(name, "split-view-width")) {
					resize_display();
					redraw_display(true);
					return REQ_NONE;
				}
				if (strstr(name, "-view") && !strstr(name, "commit-title-graph")) {
					/* Column setting: redraw */
					if (strstr(name, "main-view-commit-title-graph") || !strcmp(name, "main-view") || !strcmp(name, "reflog-view")) {
						foreach_displayed_view (v, i)
							if (v->ops->flags & VIEW_LOG_LIKE)
								reload_or_refresh(v);
					}
					redraw_display(false);
					return REQ_NONE;
				}
				foreach_displayed_view (v, i)
					reload_or_refresh(v);
				return REQ_NONE;
			}
		}
		redraw_display(false);
		return REQ_NONE;
	}

	request = get_request(cmd);
	if (request != REQ_UNKNOWN)
		return request;

	/* Check keybindings */
	{
		struct key key;
		const char *keyname = cmd;

		if (!argv[1] && get_key_value(&keyname, &key) == 0 && !*keyname) {
			int matches = 0;
			enum request req = get_keybinding(view->keymap, &key, 1, &matches);

			if (req != REQ_UNKNOWN && req != REQ_NONE)
				return req;
		}
	}

	report("Unknown option command: %s", cmd);
	return REQ_NONE;
}

enum request
do_goto(struct view *view, const char *rev)
{
	const char *rev_parse_argv[] = { "git", "rev-parse", "--verify", "-q", rev, NULL };
	char id[SIZEOF_STR];
	struct view *main_view = get_view_by_name("main");
	size_t i;

	(void) main_view;
	if (!io_run_buf(rev_parse_argv, id, sizeof(id), repo.cdup, false) || !*id) {
		report("Expression '%s' is not a meaningful revision", rev);
		return REQ_NONE;
	}

	/* Find the commit in the current view, if it tracks commits. */
	for (i = 0; i < view->lines; i++) {
		struct view_column_data column_data = {0};

		if (view->ops->get_column_data &&
		    view->ops->get_column_data(view, &view->line[i], &column_data) &&
		    column_data.id && !strncmp(column_data.id, id, strlen(column_data.id) > 7 ? 7 : strlen(column_data.id)) &&
		    !strncmp(column_data.id, id, strlen(column_data.id))) {
			select_view_line(view, i);
			report_clear();
			return REQ_NONE;
		}
	}

	/* Otherwise look at the main view. */
	{
		struct view *main = get_view_by_name("main");

		if (main && view != main) {
			for (i = 0; i < main->lines; i++) {
				struct view_column_data column_data = {0};

				if (main->ops->get_column_data(main, &main->line[i], &column_data) &&
				    column_data.id && !strcmp(column_data.id, id)) {
					string_ncopy(argv_env.goto_id, id, strlen(id));
					open_view(view, main, OPEN_DEFAULT);
					select_view_line(main, i);
					return REQ_NONE;
				}
			}
		}
	}

	report("Unable to find commit '%s'", id);
	return REQ_NONE;
}

/*
 * External commands
 */

void
open_editor(const char *file, unsigned int lineno)
{
	const char *editor_argv[SIZEOF_ARG + 3] = { "vi", file, NULL };
	char editor_cmd[SIZEOF_STR];
	char lineno_cmd[SIZEOF_STR];
	const char *editor;
	int argc = 0;

	editor = getenv("TIG_EDITOR");
	if (!editor)
		editor = getenv("GIT_EDITOR");
	if (!editor && *opt_editor)
		editor = opt_editor;
	if (!editor)
		editor = getenv("VISUAL");
	if (!editor)
		editor = getenv("EDITOR");
	if (!editor)
		editor = "vi";

	string_ncopy(editor_cmd, editor, strlen(editor));
	if (!argv_from_string_no_quotes(editor_argv, &argc, editor_cmd)) {
		report("Failed to read editor command");
		return;
	}

	if (lineno && opt_editor_line_number && string_format(lineno_cmd, "+%u", lineno))
		editor_argv[argc++] = lineno_cmd;
	editor_argv[argc] = file;
	editor_argv[argc + 1] = NULL;
	if (!open_external_viewer(editor_argv, repo.cdup, false, false, false, true, false, ""))
		report("Failed to open editor");
}

bool
open_external_viewer(const char *argv[], const char *dir, bool silent, bool confirm, bool echo, bool quick, bool refresh, const char *notice)
{
	bool ok;

	if (echo) {
		char buf[SIZEOF_STR] = "";
		struct io io;

		if (!io_run(&io, IO_RD, dir, NULL, argv)) {
			report("Failed to run command");
			return false;
		}
		io_read_buf(&io, buf, sizeof(buf), true);
		report("%s", buf);
		return true;
	}

	if (silent || (!isatty(STDIN_FILENO) && !getenv("TIG_NO_DISPLAY") && false)) {
		ok = io_run_bg(argv, dir);
	} else {
		clear();
		refresh();
		endwin();                  /* restore original tty modes */
		ok = io_run_fg(argv, dir);
		if (confirm || !ok) {
			if (!ok && *notice)
				fprintf(stderr, "%s", notice);
			fprintf(stderr, "Press Enter to continue");
			getc(get_input_tty());
		}
		if (!quick) {
			/* nothing */
		}
		fseek(stdin, 0, SEEK_END);
		redraw_display(true);
	}
	return ok;
}

enum request
exec_run_request(struct view *view, struct run_request *req)
{
	const char **argv = NULL;
	bool confirmed = false;
	enum request request = REQ_NONE;
	char cmd[SIZEOF_STR];
	const char *req_argv[SIZEOF_ARG];
	int req_argc = 0;

	if (!argv_to_string(req->argv, cmd, sizeof(cmd), " ")
	    || !argv_from_string(req_argv, &req_argc, cmd)
	    || !argv_format(view->env, &argv, req_argv, false, true)) {
		report("Failed to format arguments");
		return REQ_NONE;
	}

	if (req->flags.internal) {
		request = run_prompt_command(view, argv);

	} else {
		confirmed = !req->flags.confirm;

		if (req->flags.confirm) {
			char cmd2[SIZEOF_STR], prompt[SIZEOF_STR];
			const char *and_exit = req->flags.exit ? " and exit" : "";

			if (argv_to_string(argv, cmd2, sizeof(cmd2), " ") &&
			    string_format(prompt, "Run `%s`%s?", cmd2, and_exit) &&
			    prompt_yesno(prompt)) {
				confirmed = true;
			}
		}

		if (confirmed)
			open_external_viewer(argv, repo.cdup, req->flags.silent, false,
					     req->flags.echo, req->flags.quick, true, "");
	}

	if (argv)
		argv_free(argv);
	free(argv);

	if (request == REQ_NONE) {
		if (req->flags.confirm && !confirmed)
			request = REQ_NONE;

		else if (req->flags.exit)
			request = REQ_QUIT;

		else if (!req->flags.internal && view_can_refresh(view))
			request = REQ_REFRESH;

	}
	return request;
}

char *
read_prompt_command(void)
{
	return read_command_prompt();
}
