static bool
is_rev_parse_passthrough(const char *arg)
{
	/* Options handled directly as command line args. */
	if (!prefixcmp(arg, "--"))
		return false;
	if (!prefixcmp(arg, "-S") || !prefixcmp(arg, "-G") || !prefixcmp(arg, "-L"))
		return false;
	return true;
}

static void
filter_rev_parse(const char ***args, const char *arg1, const char *arg2, const char *argv[])
{
	const char *rev_parse_argv[SIZEOF_ARGV + 8] = { "git", "rev-parse", arg1, arg2 };
	struct io io;
	int argc = 4;
	int i;
	char *line;

	for (i = 0; argv[i] && argc < SIZEOF_ARGV + 7; i++)
		rev_parse_argv[argc++] = argv[i];
	rev_parse_argv[argc] = NULL;

	if (!io_run(&io, IO_RD, NULL, NULL, rev_parse_argv))
		die("Failed to run git rev-parse");

	while ((line = io_get(&io, '\n', true))) {
		line = chomp_string(line);
		if (*line)
			argv_append(args, line);
	}

	if (!io_done(&io))
		die("No revisions match the given arguments.");
}

static void
filter_options(const char *argv[], bool blame)
{
	const char **flags = NULL;
	const char **revs = NULL;
	const char **files = NULL;
	const char **direct = NULL;
	const char **rev_parse_input = NULL;
	int i;
	bool seen_dashdash = false;

	for (i = 0; argv[i]; i++) {
		const char *arg = argv[i];

		if (!strcmp(arg, "--")) {
			seen_dashdash = true;
			argv_append(&rev_parse_input, arg);
			continue;
		}
		if (!seen_dashdash && arg[0] == '-' && !is_rev_parse_passthrough(arg)) {
			argv_append(&direct, arg);
			continue;
		}
		argv_append(&rev_parse_input, arg);
	}

	if (!rev_parse_input)
		argv_append(&rev_parse_input, "");

	{
		const char *empty[] = { NULL };
		const char **input = rev_parse_input && rev_parse_input[0] && *rev_parse_input[0] ? rev_parse_input : empty;

		filter_rev_parse(&files, "--no-revs", "--no-flags", input);
		filter_rev_parse(&flags, "--flags", "--no-revs", input);
		filter_rev_parse(&revs, "--symbolic", "--revs-only", input);
	}

	argv_free(opt_cmdline_args);
	free(opt_cmdline_args);
	opt_cmdline_args = NULL;
	if (flags)
		argv_append_array(&opt_cmdline_args, flags);
	if (direct)
		argv_append_array(&opt_cmdline_args, direct);

	argv_free(opt_rev_args);
	free(opt_rev_args);
	opt_rev_args = NULL;
	if (revs)
		argv_append_array(&opt_rev_args, revs);

	argv_free(opt_file_args);
	free(opt_file_args);
	opt_file_args = NULL;
	if (files)
		argv_append_array(&opt_file_args, files);

	(void) blame;
}

static enum request
parse_options(int argc, const char *argv[], bool pager_mode)
{
	enum request request;
	const char *subcommand;
	bool seen_dashdash = false;
	const char **filter_argv = NULL;
	int i;

	request = pager_mode ? REQ_VIEW_PAGER : REQ_VIEW_MAIN;

	if (argc <= 1)
		return request;

	subcommand = argv[1];
	if (!strcmp(subcommand, "status")) {
		request = REQ_VIEW_STATUS;

	} else if (!strcmp(subcommand, "blame")) {
		request = REQ_VIEW_BLAME;

	} else if (!strcmp(subcommand, "show")) {
		request = REQ_VIEW_DIFF;

	} else if (!strcmp(subcommand, "log")) {
		request = REQ_VIEW_LOG;

	} else if (!strcmp(subcommand, "reflog")) {
		request = REQ_VIEW_REFLOG;

	} else if (!strcmp(subcommand, "stash")) {
		request = REQ_VIEW_STASH;

	} else if (!strcmp(subcommand, "grep")) {
		request = REQ_VIEW_GREP;

	} else if (!strcmp(subcommand, "refs")) {
		request = REQ_VIEW_REFS;

	} else {
		subcommand = NULL;
	}

	for (i = 1 + !!subcommand; i < argc; i++) {
		const char *opt = argv[i];

		/* Skip options handled by the git command. */
		if (seen_dashdash) {
			argv_append(&filter_argv, opt);
			continue;
		}

		if (!strcmp(opt, "--")) {
			seen_dashdash = true;
			argv_append(&filter_argv, opt);
			continue;
		}

		if (opt[0] == '+' && string_isnumber(opt + 1)) {
			opt_lineno_arg = atoi(opt + 1);
			continue;
		}

		if (!strcmp(opt, "-v") || !strcmp(opt, "--version")) {
			printf("tig version %s\n", TIG_VERSION);
			printf("%s", "ncursesw version " NCURSES_VERSION "." );
			printf("%d\n", NCURSES_VERSION_PATCH);
			exit(0);
		}

		if (!strcmp(opt, "-h") || !strcmp(opt, "--help")) {
			printf("%s", usage_string);
			exit(0);
		}

		if (!strcmp(opt, "-C")) {
			if (++i >= argc)
				die("Option -C requires an argument");
			if (chdir(argv[i]) == -1)
				die("Failed to change directory to %s: %s", argv[i], strerror(errno));
			continue;
		}

		if (request == REQ_VIEW_GREP || (request == REQ_VIEW_REFS && opt[0] == '-')) {
			argv_append(&filter_argv, opt);
			continue;
		}

		if (!strcmp(opt, "--stdin")) {
			if (request == REQ_VIEW_MAIN || request == REQ_VIEW_DIFF) {
				argv_append(&opt_cmdline_args, "--stdin");
				continue;
			}
		}

		argv_append(&filter_argv, opt);
	}

	if (request == REQ_VIEW_GREP) {
		grep_args = filter_argv;
		return request;
	}

	if (request == REQ_VIEW_REFS) {
		if (filter_argv)
			argv_append_array(&opt_cmdline_args, filter_argv);
		return request;
	}

	if (request == REQ_VIEW_BLAME) {
		/* tig blame [options] [rev] [--] path */
		blame_args_rest = filter_argv;
		return request;
	}

	{
		const char **saved = NULL;
		const char *empty[] = { NULL };

		if (opt_cmdline_args)
			argv_copy(&saved, opt_cmdline_args);
		filter_options(filter_argv ? filter_argv : empty, false);
		if (saved) {
			/* --stdin handled above goes first */
			const char **merged = NULL;

			argv_append_array(&merged, saved);
			argv_append_array(&merged, opt_cmdline_args);
			argv_free(opt_cmdline_args);
			free(opt_cmdline_args);
			opt_cmdline_args = merged;
		}
	}

	if (pager_mode) {
		if (request == REQ_VIEW_MAIN || request == REQ_VIEW_DIFF) {
			if (argv_contains(opt_cmdline_args, "--stdin"))
				return request;
			if (request == REQ_VIEW_MAIN && argv_contains(opt_cmdline_args, "--pretty=raw"))
				return request;
		}
		if (request == REQ_VIEW_MAIN || request == REQ_VIEW_LOG || request == REQ_VIEW_DIFF)
			return REQ_VIEW_PAGER;
	}

	return request;
}

const char **
get_grep_args(void)
{
	return grep_args;
}

const char **
get_blame_args(void)
{
	return blame_args_rest;
}

/*
 * Main loop
 */

static enum request
open_run_request(struct view *view, enum request request)
{
	struct run_request *req = get_run_request(request);

	if (!req) {
		report("Unknown run request");
		return REQ_NONE;
	}

	return exec_run_request(view, req);
}

static void
view_close(struct view *view, bool quit_allowed)
{
	int nviews = displayed_views();
	struct view *next = NULL;

	if (nviews == 1 && !quit_allowed)
		return;

	if (view->pipe)
		end_update(view, true);

	if (nviews == 2) {
		/* Close the current view and switch to the other one. */
		next = display[current_view ^ 1];
		if (view->parent && view->parent == next)
			view->parent = NULL;
		if (display[current_view] == view) {
			display[current_view] = NULL;
			if (current_view == 1 && display[0]) {
				/* fine */
			} else if (current_view == 0) {
				display[0] = display[1];
				display[1] = NULL;
			}
			current_view = 0;
		}
		maximize_view(display[0], true);
		if (display[0]->parent == view)
			display[0]->parent = NULL;
	} else {
		/* Return to the previous view. */
		if (view->prev && view->prev != view) {
			struct view *prev = view->prev;

			view->prev = NULL;
			open_view(view, prev, OPEN_DEFAULT);
		} else {
			quit(0);
		}
	}
}

enum request
view_request(struct view *view, enum request request)
{
	if (!view || !view->lines)
		return request;

	if (request == REQ_ENTER && !opt_focus_child && view_has_flags(view, VIEW_SEND_CHILD_ENTER)) {
		struct view *child = display[1];

		if (view_is_displayed(child) && view != child) {
			struct view_column_data column_data = {0};

			if (view->ops->get_column_data && view->ops->get_column_data(view, &view->line[view->pos.lineno], &column_data)) {
				/* nothing */
			}
			view = child;
			request = view->ops->request(view, request, &view->line[view->pos.lineno]);
			return request;
		}
	}

	return view->ops->request(view, request, &view->line[view->pos.lineno]);
}

static bool
view_driver(struct view *view, enum request request)
{
	int i;

	if (request == REQ_NONE)
		return true;

	if (request >= REQ_RUN_REQUESTS) {
		request = open_run_request(view, request);

		/* Confirm that we are not in the pager mode */
		if (request == REQ_REFRESH && view && view_can_refresh(view)) {
			refresh_view(view);
			return true;
		}
		if (request == REQ_NONE)
			return true;
	}

	if (view) {
		request = view_request(view, request);
		if (request == REQ_NONE)
			return true;
	}

	switch (request) {
	case REQ_MOVE_UP:
	case REQ_MOVE_DOWN:
	case REQ_MOVE_PAGE_UP:
	case REQ_MOVE_PAGE_DOWN:
	case REQ_MOVE_HALF_PAGE_UP:
	case REQ_MOVE_HALF_PAGE_DOWN:
	case REQ_MOVE_FIRST_LINE:
	case REQ_MOVE_LAST_LINE:
	case REQ_MOVE_WHEEL_DOWN:
	case REQ_MOVE_WHEEL_UP:
		move_view(view, request);
		break;

	case REQ_SCROLL_FIRST_COL:
	case REQ_SCROLL_LEFT:
	case REQ_SCROLL_RIGHT:
	case REQ_SCROLL_LINE_DOWN:
	case REQ_SCROLL_LINE_UP:
	case REQ_SCROLL_PAGE_DOWN:
	case REQ_SCROLL_PAGE_UP:
	case REQ_SCROLL_HALF_PAGE_DOWN:
	case REQ_SCROLL_HALF_PAGE_UP:
	case REQ_SCROLL_WHEEL_DOWN:
	case REQ_SCROLL_WHEEL_UP:
		scroll_view(view, request);
		break;

	case REQ_VIEW_MAIN:
	case REQ_VIEW_DIFF:
	case REQ_VIEW_LOG:
	case REQ_VIEW_REFLOG:
	case REQ_VIEW_TREE:
	case REQ_VIEW_BLOB:
	case REQ_VIEW_BLAME:
	case REQ_VIEW_REFS:
	case REQ_VIEW_STATUS:
	case REQ_VIEW_STAGE:
	case REQ_VIEW_STASH:
	case REQ_VIEW_GREP:
	case REQ_VIEW_PAGER:
	case REQ_VIEW_HELP:
		open_view(view, view_from_request(request), OPEN_DEFAULT);
		break;

	case REQ_NEXT:
	case REQ_PREVIOUS:
		if (view->parent) {
			int line;

			view = view->parent;
			line = view->pos.lineno;
			move_view(view, request);
			if (view_is_displayed(view))
				update_view_title(view);
			if (line != view->pos.lineno)
				view_request(view, REQ_ENTER);
		} else {
			move_view(view, request);
		}
		break;

	case REQ_VIEW_NEXT:
	{
		int nviews = displayed_views();
		int next_view = current_view + 1;

		if (next_view >= nviews)
			next_view = 0;

		if (next_view == current_view) {
			report("Only one view is displayed");
			break;
		}

		current_view = next_view;
		/* Blur out the title of the previous view. */
		update_view_title(view);
		/* Redraw the cursor line of both views to update the cursor color. */
		{
			struct view *v;
			int k;

			foreach_displayed_view (v, k) {
				if (v->lines) {
					draw_view_line(v, v->pos.lineno - v->pos.offset);
					wnoutrefresh(v->win);
				}
			}
		}
		report_clear();
		break;
	}
	case REQ_REFRESH:
		report("Refreshing is not supported by the %s view", view->name);
		break;

	case REQ_PARENT:
		report("Moving to parent is not supported by the %s view", view->name);
		break;

	case REQ_BACK:
		report("Going back is not supported for by %s view", view->name);
		break;

	case REQ_MAXIMIZE:
		if (displayed_views() == 2)
			maximize_view(view, true);
		break;

	case REQ_OPTIONS:
		prompt_menu_options();
		break;

	case REQ_SEARCH:
	case REQ_SEARCH_BACK:
	{
		const char *prompt = request == REQ_SEARCH ? "/" : "?";
		bool from_prompt = *argv_env.search != 0;

		if (!from_prompt) {
			char *search = read_prompt(prompt);

			if (search)
				string_ncopy(argv_env.search, search, strlen(search));
			else {
				report_clear();
				break;
			}
		}
		if (*argv_env.search) {
			search_view(view, request);
			argv_env.search[0] = 0;
		}
		break;
	}

	case REQ_FIND_NEXT:
	case REQ_FIND_PREV:
		find_next(view, request);
		break;

	case REQ_STOP_LOADING:
		foreach_view (view, i) {
			if (view->pipe)
				report("Stopped loading the %s view", view->name),
				end_update(view, true);
		}
		break;

	case REQ_SHOW_VERSION:
		report("tig-%s", TIG_VERSION);
		return true;

	case REQ_SCREEN_REDRAW:
		redraw_display(true);
		break;

	case REQ_EDIT:
		report("Nothing to edit");
		break;

	case REQ_ENTER:
		report("Nothing to enter");
		break;

	case REQ_PROMPT:
	{
		char *cmd = read_prompt_command();

		if (cmd && *cmd) {
			char cmdbuf[SIZEOF_STR];
			const char *argv[SIZEOF_ARGV];
			int argc = 0;

			string_ncopy(cmdbuf, cmd, strlen(cmd));
			if (!argv_from_string(argv, &argc, cmdbuf)) {
				report("Too many arguments");
			} else {
				enum request req = run_prompt_command(view, argv);

				if (req != REQ_NONE)
					return view_driver(display[current_view], req);
			}
		} else if (cmd) {
			report_clear();
		}
		break;
	}

	case REQ_VIEW_CLOSE:
		view_close(view, true);
		break;

	case REQ_VIEW_CLOSE_NO_QUIT:
		view_close(view, false);
		break;

	case REQ_QUIT:
		return false;

	case REQ_NONE:
		break;

	default:
		report("Unknown key, press %s for help", get_view_key(view, REQ_VIEW_HELP));
		return true;
	}

	return true;
}

static enum request
read_key_request(struct view *view, struct key *key, int *keys_read)
{
	struct key keys[16];
	int nkeys = 0;
	enum request request;
	int matches;

	keys[nkeys++] = *key;
	while (true) {
		request = get_keybinding(view->keymap, keys, nkeys, &matches);
		if (request != REQ_UNKNOWN && request != REQ_NONE && matches == 0)
			break;
		if (matches == 0)
			break;
		/* Longer sequences possible: read another key */
		if (nkeys >= ARRAY_SIZE(keys))
			break;
		if (get_input(0, &keys[nkeys]) == ERR)
			break;
		nkeys++;
		request = get_keybinding(view->keymap, keys, nkeys, &matches);
		if (request != REQ_UNKNOWN && request != REQ_NONE)
			break;
		if (matches == 0)
			break;
	}
	*keys_read = nkeys;
	return request;
}

int
main(int argc, const char *argv[])
{
	const char *codeset = ENCODING_UTF8;
	bool pager_mode = !isatty(STDIN_FILENO);
	enum request request;
	struct view *view;
	int i;

	setlocale(LC_ALL, "");
	(void) codeset;

	signal(SIGINT, quit);
	signal(SIGQUIT, quit);
	signal(SIGPIPE, SIG_IGN);

	init_option_defaults();
	init_view_env();

	request = parse_options(argc, argv, pager_mode);
	if (request == REQ_NONE)
		return 0;

	opt_pager_mode = pager_mode;
	first_request = request;

	if (load_repo_info() == ERR && !pager_mode && request != REQ_VIEW_PAGER)
		die("Not a git repository");

	if (load_options() == ERR)
		die("Failed to load user config.");

	if (load_git_config() == ERR && *repo.git_dir)
		die("Failed to load repo config.");

	/* Require a git repository unless when running in pager mode. */
	if (!repo.git_dir[0] && request != REQ_VIEW_PAGER)
		die("Not a git repository");

	if (*opt_encoding && strcasecmp(opt_encoding, "UTF-8"))
		;

	if (*repo.git_dir && load_refs(false) == ERR)
		die("Failed to load refs.");

	init_display();

	{
		const char *script_path = getenv("TIG_SCRIPT");

		if (script_path) {
			if (!*script_path) {
				/* read from stdin: treat as tty input */
			} else if (!open_script(script_path)) {
				die("Failed to open script: %s", script_path);
			}
		}
	}

	view = view_from_request(request);
	first_view = view;
	if (pager_mode && request == REQ_VIEW_PAGER) {
		open_view(NULL, view, OPEN_PAGER_MODE);
	} else if (pager_mode && (request == REQ_VIEW_MAIN || request == REQ_VIEW_DIFF)) {
		open_view(NULL, view, OPEN_FORWARD_STDIN);
	} else {
		open_view(NULL, view, OPEN_DEFAULT);
	}

	if (opt_lineno_arg > 0 && display[0]) {
		struct view *v = display[0];

		if (v->lines) {
			select_view_line(v, opt_lineno_arg - 1);
		} else {
			argv_env.goto_lineno = opt_lineno_arg;
		}
	}

	while (true) {
		struct key key;
		int keys_read;

		if (!view_driver(display[current_view], request)) {
			if (false)
				break;
			break;
		}

		view = display[current_view];
		if (!view) {
			break;
		}

		/* Refresh, accept single char input. */
		if (get_input(0, &key) == ERR)
			continue;

		request = read_key_request(view, &key, &keys_read);
		if (request == REQ_UNKNOWN || request == REQ_NONE) {
			if (request == REQ_UNKNOWN) {
				char *keyname = str_dup(get_key_name(&key, 1, false));

				(void) keyname;
				report("Unknown key, press %s for help", get_view_key(view, REQ_VIEW_HELP));
				free(keyname);
			}
			request = REQ_NONE;
		}
	}

	quit(0);

	(void) i;
	return 0;
}
