#include "tig.h"

static struct ref **refs = NULL;
static size_t refs_size = 0;
static struct ref *refs_head = NULL;

/* Id to ref list mapping. */
struct ref_list {
	char id[SIZEOF_REV];
	struct ref *refs;	/* sorted linked list */
};

static struct ref_list **ref_lists = NULL;
static size_t ref_lists_size = 0;

struct ref *
get_ref_head(void)
{
	return refs_head;
}

static int
ref_type_order(enum reference_type type)
{
	return type;
}

int
ref_compare(const struct ref *r1, const struct ref *r2)
{
	if (r1->type != r2->type)
		return ref_type_order(r1->type) - ref_type_order(r2->type);
	return strcmp_numeric(r1->name, r2->name);
}

static struct ref_list *
find_ref_list(const char *id)
{
	size_t i;

	for (i = 0; i < ref_lists_size; i++)
		if (!strcmp(ref_lists[i]->id, id))
			return ref_lists[i];
	return NULL;
}

struct ref *
get_ref_list(const char *id)
{
	struct ref_list *list = find_ref_list(id);

	return list ? list->refs : NULL;
}

struct ref *
get_canonical_ref(const char *id)
{
	struct ref *ref = get_ref_list(id);

	return ref;
}

bool
ref_list_contains_tag(const char *id)
{
	struct ref *ref;

	for (ref = get_ref_list(id); ref; ref = ref->next)
