		type = REFERENCE_REPLACE;
		name += STRING_SIZE("refs/replace/");
		namelen -= STRING_SIZE("refs/replace/");

	} else if (!prefixcmp(name, "refs/stash")) {
		type = REFERENCE_STASH;
		name += STRING_SIZE("refs/");
		namelen -= STRING_SIZE("refs/");

	} else if (!prefixcmp(name, "refs/notes/")) {
		type = REFERENCE_NOTE;
		name += STRING_SIZE("refs/");
		namelen -= STRING_SIZE("refs/");

	} else if (!prefixcmp(name, "refs/prefetch/")) {
		type = REFERENCE_PREFETCH;
		name += STRING_SIZE("refs/");
		namelen -= STRING_SIZE("refs/");

	} else {
		type = REFERENCE_OTHER;
	}

	/* If we are reloading or it's an annotated tag, replace the
	 * previous SHA1 with the resolved commit id; relies on the fact
	 * git-ls-remote lists the commit id of an annotated tag right
	 * before the commit id it points to. */
	for (i = 0; i < refs_size; i++) {
		if (refs[i]->type == type || (is_deref && refs[i]->type == REFERENCE_LOCAL_TAG))
			if (!strcmp(refs[i]->name, name)) {
				ref = refs[i];
				break;
			}
	}

	if (!ref) {
		struct ref **tmp = realloc(refs, (refs_size + 1) * sizeof(*refs));

		if (!tmp)
			return ERR;
		refs = tmp;
		ref = calloc(1, sizeof(*ref) + namelen);
		if (!ref)
			return ERR;
		refs[refs_size++] = ref;
		strncpy(ref->name, name, namelen);
		ref->name[namelen] = 0;
