		struct ref_list *list = find_ref_list(ref->id);

		if (list) {
			struct ref **pos;

			for (pos = &list->refs; *pos; pos = &(*pos)->next)
				if (*pos == ref) {
					*pos = ref->next;
					break;
				}
		}
	}

	ref->valid = true;
	ref->type = type;
	ref->next = NULL;
	string_copy_rev(ref->id, id);
	ref_list_add(ref);

	return OK;
}

