#include "tig.h"

struct repo_info repo;
char *opt_git_dir = NULL;

static bool
read_repo_info(char *name, size_t namelen, char *value, size_t valuelen, void *data)
{
	int *state = data;

	switch (*state) {
	case 0:
		string_ncopy(repo.git_dir, name, namelen);
		break;
	case 1:
		repo.is_inside_work_tree = !strcmp(name, "true");
		break;
	case 2:
		string_ncopy(repo.cdup, name, namelen);
		break;
	case 3:
		string_ncopy(repo.prefix, name, namelen);
		break;
	case 4:
		if (iscommit(name) && strlen(name) == 40) {
			string_ncopy(repo.head_id, name, namelen);
		} else if (!prefixcmp(name, "refs/heads/")) {
			string_ncopy(repo.head, name + STRING_SIZE("refs/heads/"), namelen - STRING_SIZE("refs/heads/"));
		}
		break;
	default:
		if (!prefixcmp(name, "refs/heads/")) {
			string_ncopy(repo.head, name + STRING_SIZE("refs/heads/"), namelen - STRING_SIZE("refs/heads/"));
		} else if (iscommit(name) && strlen(name) == 40) {
			string_ncopy(repo.head_id, name, namelen);
		}
		break;
	}
	(*state)++;
	return true;
}

int
load_repo_info(void)
{
	const char *rev_parse_argv[] = {
		"git", "rev-parse", "--git-dir", "--is-inside-work-tree",
		"--show-cdup", "--show-prefix", "HEAD", "--symbolic-full-name", "HEAD", NULL
	};
	struct io io;
	int state = 0;
	int ret;

	memset(&repo, 0, sizeof(repo));

	/* Use a custom loader to handle empty lines (show-prefix may be empty). */
	if (!io_run(&io, IO_RD, NULL, NULL, rev_parse_argv))
		return ERR;

	{
		char *line;

		while ((line = io_get(&io, '\n', true))) {
			line = chomp_string(line);
			read_repo_info(line, strlen(line), "", 0, &state);
		}
		io_done(&io);
	}
	ret = *repo.git_dir ? OK : ERR;

	if (*repo.git_dir && !repo.is_inside_work_tree) {
		/* Bare repo: nothing */
	}

	return ret;
}

int
load_repo_head(void)
{
	const char *rev_parse_argv[] = { "git", "rev-parse", "HEAD", "--symbolic-full-name", "HEAD", NULL };
	struct io io;
	char *line;

	repo.head[0] = 0;
	repo.head_id[0] = 0;
	if (!io_run(&io, IO_RD, NULL, NULL, rev_parse_argv))
		return ERR;
	while ((line = io_get(&io, '\n', true))) {
		line = chomp_string(line);
		if (!prefixcmp(line, "refs/heads/"))
			string_ncopy(repo.head, line + STRING_SIZE("refs/heads/"), strlen(line) - STRING_SIZE("refs/heads/"));
		else if (iscommit(line))
			string_ncopy(repo.head_id, line, strlen(line));
	}
	io_done(&io);
	return OK;
}

