#include "tig.h"

/*
 * Pager backend
 */

bool
pager_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	column_data->text = box_text(line);
	column_data->box = line->data;
	return true;
}

static bool
pager_draw(struct view *view, struct line *line, unsigned int lineno)
{
	return view_columns_draw(view, line, lineno);
}

bool
pager_common_grep(struct view *view, struct line *line)
{
	const char *text[] = { box_text(line), NULL };

	return grep_text(view, text);
}

static const char *
format_refs_line(const char *id, bool describe)
{
	static char buf[SIZEOF_STR];
	size_t bufpos = 0;
	struct ref *ref = get_ref_list(id);
	const char *sep = "";
	bool is_tag = false;

	if (!ref && !describe)
		return NULL;

	string_format_from(buf, &bufpos, "Refs: ");
	for (; ref; ref = ref->next) {
		const struct ref_format *fmt = get_ref_format(ref);

		if (fmt->hidden)
			continue;
		if (ref_is_tag(ref))
			is_tag = true;
		if (!string_format_from(buf, &bufpos, "%s%s%s%s", sep, fmt->start, ref->name, fmt->end))
			return NULL;
		sep = ", ";
	}

	if (describe && !is_tag) {
		const char *describe_argv[] = { "git", "describe", "--tags", id, NULL };
		char describe_buf[SIZEOF_STR] = "";

		if (io_run_buf(describe_argv, describe_buf, sizeof(describe_buf), repo.cdup, false) && *describe_buf) {
			if (!string_format_from(buf, &bufpos, "%s%s", sep, describe_buf))
				return NULL;
			sep = ", ";
		}
	}

	if (!*sep)
		return NULL;
	return buf;
}

void
add_pager_refs(struct view *view, const char *commit_id)
{
	char id[SIZEOF_REV];
	const char *refs_line;
	bool describe = view_has_flags(view, VIEW_ADD_DESCRIBE_REF);

	string_copy_rev(id, commit_id);
	refs_line = format_refs_line(id, describe);
	if (refs_line)
		add_line_text(view, refs_line, LINE_PP_REFS);
}

bool
pager_common_read(struct view *view, const char *data, enum line_type type, struct line **line_ptr)
{
	struct line *line;

	if (!data)
		return true;

	line = add_line_text(view, data, type);
	if (!line)
		return false;

	if (line_ptr)
		*line_ptr = line;

	if (line->type == LINE_COMMIT && view_has_flags(view, VIEW_ADD_PAGER_REFS))
		add_pager_refs(view, data + STRING_SIZE("commit "));

	return true;
}

bool
pager_read(struct view *view, struct buffer *buf, bool force_stop)
{
	if (!buf)
		return true;

	return pager_common_read(view, buf->data, get_line_type(buf->data), NULL);
}

static void
pager_select_commit(struct view *view, struct line *line)
{
	if (line->type == LINE_COMMIT) {
		const char *text = box_text(line);

		if (!prefixcmp(text, "commit "))
			text += STRING_SIZE("commit ");
		string_copy_rev(view->env->commit, text);
		if (!view_has_flags(view, VIEW_NO_REF))
			string_copy_rev(view->ref, view->env->commit);
	}
}

void
pager_select(struct view *view, struct line *line)
{
	pager_select_commit(view, line);
}

enum request
pager_request(struct view *view, enum request request, struct line *line)
{
	int split = 0;

	if (request != REQ_ENTER)
		return request;

	if (line->type == LINE_COMMIT && view_has_flags(view, VIEW_OPEN_DIFF)) {
		open_view(view, view_from_request(REQ_VIEW_DIFF), OPEN_SPLIT);
		split = 1;
	}

	/* Always scroll the view even if it was split. That way
	 * you can use Enter to scroll through the log view and
	 * split open each commit diff. */
	scroll_view(view, REQ_SCROLL_LINE_DOWN);

	/* FIXME: A minor workaround. Scrolling the view will call report_clear()
	 * but if we are scrolling a non-current view this won't properly
	 * update the view title. */
	if (split)
		update_view_title(view);

	return REQ_NONE;
}

static bool
pager_open(struct view *view, enum open_flags flags)
{
	if (!open_from_stdin(flags) && !view->lines && !(flags & OPEN_PREPARED)) {
		report("No pager content, press %s to run command from prompt",
			get_view_key(view, REQ_PROMPT));
		return false;
	}

	return begin_update(view, NULL, NULL, flags);
}

