	case IGNORE_SPACE_ALL: return "--ignore-all-space";
	case IGNORE_SPACE_SOME: return "--ignore-space-change";
	case IGNORE_SPACE_AT_EOL: return "--ignore-space-at-eol";
	default: return "";
	}
}

static const char *
diff_stat_arg(struct view *view)
{
	static char buf[32];
	int width = view->width ? view->width : COLS;

	string_format(buf, "--stat=%d", width);
	return buf;
}

void
diff_save_line(struct view *view, struct diff_state *state, enum open_flags flags)
{
	struct diff_private *priv = (struct diff_private *) state;

	if (flags & OPEN_REFRESH) {
		struct line *line = view->lines ? &view->line[view->pos.lineno] : NULL;
		const char *file = line ? diff_get_pathname(view, line, false) : NULL;

		if (file) {
			string_ncopy(priv->filename, file, strlen(file));
			priv->lineno = diff_get_lineno(view, line, false);
			priv->prev_pos = view->pos;
		} else {
			priv->filename[0] = 0;
		}
	}
}

void
diff_restore_line(struct view *view, struct diff_state *state)
{
	struct diff_private *priv = (struct diff_private *) state;
	struct line *line = &view->line[view->lines - 1];

	if (!*priv->filename)
		return;

	while ((line = find_prev_line_by_type(view, line, LINE_DIFF_HEADER))) {
		const char *file = diff_get_pathname(view, line, false);

		if (file && !strcmp(file, priv->filename))
			break;
		line--;
	}

	if (!line)
		return;

	while ((line = find_next_line_by_type(view, line, LINE_DIFF_CHUNK))) {
		unsigned int lineno = diff_get_lineno(view, line, false);

		for (line++; view_has_line(view, line) && line->type != LINE_DIFF_CHUNK; line++) {
			if (lineno == priv->lineno) {
				unsigned long lineno_pos = line - view->line;

				goto_view_line(view, view->pos.offset, lineno_pos);
				view->pos.offset = priv->prev_pos.offset;
				if (view->pos.offset > view->pos.lineno)
					view->pos.offset = view->pos.lineno > view->height / 2 ? view->pos.lineno - view->height / 2 : 0;
				if (view->pos.lineno >= view->pos.offset + view->height)
					view->pos.offset = view->pos.lineno - view->height / 2;
				priv->filename[0] = 0;
				return;
			}
			if (line->type != LINE_DIFF_DEL &&
			    line->type != LINE_DIFF_DEL2)
				lineno++;
		}
	}
	priv->filename[0] = 0;
}

static bool
diff_open(struct view *view, enum open_flags flags)
{
	const char *diff_argv[] = {
		"git", "show", "--encoding=UTF-8", "--pretty=fuller", "--root",
		"--patch-with-stat", diff_stat_arg(view), use_mailmap_arg(), show_notes_arg(),
		"%(diffargs)", "%(cmdlineargs)", "--no-color", word_diff_arg(),
		"%(commit)", "--", "%(fileargs)", NULL
	};
	struct diff_private *priv = view->private;

	diff_save_line(view, &priv->state, flags);

	/* Keep the saved filename across the state reset. */
	{
		char filename[SIZEOF_STR];
		unsigned int lineno = priv->lineno;
		struct position prev_pos = priv->prev_pos;

		string_copy(filename, priv->filename);
		memset(&priv->state, 0, sizeof(priv->state));
		string_copy(priv->filename, filename);
		priv->lineno = lineno;
		priv->prev_pos = prev_pos;
	}

	return begin_update(view, NULL, diff_argv, flags);
}

struct line *
diff_common_add_diff_stat(struct view *view, const char *text, size_t offset)
{
	const char *start = text + offset;
	const char *data = start;
	size_t len = strlen(data);
	char *pipe = strchr(data, '|');
	bool has_histogram = len > 0 && (data[len - 1] == '-' || data[len - 1] == '+');
	bool has_bin_diff = pipe && strstr(pipe, "Bin") && strstr(pipe, "->");
	bool has_rename = len > 0 && data[len - 1] == '0' && (strstr(data, "=>") || !strncmp(data, " ...", 4));
	bool has_no_change = pipe && strstr(pipe, " 0");

	if (pipe && (has_histogram || has_bin_diff || has_rename || has_no_change)) {
		struct line *line = add_line_text_at(view, view->lines, text, LINE_DIFF_STAT, 4);
		struct box *box;
		const char *p;
		size_t filelen, numlen, pluslen = 0, minuslen = 0;

		if (!line)
			return NULL;
		box = line->data;
		/* file name part including the leading offset text up to the pipe */
		filelen = pipe - text;
		p = pipe;
		/* numbers part: up to the first + or - */
		while (*p && *p != '+' && *p != '-')
			p++;
		numlen = p - pipe;
		while (p[pluslen] == '+')
			pluslen++;
		p += pluslen;
		while (p[minuslen] == '-')
			minuslen++;

		box->cells = 0;
		box_add_cell(box, text, LINE_DIFF_STAT, filelen);
		box_add_cell(box, pipe, LINE_DEFAULT, numlen);
		if (pluslen)
			box_add_cell(box, pipe + numlen, LINE_DIFF_ADD, pluslen);
		if (minuslen)
			box_add_cell(box, pipe + numlen + pluslen, LINE_DIFF_DEL, minuslen);
		{
			size_t used = filelen + numlen + pluslen + minuslen;
			size_t total = strlen(text);

			if (used < total)
				box_add_cell(box, text + used, LINE_DEFAULT, total - used);
		}
		return line;
	}

	return NULL;
}

static bool
diff_common_add_diff_stat_section(struct view *view, const char *data)
{
	return diff_common_add_diff_stat(view, data, 0) != NULL;
}

bool
diff_common_read(struct view *view, const char *data, struct diff_state *state)
{
	enum line_type type = get_line_type(data);

	if (!view->lines && type != LINE_COMMIT)
		state->reading_diff_stat = true;

	if (state->combined_diff && !state->after_diff && data[0] == ' ' && data[1] != ' ')
		state->reading_diff_stat = true;

	if (state->reading_diff_stat) {
		if (diff_common_add_diff_stat_section(view, data))
			return true;
		state->reading_diff_stat = false;

	} else if (!strcmp(data, "---")) {
		state->reading_diff_stat = true;
	}

	if (!state->after_commit_title && !prefixcmp(data, "    ")) {
		struct line *line = add_line_text(view, data, LINE_DEFAULT);

		if (!line)
			return false;
		state->after_commit_title = true;
		return true;
	}

	if (type == LINE_DIFF_HEADER) {
		state->after_diff = true;
		state->reading_diff_chunk = false;
		if (!state->combined_diff && !prefixcmp(data, "diff --cc"))
			state->combined_diff = true;
		if (!state->combined_diff && !prefixcmp(data, "diff --combined"))
			state->combined_diff = true;

	} else if (type == LINE_DIFF_CHUNK) {
		const int len = chunk_header_marker_length(data);
		const char *context = strstr(data + len, "@@");
		struct line *line =
			context ? add_line_text_at(view, view->lines, data, LINE_DIFF_CHUNK, 2) : NULL;
		struct box *box;

		if (!line)
			return false;

		box = line->data;
		box->cells = 0;
		box_add_cell(box, data, LINE_DIFF_CHUNK, context - data + len);
		box_add_cell(box, context + len, LINE_DEFAULT, strlen(context + len));
		state->reading_diff_chunk = true;
		return true;

	} else if (type == LINE_COMMIT) {
		state->reading_diff_chunk = false;
		state->after_diff = false;
		state->after_commit_title = false;
		state->reading_diff_stat = false;

	} else if (state->reading_diff_chunk && !state->combined_diff &&
		   (type == LINE_DIFF_ADD2 || type == LINE_DIFF_DEL2)) {
		type = LINE_DEFAULT;

	} else if (state->reading_diff_chunk && type != LINE_DIFF_ADD && type != LINE_DIFF_DEL &&
		   type != LINE_DIFF_ADD2 && type != LINE_DIFF_DEL2 && type != LINE_DIFF_NO_NEWLINE &&
		   data[0] == ' ') {
		type = LINE_DEFAULT;
	}

	return pager_common_read(view, data, type, NULL);
}

int
chunk_header_marker_length(const char *data)
{
	int len = 0;

	while (data[len] == '@')
		len++;
	return len;
}

static bool
diff_read_describe(struct view *view, struct buffer *buffer, struct diff_state *state)
{
	return true;
}

static bool
diff_read(struct view *view, struct buffer *buf, bool force_stop)
{
	struct diff_private *priv = view->private;
	struct diff_state *state = &priv->state;

	if (!buf) {
		/* Fall back to retry if no diff will be shown. */
		if (view->lines == 0 && opt_file_args) {
			int pos = argv_size(view->argv)
				- argv_size(opt_file_args) - 1;

			if (pos > 0 && !strcmp(view->argv[pos], "--")) {
				for (; view->argv[pos]; pos++) {
					free((void *) view->argv[pos]);
					view->argv[pos] = NULL;
				}

				if (view->pipe)
					io_done(view->pipe);
				if (io_run(&view->io, IO_RD, view->dir, (char **) NULL, view->argv))
					return false;
			}
		}
		diff_restore_line(view, state);
		return true;
	}

	return diff_common_read(view, buf->data, state);
}

static bool
diff_blame_line(const char *ref, const char *file, unsigned long lineno,
		struct blame_header *header, struct blame_commit *commit)
{
	return false;
}

unsigned int
diff_get_lineno(struct view *view, struct line *line, bool old)
{
	const struct line *header, *chunk;
	unsigned int lineno;
	struct chunk_header chunk_header;

	/* Verify that we are after a diff header and one of its chunks */
	header = find_prev_line_by_type(view, line, LINE_DIFF_HEADER);
	chunk = find_prev_line_by_type(view, line, LINE_DIFF_CHUNK);
	if (!header || !chunk || chunk < header)
		return 0;

	/*
	 * In a chunk header, the number after the '+' sign is the number of its
	 * following line, in the new version of the file. We increment this
	 * number for each non-deletion line, until the given line position.
	 */
	if (!parse_chunk_header(&chunk_header, box_text(chunk)))
		return 0;

	lineno = old ? chunk_header.old.position : chunk_header.new.position;

	for (chunk++; chunk < line; chunk++)
		if (old ? chunk->type != LINE_DIFF_ADD && chunk->type != LINE_DIFF_ADD2
		        : chunk->type != LINE_DIFF_DEL && chunk->type != LINE_DIFF_DEL2)
			lineno++;

	return lineno;
}

bool
parse_chunk_header(struct chunk_header *header, const char *line)
{
	const char *p;
	int at = 0;

	memset(header, 0, sizeof(*header));
	for (p = line; *p == '@'; p++)
		at++;
	if (at < 2)
		return false;

	/* @@ -old,count +new,count @@ (combined: @@@ -a,b -c,d +e,f @@@) */
	while (*p) {
		while (*p == ' ')
			p++;
		if (*p == '-') {
			unsigned long pos, len = 1;
			const char *end;

			p++;
			if (!parse_ulong(&pos, p, &end))
				return false;
			p = end;
			if (*p == ',') {
				p++;
				if (!parse_ulong(&len, p, &end))
					return false;
				p = end;
			}
			header->old.position = pos;
			header->old.lines = len;
		} else if (*p == '+') {
			unsigned long pos, len = 1;
			const char *end;

			p++;
			if (!parse_ulong(&pos, p, &end))
				return false;
			p = end;
			if (*p == ',') {
				p++;
				if (!parse_ulong(&len, p, &end))
					return false;
				p = end;
			}
			header->new.position = pos;
			header->new.lines = len;
		} else {
			break;
		}
	}
	return true;
}

static enum request
diff_trace_origin(struct view *view, struct line *line)
{
	report("Tracing the origin of a line is not supported");
	return REQ_NONE;
}

const char *
diff_get_pathname(struct view *view, struct line *line, bool old)
{
	const struct line *header;
	const char *dst = NULL;
	const char *prefixes[] = { " b/", " a/", "a/", "b/", "/dev/null" };
	int i;

	header = find_prev_line_by_type(view, line, LINE_DIFF_HEADER);
	if (!header)
		return NULL;

	/* Find the "+++ b/path" or "--- a/path" line. */
	{
		const struct line *l;

		for (l = header + 1; view_has_line(view, l) && l->type != LINE_DIFF_CHUNK; l++) {
			if (!old && l->type == LINE_DIFF_ADD_FILE) {
				dst = box_text(l) + STRING_SIZE("+++ ");
				break;
			}
			if (old && l->type == LINE_DIFF_DEL_FILE) {
				dst = box_text(l) + STRING_SIZE("--- ");
				break;
			}
		}
	}

	if (!dst) {
		/* Fall back to the diff header: "diff --git a/x b/x" */
		const char *text = box_text(header);
		const char *bpath;

		if (old) {
			if (!prefixcmp(text, "diff --git a/")) {
				static char buf[SIZEOF_STR];
				const char *start = text + STRING_SIZE("diff --git a/");
				const char *end = strstr(start, " b/");

				if (end) {
					string_ncopy(buf, start, end - start);
					return buf;
				}
			}
			return NULL;
		}
		bpath = strstr(text, " b/");
		if (bpath)
			return bpath + STRING_SIZE(" b/");
		return NULL;
	}

	for (i = 0; i < ARRAY_SIZE(prefixes); i++) {
		if (!prefixcmp(dst, prefixes[i])) {
			dst += strlen(prefixes[i]);
			break;
		}
	}
	if (!strcmp(dst, "/dev/null") || !*dst)
		return NULL;
	return dst;
}

bool
diff_common_edit(struct view *view, enum request request, struct line *line)
{
	const char *file = diff_get_pathname(view, line, false);
	char path[SIZEOF_STR];
	bool has_path = file && string_format(path, "%s%s", repo.cdup, file);

	if (has_path && access(path, R_OK)) {
		report("Failed to open file: %s", file);
		return true;
	}

	if (has_path) {
		open_editor(file, diff_get_lineno(view, line, false));
		return true;
	}

	report("No file to edit");
	return true;
}

enum request
diff_common_enter(struct view *view, enum request request, struct line *line)
{
	if (line->type == LINE_DIFF_STAT) {
		int file_number = 0;

		while (view_has_line(view, line) && line->type == LINE_DIFF_STAT) {
			file_number++;
			line--;
		}

		for (line = view->line; view_has_line(view, line); line++) {
			line = find_next_line_by_type(view, line, LINE_DIFF_HEADER);
			if (!line)
				break;

			if (diff_get_pathname(view, line, false)) {
				if (--file_number == 0)
					break;
			}
		}

		if (!line) {
			report("Failed to find file diff");
			return REQ_NONE;
		}

		select_view_line(view, line - view->line);
		report_clear();
		return REQ_NONE;

	} else {
		return pager_request(view, request, line);
	}
}

static enum request
diff_request(struct view *view, enum request request, struct line *line)
{
	switch (request) {
	case REQ_VIEW_BLAME:
		return diff_trace_origin(view, line);

	case REQ_EDIT:
		diff_common_edit(view, request, line);
		return REQ_NONE;

	case REQ_ENTER:
		return diff_common_enter(view, request, line);

	case REQ_REFRESH:
		if (string_rev_is_null(view->vid))
			refresh_view(view);
		else
			reload_view(view);
		return REQ_NONE;

	default:
		return pager_request(view, request, line);
	}
}

bool
string_rev_is_null(const char *rev)
{
	return !strncmp(rev, NULL_ID, strlen(rev)) || !*rev;
}

void
diff_common_select(struct view *view, struct line *line, const char *changes_msg)
{
	if (line->type == LINE_DIFF_STAT) {
		string_format(view->ref, "Press '%s' to jump to file diff",
			      get_view_key(view, REQ_ENTER));
	} else {
		const char *file = diff_get_pathname(view, line, false);

		if (file) {
			if (changes_msg)
				string_format(view->ref, "%s to '%s'", changes_msg, file);
