		    draw_formatted(view, LINE_HELP_ACTION, "%-*s", action_width, help->data.toggle.name))
			return true;
		draw_formatted(view, LINE_DEFAULT, " %s", help->data.toggle.text);

	} else if (help->request > REQ_RUN_REQUESTS) {
		const struct run_request *req = help->data.req;
		const char *key = help->keys;
		char buf[SIZEOF_STR];
		const char *sep = format_run_request_flags(req);

		if (draw_formatted(view, LINE_DEFAULT, "%*s ", keys_width, key))
			return true;
		if (!argv_to_string(req->argv, buf, sizeof(buf), " "))
			return true;
		if (req->flags.internal)
			draw_formatted(view, LINE_HELP_ACTION, "%s", buf);
		else
			draw_formatted(view, LINE_HELP_ACTION, "%s%s", sep, buf);

	} else if (help->request == REQ_NONE && line->type == LINE_DEFAULT && help->data.text == NULL) {
		/* blank */

	} else if (help->request != REQ_NONE || help->data.req_info) {
		const struct request_info *req_info = help->data.req_info;
		const char *key = help->keys;

		if (draw_formatted(view, LINE_DEFAULT, "%*s ", keys_width, key))
			return true;
		if (draw_formatted(view, LINE_HELP_ACTION, "%-*s", action_width, enum_name(req_info->name)))
			return true;
		draw_formatted(view, LINE_DEFAULT, " %s", req_info->help);

	} else if (help->data.text) {
		draw_text(view, line->type, help->data.text);
	}

	return true;
}

struct help_widths {
	int keys;
	int action;
};

static struct help_widths widths;

int
help_keys_width(struct view *view)
{
	return widths.keys;
}

int
help_action_width(struct view *view)
{
	return widths.action;
}

static bool
help_grep(struct view *view, struct line *line)
{
	struct help *help = line->data;
	struct keymap *keymap = help->keymap;

	if (line->type == LINE_SECTION) {
		const char *text[] = { keymap->name, NULL };

		return grep_text(view, text);

	} else if (line->type == LINE_HELP_GROUP) {
		const char *text[] = { help->data.text, NULL };

		return grep_text(view, text);

	} else if (line->type == LINE_HELP_TOGGLE) {
		const char *text[] = { help->data.toggle.name, help->data.toggle.text, NULL };

		return grep_text(view, text);

	} else if (help->request > REQ_RUN_REQUESTS) {
		const struct run_request *req = help->data.req;
		const char *key = help->keys;
		char buf[SIZEOF_STR] = "";
		const char *text[] = { key, buf, NULL };

		if (!argv_to_string(req->argv, buf, sizeof(buf), " "))
			return false;
		return grep_text(view, text);

	} else if (help->data.req_info) {
		const struct request_info *req_info = help->data.req_info;
		const char *key = help->keys;
		const char *text[] = { key, enum_name(req_info->name), req_info->help, NULL };

		return grep_text(view, text);
	}

	return false;
}

static struct line *
help_add_line(struct view *view, enum line_type type, struct keymap *keymap)
{
	struct help *help;
	struct line *line = add_line_alloc(view, &help, type, 0, false);

	if (line)
		help->keymap = keymap;
	return line;
}

static bool
help_keys_visitor(void *data, const char *group, struct keymap *keymap,
		  enum request request, const char *key,
		  const struct request_info *req_info, const struct run_request *run_req)
{
	struct help_request_iterator *iterator = data;
	struct view *view = iterator->view;
	struct line *line;
	struct help *help;

	if (iterator->keymap != keymap) {
		if (iterator->keymap && !iterator->keymap->hidden) {
			/* nothing */
		}
		iterator->keymap = keymap;
		iterator->group = NULL;
		line = help_add_line(view, LINE_SECTION, keymap);
		if (!line)
			return false;
	}

	if (keymap->hidden)
		return true;

	if (group != iterator->group) {
		iterator->group = group;
		line = help_add_line(view, LINE_HELP_GROUP, keymap);
		if (!line)
			return false;
		help = line->data;
		help->data.text = group;
	}

	line = help_add_line(view, LINE_DEFAULT, keymap);
	if (!line)
		return false;
	help = line->data;
	help->request = request;
	string_ncopy(help->keys, key, strlen(key));
	if (req_info)
		help->data.req_info = req_info;
	else
		help->data.req = run_req;

	{
		int len = utf8_width_of(key, -1, -1);

		if (len + 2 > widths.keys)
			widths.keys = len + 2;
		if (req_info) {
			int alen = strlen(req_info->name);

			if (alen > widths.action)
				widths.action = alen;
		}
	}

	return true;
}

static bool
help_open_keymap_sections(struct view *view)
{
	struct help_request_iterator iterator = { view, NULL, false, NULL };

	return foreach_key(help_keys_visitor, &iterator, true);
}

static bool
help_open(struct view *view, enum open_flags flags)
{
	struct line *line;
	struct help *help;
	struct keymap *toggle_keymap;
	static struct keymap toggle_keymap_storage = { "toggle" };
	const struct toggle_entry *entries;
	int count, i;

	toggle_keymap = &toggle_keymap_storage;

	reset_view(view);

	if (!(line = help_add_line(view, LINE_HEADER, NULL)))
		return false;
	help = line->data;
	help->data.text = "Quick reference for tig keybindings:";

	if (!(line = help_add_line(view, LINE_SECTION, NULL)))
		return false;
	help = line->data;
	help->data.text = "Collapse all sections";

	if (!(line = help_add_line(view, LINE_DEFAULT, NULL)))
		return false;
	help = line->data;
	help->data.text = NULL;

	widths.keys = 0;
	widths.action = 0;

	if (!help_open_keymap_sections(view))
		return false;

	/* Toggle section */
	if (!(line = help_add_line(view, LINE_SECTION, toggle_keymap)))
		return false;

	count = get_toggle_entries(&entries);
	for (i = 0; i < count; i++) {
		int alen = strlen(entries[i].name);

		if (alen > widths.action)
			widths.action = alen;
	}

	if (!toggle_keymap->hidden) {
		if (!(line = help_add_line(view, LINE_HELP_GROUP, toggle_keymap)))
			return false;
		help = line->data;
		help->data.text = "Toggle keys (enter: o <key>):";

		for (i = 0; i < count; i++) {
			if (!(line = help_add_line(view, LINE_HELP_TOGGLE, toggle_keymap)))
				return false;
			help = line->data;
			help->data.toggle.hotkey = entries[i].hotkey;
			help->data.toggle.name = entries[i].name;
			help->data.toggle.text = entries[i].text;
		}
	}

	if (widths.keys < 1)
		widths.keys = 1;

	return true;
}

static bool
help_draw_line(struct view *view, struct line *line, unsigned int lineno)
{
	struct help *help = line->data;

	if (line->type == LINE_SECTION && !help->keymap) {
		/* Collapse all sections line */
		bool all_hidden = true;
		int i;

		for (i = 0; i < get_keymap_count(); i++) {
			struct keymap *keymap = get_keymap_by_index(i);

			if (keymap->data && !keymap->hidden)
				all_hidden = false;
		}
		draw_formatted(view, line->type, "[%c] %s", all_hidden ? '+' : '-', all_hidden ? "Expand all sections" : "Collapse all sections");
		return true;
	}
	if (line->type == LINE_HEADER) {
		draw_text(view, line->type, help->data.text);
		return true;
	}
	if (line->type == LINE_DEFAULT && !help->keymap) {
		return true;
	}
	return help_draw(view, line, lineno);
}

static enum request
help_request(struct view *view, enum request request, struct line *line)
{
	struct help *help = line->data;

	switch (request) {
	case REQ_ENTER:
		if (line->type == LINE_SECTION) {
			if (help->keymap) {
				help->keymap->hidden = !help->keymap->hidden;
			} else {
				bool all_hidden = true;
				int i;

				for (i = 0; i < get_keymap_count(); i++) {
					struct keymap *keymap = get_keymap_by_index(i);

					if (keymap->data && !keymap->hidden)
						all_hidden = false;
				}
				for (i = 0; i < get_keymap_count(); i++)
					get_keymap_by_index(i)->hidden = !all_hidden;
				{
					/* toggle keymap */
					struct line *l;
					size_t k;

					for (k = 0; k < view->lines; k++) {
						l = &view->line[k];
						if (l->type == LINE_SECTION && ((struct help *) l->data)->keymap &&
						    !strcmp(((struct help *) l->data)->keymap->name, "toggle"))
							((struct help *) l->data)->keymap->hidden = !all_hidden;
					}
				}
			}
			refresh_view(view);
		}
		return REQ_NONE;

	case REQ_REFRESH:
		refresh_view(view);
		return REQ_NONE;

	default:
		return request;
	}
}

