#include "tig.h"
#include "graph.h"

/*
 * Graph columns.
 */

struct graph_column {
	char id[SIZEOF_REV];
	size_t color;
};

struct graph_v2 {
	struct graph_column *columns;
	size_t columns_size;
	size_t columns_alloc;
	size_t next_color;

	/* State of the commit being added. */
	size_t position;		/* column of the commit */
	size_t parents;
	size_t parents_added;		/* parents handled */
	bool is_boundary;
	bool has_parents;
	struct graph_canvas *canvas;
	char id[SIZEOF_REV];

	/* Per column row state. */
	unsigned char *joins;		/* 1 if column id == commit id (before processing) */
	size_t joins_alloc;
};

static bool
graph_ensure_columns(struct graph_v2 *graph, size_t size)
{
	if (size > graph->columns_alloc) {
		size_t alloc = size + 8;
		struct graph_column *tmp = realloc(graph->columns, alloc * sizeof(*tmp));
		unsigned char *joins = realloc(graph->joins, alloc);

		if (!tmp || !joins)
			return false;
		graph->columns = tmp;
		graph->joins = joins;
		graph->columns_alloc = alloc;
	}
	return true;
}

static bool
graph_canvas_add(struct graph_canvas *canvas, struct graph_symbol symbol)
{
	struct graph_symbol *tmp = realloc(canvas->symbols, (canvas->size + 1) * sizeof(*tmp));

	if (!tmp)
		return false;
	canvas->symbols = tmp;
	canvas->symbols[canvas->size++] = symbol;
	return true;
}

static size_t
graph_find_column(struct graph_v2 *graph, const char *id, size_t from)
{
	size_t i;

	for (i = from; i < graph->columns_size; i++)
		if (!strcmp(graph->columns[i].id, id))
			return i;
	return (size_t) -1;
}

static void
graph_remove_column(struct graph_v2 *graph, size_t pos)
{
	if (pos + 1 < graph->columns_size)
		memmove(&graph->columns[pos], &graph->columns[pos + 1],
			(graph->columns_size - pos - 1) * sizeof(*graph->columns));
	graph->columns_size--;
}

struct graph *
init_graph(enum graph_display display)
{
	struct graph *graph = calloc(1, sizeof(*graph));

	if (graph)
		graph->display = display;
	return graph;
}

void
done_graph(struct graph *graph)
{
	struct graph_v2 *g = graph->private;

	if (g) {
		free(g->columns);
		free(g->joins);
		free(g);
	}
	free(graph);
}

void
done_graph_rendering(struct graph *graph)
{
}

static struct graph_v2 *
graph_private(struct graph *graph)
{
	if (!graph->private) {
		graph->private = calloc(1, sizeof(struct graph_v2));
	}
	return graph->private;
}

bool
graph_add_commit(struct graph *graph, struct graph_canvas *canvas,
		 const char *id, const char *parents, bool is_boundary)
{
	struct graph_v2 *g = graph_private(graph);
	size_t i, pos;
	size_t nparents = 0;
	const char *p;

	if (!g)
		return false;

	memset(canvas, 0, sizeof(*canvas));
	g->canvas = canvas;
	g->is_boundary = is_boundary;
	g->parents_added = 0;
	string_copy_rev(g->id, id);

	/* Count parents. */
	for (p = parents; p && *p; ) {
		while (*p == ' ')
			p++;
		if (!*p)
			break;
		nparents++;
		while (*p && *p != ' ')
			p++;
	}
	g->parents = nparents;
	g->has_parents = nparents > 0;

	/* Find the commit column, or append a new one. */
	pos = graph_find_column(g, id, 0);
	if (pos == (size_t) -1) {
		if (!graph_ensure_columns(g, g->columns_size + 1))
			return false;
		pos = g->columns_size++;
		string_copy_rev(g->columns[pos].id, id);
		g->columns[pos].color = g->next_color++;
	}
	g->position = pos;

	/* Mark joining columns. */
	for (i = 0; i < g->columns_size; i++)
		g->joins[i] = i != pos && !strcmp(g->columns[i].id, id);

	return true;
}

bool
graph_add_parent(struct graph *graph, const char *parent)
{
	struct graph_v2 *g = graph->private;

	if (!g)
		return false;

	if (g->parents_added == 0) {
		/* First parent takes over the commit column. */
		string_copy_rev(g->columns[g->position].id, parent);
		g->parents_added++;
		return true;
	}

	/* Reuse a joining column if any, else append a new column. */
	{
		size_t i;

		for (i = g->position + 1; i < g->columns_size; i++) {
			if (g->joins[i] == 1) {
				string_copy_rev(g->columns[i].id, parent);
				g->joins[i] = 2;	/* reused */
				g->parents_added++;
				return true;
			}
		}
	}

	if (!graph_ensure_columns(g, g->columns_size + 1))
		return false;
	g->joins[g->columns_size] = 3;	/* new column */
	string_copy_rev(g->columns[g->columns_size].id, parent);
	g->columns[g->columns_size].color = g->next_color++;
	g->columns_size++;
	g->parents_added++;
	return true;
}

bool
graph_render_parents(struct graph *graph, struct graph_canvas *canvas)
{
	struct graph_v2 *g = graph->private;
	size_t i;
	size_t span_end = g->position;

	if (!g)
		return false;

	/* Determine the end of the horizontal span. */
	for (i = g->position + 1; i < g->columns_size; i++)
		if (g->joins[i])
			span_end = i;

	for (i = 0; i < g->columns_size; i++) {
		struct graph_symbol symbol = {0};

		symbol.color = g->columns[i].color % 14;

		if (i == g->position) {
			symbol.commit = 1;
			symbol.merge = g->parents > 1;
			symbol.initial = !g->has_parents;
			symbol.boundary = g->is_boundary;
			symbol.color = g->columns[i].color % 14;
		} else if (i > g->position && i <= span_end) {
			symbol.in_span = 1;
			if (g->joins[i] == 1) {
				symbol.join = 1;
			} else if (g->joins[i] == 2) {
				symbol.reused = 1;
			} else if (g->joins[i] == 3) {
				symbol.new_column = 1;
			} else {
				symbol.pass = 1;
			}
			symbol.span_end = (i == span_end);
			symbol.color = g->columns[g->position].color % 14;
			if (symbol.pass)
				symbol.color = g->columns[i].color % 14;
		} else {
			symbol.vertical = 1;
		}

		if (!graph_canvas_add(canvas, symbol))
			return false;
	}

	/* Remove collapsed (joined, not reused) columns. */
	for (i = g->columns_size; i > g->position + 1; i--) {
		if (g->joins[i - 1] == 1) {
			graph_remove_column(g, i - 1);
			/* keep joins consistent */
			if (i - 1 < g->columns_size)
				memmove(&g->joins[i - 1], &g->joins[i], g->columns_size - (i - 1));
		}
	}

	/* Commit without parents: remove its column. */
	if (!g->has_parents)
		graph_remove_column(g, g->position);

	return true;
}

static void
graph_symbol_chars(const struct graph_symbol *symbol, enum graphic mode, const char **sym, const char **sep)
{
	/* sep is the connector drawn after the symbol (towards the next column) */
	static const char *ascii[] = { "*", "M", "I", "|", "-", ".", "'", "|", "+", "+", "+", " ", "o", "^" };
	static const char *utf8[] = { "\xE2\x88\x99", "\xE2\x97\x8F", "\xE2\x97\x8E", "\xE2\x94\x82", "\xE2\x94\x80",
				      "\xE2\x95\xAE", "\xE2\x95\xAF", "\xE2\x94\xA4", "\xE2\x94\xAC", "\xE2\x94\xB4", "\xE2\x94\xBC", " ", "o", "^" };
	const char **table = mode == GRAPHIC_UTF_8 ? utf8 : ascii;
	int idx;
	bool hline = false;

	if (symbol->commit) {
		if (symbol->boundary)
			idx = 12;
		else if (symbol->initial)
			idx = 2;
		else if (symbol->merge)
			idx = 1;
		else
			idx = 0;
	} else if (symbol->in_span) {
		if (symbol->pass)
			idx = 3;
		else if (symbol->span_end)
			idx = symbol->new_column ? 5 : symbol->join ? 6 : 7;
		else
			idx = symbol->new_column ? 8 : symbol->join ? 9 : 10;
	} else {
		idx = 3;
	}

	*sym = table[idx];
	(void) hline;
	*sep = NULL;
}

bool
graph_draw(struct view *view, const struct graph *graph, const struct graph_canvas *canvas)
{
	enum graphic mode = opt_line_graphics;
	size_t i;
	size_t position = 0;
	size_t span_end = 0;
	bool have_span = false;

	if (mode == GRAPHIC_AUTO)
		mode = (nl_langinfo(CODESET) && !strcasecmp(nl_langinfo(CODESET), "UTF-8")) ? GRAPHIC_UTF_8 : GRAPHIC_DEFAULT;

	for (i = 0; i < canvas->size; i++) {
		if (canvas->symbols[i].commit)
			position = i;
		if (canvas->symbols[i].in_span) {
			span_end = i;
			have_span = true;
		}
	}

	for (i = 0; i < canvas->size; i++) {
		const struct graph_symbol *symbol = &canvas->symbols[i];
		enum line_type type = LINE_PALETTE_0 + (symbol->color % 14);
		bool connector_hline = have_span && i >= position && i < span_end;
		const char *sym, *sep;

		if (symbol->commit)
			type = LINE_GRAPH_COMMIT;

		graph_symbol_chars(symbol, mode, &sym, &sep);

		if (mode == GRAPHIC_DEFAULT) {
			chtype ch;

			if (symbol->commit) {
				if (symbol->boundary) ch = 'o';
				else if (symbol->initial) ch = 'I';
				else if (symbol->merge) ch = 'M';
				else ch = 'o';
			} else if (symbol->in_span) {
				if (symbol->pass) ch = ACS_VLINE;
				else if (symbol->span_end) ch = symbol->new_column ? ACS_URCORNER : symbol->join ? ACS_LRCORNER : ACS_RTEE;
				else ch = symbol->new_column ? ACS_TTEE : symbol->join ? ACS_BTEE : ACS_PLUS;
			} else {
				ch = ACS_VLINE;
			}
			if (draw_graphic_char(view, type, ch))
				return true;
			if (i + 1 < canvas->size || true) {
				chtype conn = connector_hline ? ACS_HLINE : ' ';
				enum line_type ctype = connector_hline ? LINE_PALETTE_0 + (canvas->symbols[position].color % 14) : LINE_DEFAULT;

				if (i + 1 == canvas->size) {
					conn = ' ';
					ctype = LINE_DEFAULT;
				}
				if (draw_graphic_char(view, ctype, conn))
					return true;
			}
		} else {
			const char *conn = connector_hline ? (mode == GRAPHIC_UTF_8 ? "\xE2\x94\x80" : "-") : " ";
			enum line_type ctype = connector_hline ? LINE_PALETTE_0 + (canvas->symbols[position].color % 14) : LINE_DEFAULT;

			if (draw_text(view, type, sym))
				return true;
			if (i + 1 == canvas->size) {
				conn = " ";
				ctype = LINE_DEFAULT;
			}
			if (draw_text(view, ctype, conn))
				return true;
		}
	}

	return false;
}
