};

static void
main_register_commit(struct view *view, struct commit *commit, const char *ids, bool is_boundary)
{
	struct main_state *state = view->private;

	string_copy_rev(commit->id, ids);
	if (state->with_graph)
		graph_add_commit(state->graph, &commit->graph, commit->id, ids, is_boundary);
}

static struct commit *
main_add_commit(struct view *view, enum line_type type, struct commit *template,
		const char *title, bool custom)
{
	struct main_state *state = view->private;
	size_t titlelen;
	struct commit *commit;
	char buf[SIZEOF_STR / 2];
	struct line *line;

	/* FIXME: More graceful handling of titles; append "..." to
	 * shortened titles, etc. */
	string_expand(buf, sizeof(buf), title, -1, 1);
	title = chomp_string(buf);
	titlelen = strlen(title);

	line = add_line_alloc(view, &commit, type, titlelen, custom);
	if (!line)
		return NULL;

	*commit = *template;
	strncpy(commit->title, title, titlelen);
	memset(template, 0, sizeof(*template));
	state->reflogmsg[0] = 0;

	view_column_info_update(view, line);
	return commit;
}

void
string_expand(char *dst, size_t dstlen, const char *src, int srclen, int tabsize)
{
	size_t size, pos;

	for (size = pos = 0; size < dstlen - 1 && (srclen < 0 || pos < srclen) && src[pos]; pos++) {
		if (src[pos] == '\t') {
			size_t expanded = tabsize - (size % tabsize);

			if (expanded + size >= dstlen - 1)
				expanded = dstlen - size - 1;
			memcpy(dst + size, "        ", expanded);
			size += expanded;
		} else {
			dst[size++] = src[pos];
		}
	}

	dst[size] = 0;
}

static inline void
main_flush_commit(struct view *view, struct commit *commit)
{
	if (*commit->id)
		main_add_commit(view, LINE_MAIN_COMMIT, commit, "", false);
}

static bool
main_has_changes(const char *argv[])
{
	struct io io;

	if (!io_run(&io, IO_BG, NULL, NULL, argv))
		return false;
	io_done(&io);
	return io.status == 1;
}

static void
main_add_changes_commit(struct view *view, enum line_type type, const char *parent, const char *title)
{
	char ids[SIZEOF_STR] = NULL_ID " ";
	struct main_state *state = view->private;
	struct graph_canvas *canvas = &state->current.graph;
	struct commit commit = {{0}};
	struct timeval now;
	struct timezone tz;
	struct line *line;
	struct commit *c;
	size_t titlelen = strlen(title);

	if (!parent)
		return;

	if (*parent)
		string_copy_rev(ids + STRING_SIZE(NULL_ID " "), parent);
	else
		ids[STRING_SIZE(NULL_ID)] = 0;

	if (!gettimeofday(&now, &tz)) {
		time_t t = now.tv_sec;
		struct tm *lt = localtime(&t);

		commit.time.sec = now.tv_sec;
		commit.time.tz = lt ? lt->tm_gmtoff : 0;
	}
	commit.author = get_author("Not Committed Yet", "not.committed.yet");
	commit.committer = commit.author;
	commit.committer_time = commit.time;
	string_copy_rev(commit.id, NULL_ID);

	/* The graph for change commits is a single commit symbol. */
	{
		struct graph_symbol *sym = calloc(1, sizeof(*sym));

		if (sym) {
			sym->commit = 1;
			commit.graph.size = 1;
			commit.graph.symbols = sym;
		}
	}

	line = add_line_at(view, 0, NULL, type, sizeof(*c) + titlelen, true);
	if (!line)
		return;
	c = line->data;
	*c = commit;
	strncpy(c->title, title, titlelen);
	view_column_info_update(view, line);
	(void) canvas;
}

static bool
main_add_changes_commits(struct view *view, struct main_state *state, const char *parent)
{
	const char *staged_argv[] = { "git", "diff-index", "--quiet", "--cached", "HEAD", "--", NULL };
	const char *unstaged_argv[] = { "git", "diff-files", "--quiet", "--", NULL };
	const char *status_argv[] = { "git", "status", "--porcelain", "-z", "--untracked-files=normal", NULL };
	struct io io;
	char *line;
	bool staged = false, unstaged = false, untracked = false;

	if (!opt_show_changes)
		return true;

	if (!io_run(&io, IO_RD, repo.cdup, NULL, status_argv))
		return true;
	while ((line = io_get(&io, 0, true))) {
		if (strlen(line) < 3)
			continue;
		if (line[0] == '?' && line[1] == '?') {
			untracked = true;
		} else {
			if (line[0] != ' ' && line[0] != '?' && line[0] != '!')
				staged = true;
			if (line[1] != ' ' && line[1] != '?' && line[1] != '!')
				unstaged = true;
		}
		/* Renames have a second NUL-separated path. */
		if (line[0] == 'R' || line[0] == 'C' || line[1] == 'R' || line[1] == 'C')
			io_get(&io, 0, true);
	}
	io_done(&io);

	(void) staged_argv; (void) unstaged_argv;

	if (staged)
		main_add_changes_commit(view, LINE_STAT_STAGED, parent, "Staged changes");
	if (unstaged)
		main_add_changes_commit(view, LINE_STAT_UNSTAGED, parent, "Unstaged changes");
	if (untracked && opt_show_untracked)
		main_add_changes_commit(view, LINE_STAT_UNTRACKED, parent, "Untracked changes");

	return true;
}

static bool
main_check_argv(struct view *view, const char *argv[])
{
	struct main_state *state = view->private;
	bool with_reflog = false;
	int i;

	for (i = 0; argv[i]; i++) {
		const char *arg = argv[i];
		struct rev_flags rev_flags;

		if (!strcmp(arg, "--graph")) {
			struct view_column *column = get_view_column(view, VIEW_COLUMN_COMMIT_TITLE);

			if (column) {
				column->opt.commit_title.graph = GRAPH_DISPLAY_V2;
				if (opt_commit_order != COMMIT_ORDER_REVERSE)
					state->with_graph = true;
			}
			argv[i] = "";
			continue;
		}

		if (!strcmp(arg, "--first-parent")) {
			state->first_parent = true;
		}

		if (!strcmp(arg, "--walk-reflogs") || !strcmp(arg, "-g"))
			with_reflog = true;

		if (!argv_parse_rev_flag(arg, &rev_flags))
			continue;

		if (rev_flags.with_reflog)
			with_reflog = true;
		if (!rev_flags.with_graph)
			state->with_graph = false;
		arg += rev_flags.search_offset;
		if (*arg && !strstr(arg, "..") && !strcmp(arg, "HEAD") == false)
			;
	}

	return with_reflog;
}

bool
argv_parse_rev_flag(const char *arg, struct rev_flags *rev_flags)
{
	static const struct {
		const char *name;
		bool with_graph;
		bool with_reflog;
	} rev_flag_names[] = {
		{ "--no-walk", false, false },
		{ "--walk-reflogs", false, true },
		{ "-g", false, true },
		{ "--reflog", false, true },
		{ "--all", true, false },
		{ "--branches", true, false },
		{ "--tags", true, false },
		{ "--remotes", true, false },
		{ "--glob", true, false },
		{ "--exclude", true, false },
		{ "--not", true, false },
		{ "--stdin", true, false },
	};
	int i;

	memset(rev_flags, 0, sizeof(*rev_flags));
	rev_flags->with_graph = true;

	for (i = 0; i < ARRAY_SIZE(rev_flag_names); i++) {
		size_t len = strlen(rev_flag_names[i].name);

		if (!strncmp(arg, rev_flag_names[i].name, len) &&
		    (arg[len] == 0 || arg[len] == '=')) {
			rev_flags->with_graph = rev_flag_names[i].with_graph;
			rev_flags->with_reflog = rev_flag_names[i].with_reflog;
			return true;
		}
	}
	return false;
}

static const char *
commit_order_arg(struct view *view)
{
	struct main_state *state = view->private;

	switch (opt_commit_order) {
	case COMMIT_ORDER_AUTO:
		return state->with_graph ? "--topo-order" : "";
	case COMMIT_ORDER_TOPO:
		return "--topo-order";
	case COMMIT_ORDER_DATE:
		return "--date-order";
	case COMMIT_ORDER_AUTHOR_DATE:
		return "--author-date-order";
	case COMMIT_ORDER_REVERSE:
		return "--reverse";
	default:
		return "";
	}
}

static bool
main_open(struct view *view, enum open_flags flags)
{
	struct view_column *commit_title_column = get_view_column(view, VIEW_COLUMN_COMMIT_TITLE);
	const char *pretty_custom_argv[] = {
		"git", "log", "--encoding=UTF-8", "%(commit-order)", "%(cmdlineargs)", "%(revargs)",
		"--date=raw", "--parents", "--no-color", "%(notes)",
		"--pretty=format:commit %m %H %P%x00%aN <%aE> %ad%x00%cN <%cE> %cd%x00%s%x00%N%x03",
		"--", "%(fileargs)", NULL
	};
	const char *pretty_raw_argv[] = {
		"git", "log", "--encoding=UTF-8", "%(commit-order)", "%(cmdlineargs)", "%(revargs)",
		"--date=raw", "--parents", "--no-color", "--pretty=raw", "--", "%(fileargs)", NULL
	};
	struct main_state *state = view->private;
	const char **main_argv = pretty_custom_argv;
	enum graph_display graph_display = commit_title_column ? commit_title_column->opt.commit_title.graph : GRAPH_DISPLAY_NO;
	enum open_flags main_flags = flags;
	const char *argv[SIZEOF_ARGV + 8];
	int argc = 0, i;
	bool with_reflog;

	if (opt_commit_order != COMMIT_ORDER_REVERSE && graph_display != GRAPH_DISPLAY_NO)
		state->with_graph = true;
	else
		state->with_graph = false;
	state->first_parent = false;
	state->changes_parents = false;

	with_reflog = main_check_argv(view, opt_cmdline_args ? opt_cmdline_args : (const char *[]) { NULL });
	if (!main_check_argv(view, opt_rev_args ? opt_rev_args : (const char *[]) { NULL }))
		;

	if (opt_rev_args && argv_contains(opt_rev_args, "--pretty=raw"))
		main_argv = pretty_raw_argv;
	if (opt_cmdline_args && argv_contains(opt_cmdline_args, "--pretty=raw"))
		main_argv = pretty_raw_argv;

	if (open_in_pager_mode(flags) && !argv_contains(opt_cmdline_args, "--stdin")) {
		main_flags |= OPEN_PAGER_MODE;
	}

	if (state->graph)
		done_graph(state->graph);
	state->graph = state->with_graph ? init_graph(graph_display) : NULL;
	memset(&state->current, 0, sizeof(state->current));
	state->in_header = false;
	state->added_changes_commits = false;
	state->reading_notes = false;
	state->reflogmsg[0] = 0;

	/* Expand our custom placeholders. */
	for (i = 0; main_argv[i] && argc < SIZEOF_ARGV; i++) {
		const char *arg = main_argv[i];

		if (!strcmp(arg, "%(commit-order)")) {
			const char *order = commit_order_arg(view);

			if (*order)
				argv[argc++] = order;
			continue;
		}
		if (!strcmp(arg, "%(notes)")) {
			if (opt_show_notes)
				argv[argc++] = opt_notes_arg;
			continue;
		}
		if (!strcmp(arg, "%(cmdlineargs)")) {
			argv[argc++] = arg;
			if (opt_main_options)
				argv[argc++] = "%(mainargs)";
			continue;
		}
		argv[argc++] = arg;
	}
	argv[argc] = NULL;

	(void) with_reflog;
	return begin_update(view, NULL, argv, main_flags);
}

static void
main_done(struct view *view)
{
	struct main_state *state = view->private;
	int i;

	for (i = 0; i < view->lines; i++) {
		struct commit *commit = view->line[i].data;

		free(commit->graph.symbols);
	}

	for (i = 0; i < state->reflogs; i++)
		free(state->reflog[i]);
	free(state->reflog);
	state->reflog = NULL;
	state->reflogs = 0;
	if (state->graph) {
		done_graph(state->graph);
		state->graph = NULL;
	}
}

#define main_check_commit_refs(line)	!((line)->no_commit_refs)
#define main_mark_no_commit_refs(line)	(((struct line *) (line))->no_commit_refs = 1)

static inline const struct ref *
main_get_commit_refs(const struct line *line, struct commit *commit)
{
	const struct ref *refs = NULL;

	if (main_check_commit_refs(line) && !(refs = get_ref_list(commit->id)))
		main_mark_no_commit_refs(line);

	return refs;
}

static bool
main_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	struct main_state *state = view->private;
	struct commit *commit = line->data;

	column_data->author = commit->author;
	column_data->date = &commit->time;
	column_data->id = commit->id;
	if (state->reflogs)
		column_data->reflog = state->reflog[line->lineno - 1];

	column_data->commit_title = commit->title;
	if (state->with_graph) {
		column_data->graph = state->graph;
		column_data->graph_canvas = &commit->graph;
	}
	if (line->type == LINE_STAT_STAGED || line->type == LINE_STAT_UNSTAGED || line->type == LINE_STAT_UNTRACKED) {
		column_data->graph = state->graph ? state->graph : (struct graph *) 1;
		column_data->graph_canvas = &commit->graph;
		if (!state->with_graph) {
			column_data->graph = NULL;
			column_data->graph_canvas = NULL;
		}
	}

	column_data->refs = main_get_commit_refs(line, commit);
	{
		struct view_column *column;

		for (column = view->columns; column; column = column->next)
			if (column->type == VIEW_COLUMN_DATE && column->opt.date.use_author)
				column_data->date = &commit->time;
			else if (column->type == VIEW_COLUMN_DATE)
				column_data->date = &commit->committer_time;
			else if (column->type == VIEW_COLUMN_COMMITTER)
				;
	}
	return true;
}

static bool
main_get_column_data_committer(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	return main_get_column_data(view, line, column_data);
}

static bool
main_add_reflog(struct view *view, struct main_state *state, char *reflog)
{
	char *end = strchr(reflog, ' ');
	int id_width;

	if (!end)
		return false;
	*end = 0;

	if (!realloc_reflogs(&state->reflog, state->reflogs, 1))
		return false;

	state->reflog[state->reflogs++] = str_dup(reflog);
	id_width = strlen(reflog);
	if (state->reflog_width < id_width) {
		state->reflog_width = id_width;
		if (opt_id_width == 0)
			view->force_redraw = true;
	}

	return true;
}

bool
realloc_reflogs(char ***reflog, size_t size, size_t extra)
{
	char **tmp = realloc(*reflog, (size + extra) * sizeof(**reflog));

	if (!tmp)
		return false;
	*reflog = tmp;
	return true;
}

static bool
main_read_pretty_raw(struct view *view, struct main_state *state, char *line)
{
	struct commit *commit = &state->current;
	enum line_type type;

	if (!line) {
		main_flush_commit(view, commit);
		return true;
	}

	type = get_line_type(line);
	if (type == LINE_COMMIT) {
		bool is_boundary;

		state->in_header = true;
		line += STRING_SIZE("commit ");
		is_boundary = *line == '-';
		while (*line == '-' || *line == '<' || *line == '>')
			line++;
		while (*line == ' ')
			line++;

		main_flush_commit(view, commit);

		main_register_commit(view, &state->current, line, is_boundary);
		return true;
	}

	if (!*commit->id)
		return true;

	/* Empty line separates the commit header from the log itself. */
	if (*line == '\0')
		state->in_header = false;

	switch (type) {
	case LINE_PP_REFLOG:
		if (!main_add_reflog(view, state, line + STRING_SIZE("Reflog: ")))
			return false;
		break;

	case LINE_PP_REFLOGMSG:
		line += STRING_SIZE("Reflog message: ");
		string_ncopy(state->reflogmsg, line, strlen(line));
		break;

	case LINE_PARENT:
		if (state->with_graph && !graph_add_parent(state->graph, line + STRING_SIZE("parent ")))
			return false;
		break;

	case LINE_AUTHOR:
		{
			const char *author;
			char *ident = line + STRING_SIZE("author ");
			const char *email;

			parse_author_line(ident, &author, &commit->time);
			email = strchr(ident, 0) + 1;
			if (email <= ident + strlen(line) + 1 && strchr(line, '<'))
				commit->author = get_author(author, email);
			else
				commit->author = get_author(author, "");
			if (state->with_graph)
				graph_render_parents(state->graph, &commit->graph);
		}
		break;

	case LINE_COMMITTER:
		{
			const char *author;
			char *ident = line + STRING_SIZE("committer ");

			parse_author_line(ident, &author, &commit->committer_time);
			commit->committer = get_author(author, strchr(ident, 0) + 1);
		}
		break;

	default:
		/* Fill in the commit title if it has not already been set. */
		if (*commit->title)
			break;

		/* Skip lines in the commit header. */
		if (state->in_header)
			break;

		/* Require titles to start with a non-space character, to
		 * avoid "dangling" titles as can be produced by commit
		 * messages with "     " on the first line. */
		if (isspace((unsigned char) *line))
			break;

		{
			const char *title = *state->reflogmsg ? state->reflogmsg : line;

			if (!main_add_commit(view, LINE_MAIN_COMMIT, commit, title, false))
				return false;
		}
	}

	return true;
}

static bool
main_read(struct view *view, struct buffer *buf, bool force_stop)
{
	struct main_state *state = view->private;
	struct commit *commit = &state->current;
	char *line;
	char *fields[8];
	int nfields = 0;
	char *p;
	bool is_boundary;
	bool raw = (opt_cmdline_args && argv_contains(opt_cmdline_args, "--pretty=raw")) ||
		   (opt_rev_args && argv_contains(opt_rev_args, "--pretty=raw"));

	if (raw)
		return main_read_pretty_raw(view, state, buf ? buf->data : NULL);

	if (!buf) {
		if (state->reading_notes) {
			state->reading_notes = false;
		}
		main_flush_commit(view, commit);

		if (!state->added_changes_commits && opt_show_changes && repo.is_inside_work_tree) {
			state->added_changes_commits = true;
			/* Only add changes when HEAD is part of the view. */
			if (view->lines > 0) {
				size_t i;
				bool head_found = false;

				for (i = 0; i < view->lines; i++) {
					struct commit *c = view->line[i].data;

					if (*repo.head_id && !strcmp(c->id, repo.head_id)) {
						head_found = true;
						break;
					}
				}
				if (head_found || !*repo.head_id)
					main_add_changes_commits(view, state, repo.head_id);
			}
		}

		if (state->graph)
			done_graph_rendering(state->graph);
		return true;
	}

	line = buf->data;

	if (state->reading_notes) {
		/* Continuation of notes; ends at \x03 */
		char *end = strchr(line, '\x03');

		if (end) {
			*end = 0;
			state->reading_notes = false;
			/* Flush commit after notes end. */
			main_flush_commit(view, commit);
		}
		return true;
	}

	if (prefixcmp(line, "commit "))
		return true;

	/* Fields separated by NUL within the buffer. */
	{
		size_t len = buf->size;
		char *end = line + len;

		p = line;
		while (p < end && nfields < 8) {
			fields[nfields++] = p;
			p = memchr(p, 0, end - p);
			if (!p)
				break;
			p++;
		}
	}

	if (nfields < 4)
		return true;

	/* Flush any pending commit. */
	main_flush_commit(view, commit);

	/* commit %m %H %P */
	p = fields[0] + STRING_SIZE("commit ");
	is_boundary = *p == '-';
	while (*p == '-' || *p == '<' || *p == '>')
		p++;
	while (*p == ' ')
		p++;

	main_register_commit(view, commit, p, is_boundary);

	if (state->with_graph) {
		char *parents = p + strcspn(p, " ");

		while (*parents == ' ')
			parents++;
		while (*parents) {
			char parent[SIZEOF_REV];
			size_t plen = strcspn(parents, " ");

			string_ncopy(parent, parents, plen);
			if (!graph_add_parent(state->graph, parent))
				return false;
			parents += plen;
			while (*parents == ' ')
				parents++;
			if (state->first_parent)
				break;
		}
		graph_render_parents(state->graph, &commit->graph);
	}

	/* author */
	{
		const char *author;
		char *ident = fields[1];
		char *lt = strchr(ident, '<');
		char *gt = strchr(ident, '>');
		char email[SIZEOF_STR] = "";

		if (lt && gt && gt > lt)
			string_ncopy(email, lt + 1, gt - lt - 1);
		parse_author_line(ident, &author, &commit->time);
		commit->author = get_author(author, email);
	}

	/* committer */
	{
		const char *author;
		char *ident = fields[2];
		char *lt = strchr(ident, '<');
		char *gt = strchr(ident, '>');
		char email[SIZEOF_STR] = "";

		if (lt && gt && gt > lt)
			string_ncopy(email, lt + 1, gt - lt - 1);
		parse_author_line(ident, &author, &commit->committer_time);
		commit->committer = get_author(author, email);
	}

	/* title */
	{
		char *title = fields[3];
		char *notes = nfields > 4 ? fields[4] : NULL;
		char *end;

		if (notes) {
			end = strchr(notes, '\x03');
			if (end)
				*end = 0;
			else
				state->reading_notes = true;
		} else {
			end = strchr(title, '\x03');
			if (end)
				*end = 0;
		}

		if (!main_add_commit(view, LINE_MAIN_COMMIT, commit, title, false))
			return false;
	}

	return true;
}

static enum request
main_request(struct view *view, enum request request, struct line *line)
{
	enum open_flags flags = (view_is_displayed(view) && request != REQ_VIEW_DIFF)
				? OPEN_SPLIT : OPEN_DEFAULT;

	switch (request) {
	case REQ_NEXT:
	case REQ_PREVIOUS:
		if (view_is_displayed(view) && display[0] != view)
			return request;
		/* Do not pass down to view_request. */
		if (request == REQ_NEXT)
			move_view(view, REQ_MOVE_DOWN);
		else
			move_view(view, REQ_MOVE_UP);
		return REQ_NONE;

	case REQ_VIEW_DIFF:
	case REQ_ENTER:
		if (view_is_displayed(view) && display[0] != view)
			maximize_view(view, true);

		if (line->type == LINE_STAT_UNSTAGED
		    || line->type == LINE_STAT_STAGED
		    || line->type == LINE_STAT_UNTRACKED)
			open_stage_view(view, NULL, line->type, flags);
		else
			open_view(view, view_from_request(REQ_VIEW_DIFF), flags);
		break;

	case REQ_REFRESH:
		load_refs(true);
		refresh_view(view);
		break;

	case REQ_JUMP_COMMIT:
	{
		int lineno;

		for (lineno = 0; lineno < view->lines; lineno++) {
			struct commit *commit = view->line[lineno].data;

			if (!strncasecmp(commit->id, view->env->goto_id, strlen(view->env->goto_id))) {
				select_view_line(view, lineno);
				report_clear();
				return REQ_NONE;
			}
		}

		report("Unable to find commit '%s'", view->env->goto_id);
		break;
	}
	default:
		return request;
	}

	return REQ_NONE;
}

static bool
main_grep(struct view *view, struct line *line)
{
	return view_column_grep(view, line);
}

static void
main_select(struct view *view, struct line *line)
{
	struct commit *commit = line->data;

	if (line->type == LINE_STAT_STAGED || line->type == LINE_STAT_UNSTAGED || line->type == LINE_STAT_UNTRACKED) {
		string_ncopy(view->ref, commit->title, strlen(commit->title));
		string_copy_rev(view->env->commit, NULL_ID);
	} else {
		struct main_state *state = view->private;
		const struct ref *ref;

		if (state->reflogs) {
			string_ncopy(view->ref, state->reflog[line->lineno - 1], strlen(state->reflog[line->lineno - 1]));
		} else {
			string_copy_rev(view->ref, commit->id);
		}
		string_copy_rev(view->env->commit, commit->id);
		/* Update branch/tag env from the refs. */
		view->env->branch[0] = 0;
		view->env->tag[0] = 0;
		view->env->remote[0] = 0;
		view->env->refname[0] = 0;
		for (ref = get_ref_list(commit->id); ref; ref = ref->next) {
			if (ref->type == REFERENCE_HEAD || ref->type == REFERENCE_BRANCH) {
				if (!*view->env->branch)
					string_ncopy(view->env->branch, ref->name, strlen(ref->name));
				if (!*view->env->refname)
					string_ncopy(view->env->refname, ref->name, strlen(ref->name));
			} else if (ref_is_tag(ref)) {
				if (!*view->env->tag)
					string_ncopy(view->env->tag, ref->name, strlen(ref->name));
			} else if (ref_is_remote(ref)) {
				const char *sep = strchr(ref->name, '/');

				if (!*view->env->remote && sep) {
					string_ncopy(view->env->remote, ref->name, sep - ref->name);
					if (!*view->env->branch)
						string_ncopy(view->env->branch, sep + 1, strlen(sep + 1));
				}
			}
		}
	}
	view->env->blob[0] = 0;
}

