static bool
reflog_open(struct view *view, enum open_flags flags)
{
	const char *reflog_argv[] = {
		"git", "reflog", "show", "--encoding=UTF-8", "--no-color", "--pretty=raw",
		"%(cmdlineargs)", "%(revargs)", NULL
	};
	struct main_state *state = view->private;

	state->with_graph = false;
	if (state->graph) {
		done_graph(state->graph);
		state->graph = NULL;
	}
	memset(&state->current, 0, sizeof(state->current));
	state->in_header = false;
	state->reflogmsg[0] = 0;
	{
		int i;

		for (i = 0; i < state->reflogs; i++)
			free(state->reflog[i]);
		free(state->reflog);
		state->reflog = NULL;
		state->reflogs = 0;
		state->reflog_width = 0;
	}

	return begin_update(view, NULL, reflog_argv, flags);
}

static bool
reflog_read(struct view *view, struct buffer *buf, bool force_stop)
{
	struct main_state *state = view->private;

	return main_read_pretty_raw(view, state, buf ? buf->data : NULL);
}

static enum request
reflog_request(struct view *view, enum request request, struct line *line)
{
	struct commit *commit = line->data;

	switch (request) {
	case REQ_ENTER:
		open_view(view, view_from_request(REQ_VIEW_DIFF), OPEN_SPLIT);
		return REQ_NONE;

	case REQ_REFRESH:
		load_refs(true);
		refresh_view(view);
		return REQ_NONE;

	default:
		(void) commit;
		return main_request(view, request, line);
	}
}

