	reflog_request,
	main_grep,
	main_select,
	main_done,
	(1 << VIEW_COLUMN_AUTHOR) | (1 << VIEW_COLUMN_COMMITTER) | (1 << VIEW_COLUMN_DATE) | (1 << VIEW_COLUMN_ID) |
	(1 << VIEW_COLUMN_LINE_NUMBER) | (1 << VIEW_COLUMN_COMMIT_TITLE) | (1 << VIEW_COLUMN_REF),
	main_get_column_data,
};

