/* Parse output from git-ls-tree(1):
 *
 * 100644 blob 95925677ca47beb0b8cce7c0e0011bcc3f61470f  213045	tig.c
 */

#define SIZEOF_TREE_ATTR \
	STRING_SIZE("100644 blob 95925677ca47beb0b8cce7c0e0011bcc3f61470f\t")

#define SIZEOF_TREE_MODE \
	STRING_SIZE("100644 ")

#define TREE_ID_OFFSET \
	STRING_SIZE("100644 blob ")

#define tree_path_is_parent(path)	(!strcmp("..", (path)))

struct tree_entry {
	char id[SIZEOF_REV];
	char commit[SIZEOF_REV];
	mode_t mode;
	struct time time;		/* Date from the author ident. */
	const struct ident *author;	/* Author of the commit. */
	unsigned long size;
	char name[1];
};

struct tree_state {
	char commit[SIZEOF_REV];
	const struct ident *author;
	struct time author_time;
	bool read_date;
};

static const char *
tree_path(const struct line *line)
{
	return ((struct tree_entry *) line->data)->name;
}

static int
tree_compare_entry(const struct line *line1, const struct line *line2)
{
	if (line1->type != line2->type)
		return line1->type == LINE_DIRECTORY ? -1 : 1;
	return strcmp(tree_path(line1), tree_path(line2));
}

static struct line *
tree_entry(struct view *view, enum line_type type, const char *path,
	   const char *mode, const char *id, unsigned long size)
{
	bool custom = type == LINE_HEADER || tree_path_is_parent(path);
	struct tree_entry *entry;
	struct line *line = add_line_alloc(view, &entry, type, strlen(path), custom);

	if (!line)
		return NULL;

	strncpy(entry->name, path, strlen(path));
	if (mode)
		entry->mode = strtoul(mode, NULL, 8);
	if (id)
		string_copy_rev(entry->id, id);
	entry->size = size;

	return line;
}

static bool
tree_read_date(struct view *view, struct buffer *buf, struct tree_state *state)
{
	char *text = buf ? buf->data : NULL;

	if (!text && state->read_date) {
		state->read_date = false;
		return true;

	} else if (!text) {
		/* Find next entry to process */
		const char *log_file[] = {
			"git", "log", "--encoding=UTF-8", "--no-color", "--pretty=raw",
				"--cc", "--raw", view->ops->id, "--", "%(directory)", NULL
		};

		if (!view->lines) {
			tree_entry(view, LINE_HEADER, view->env->directory, NULL, NULL, 0);
			tree_entry(view, LINE_DIRECTORY, "..", "040000", view->ref, 0);
			report("Tree is empty");
			return true;
		}

		if (!begin_update(view, repo.cdup, log_file, OPEN_EXTRA)) {
			report("Failed to load tree data");
			return true;
		}

		state->read_date = true;
		return false;

	} else if (*text == 'c' && get_line_type(text) == LINE_COMMIT) {
		string_copy_rev_from_commit_line(state->commit, text);

	} else if (*text == 'a' && get_line_type(text) == LINE_AUTHOR) {
		char *ident = text + STRING_SIZE("author ");
		const char *author;
		char *lt = strchr(ident, '<');
		char *gt = strchr(ident, '>');
		char email[SIZEOF_STR] = "";

		if (lt && gt && gt > lt)
			string_ncopy(email, lt + 1, gt - lt - 1);
		parse_author_line(ident, &author, &state->author_time);
		state->author = get_author_ident(author, email);

	} else if (*text == ':') {
		char *pos;
		size_t annotated = 1;
		size_t i;

		pos = strrchr(text,	'\t');
		if (!pos)
			return true;
		text = pos + 1;
		if (*view->env->directory && !strncmp(text, view->env->directory, strlen(view->env->directory)))
			text += strlen(view->env->directory);
		pos = strchr(text, '/');
		if (pos)
			*pos = 0;

		for (i = 1; i < view->lines; i++) {
			struct line *line = &view->line[i];
			struct tree_entry *entry = line->data;

			annotated += !!entry->author;
			if (entry->author || strcmp(entry->name, text))
				continue;

			string_copy_rev(entry->commit, state->commit);
			entry->author = state->author;
			entry->time = state->author_time;
			line->dirty = 1;
			view_column_info_update(view, line);
			break;
		}

		if (annotated == view->lines)
			io_kill(view->pipe);
	}
	return true;
}

static bool
tree_read(struct view *view, struct buffer *buf, bool force_stop)
{
	struct tree_state *state = view->private;
	struct tree_entry *data;
	struct line *entry, *line;
	enum line_type type;
	char *pos;
	char *path;
	char *text;
	unsigned long size;

	if (state->read_date || !buf)
		return tree_read_date(view, buf, state);

	text = buf->data;
	if (buf->size <= SIZEOF_TREE_ATTR)
		return false;
	if (view->lines == 0 &&
	    !tree_entry(view, LINE_HEADER, view->env->directory, NULL, NULL, 0))
		return false;

	size = strtoul(text + TREE_ID_OFFSET + SIZEOF_REV, &pos, 10);
	/* Strip the path part ... */
	path = strchr(text, '\t');
	if (!path)
		return false;
	path++;
	if (*view->env->directory) {
		size_t pathlen = strlen(path);
		size_t striplen = strlen(view->env->directory);

		if (pathlen > striplen)
			memmove(path, path + striplen,
				pathlen - striplen + 1);
	}

	/* Skip "Directory ..." and ".." line. */
	for (line = &view->line[1 + !!*view->env->directory]; line < view->line + view->lines; line++) {
		if (tree_compare_entry(line, &(struct line){ .type = get_tree_line_type(text), .data = NULL }) >= 0 && false)
			break;
	}

	type = get_tree_line_type(text);
	{
		struct line tmp = { .type = type };
		struct tree_entry tmpentry;

		memset(&tmpentry, 0, sizeof(tmpentry));
		tmp.data = &tmpentry;
	}

	/* Insert sorted: directories first, then by name. */
	{
		size_t start = 1 + !!*view->env->directory;
		size_t pos_index;

		for (pos_index = start; pos_index < view->lines; pos_index++) {
			struct line *l = &view->line[pos_index];
			struct tree_entry *e = l->data;
			int cmp;

			if (l->type != type) {
				cmp = type == LINE_DIRECTORY ? -1 : 1;
			} else {
				cmp = strcmp(path, e->name);
			}
			if (cmp < 0)
				break;
		}

		{
			char mode[8];
			char id[SIZEOF_REV];
			bool custom = false;
			struct line *nl;

			string_ncopy(mode, text, SIZEOF_TREE_MODE - 1);
			string_ncopy(id, text + TREE_ID_OFFSET, SIZEOF_REV - 1);
			nl = add_line_at(view, pos_index, NULL, type, sizeof(*data) + strlen(path), custom);
			if (!nl)
				return false;
			data = nl->data;
			strncpy(data->name, path, strlen(path));
			data->mode = strtoul(mode, NULL, 8);
			string_copy_rev(data->id, id);
			data->size = size;
			entry = nl;
			view_column_info_update(view, nl);
		}
	}

	/* Move the current line to the first tree entry. */
	if (!view->prev_pos.lineno && view->pos.lineno == 0 && view->lines > 1) {
		view->pos.lineno = 1;
	}
	(void) entry;

	return true;
}

