#include "tig.h"

/*
 * Blame backend
 *
 * Loading the blame view is a two phase job:
 *
 *  1. File content is read either using argv_env.file from the
 *     filesystem or using git-cat-file.
 *  2. Then blame information is incrementally added by
 *     reading output from git-blame.
 */

struct blame_header {
	char id[SIZEOF_REV];		/* SHA1 ID. */
	size_t orig_lineno;
	size_t lineno;
	size_t group;
};

struct blame_commit {
	char id[SIZEOF_REV];		/* SHA1 ID. */
	char title[128];		/* First line of the commit message. */
	const struct ident *author;	/* Author of the commit. */
	struct time time;		/* Date from the author ident. */
	char filename[128];		/* Name of file. */
	char parent_id[SIZEOF_REV];	/* Parent/previous SHA1 ID. */
	char parent_filename[128];	/* Parent/previous name of file. */
};

struct blame {
	struct blame_commit *commit;
	unsigned long lineno;
	char text[1];
};

struct blame_state {
	struct blame_commit *commit;
	int blamed;
	bool done_reading;
	bool auto_filename_display;
	struct view_history *history;
	struct blame_history_state {
		char id[SIZEOF_REV];
		const char *filename;
	} history_state;
	char line_buf[SIZEOF_STR];
};

static struct view_history blame_view_history = { sizeof(struct blame_history_state) };

static bool
blame_detect_filename_display(struct view *view)
{
	bool show_filenames = false;
	const char *filename = NULL;
	int i;

	if (opt_blame_options) {
		for (i = 0; opt_blame_options[i]; i++) {
			if (prefixcmp(opt_blame_options[i], "-C"))
				continue;

			show_filenames = true;
		}
	}

	for (i = 0; i < view->lines; i++) {
		struct blame *blame = view->line[i].data;

		if (blame->commit && blame->commit->id[0]) {
			if (!filename)
				filename = blame->commit->filename;
			else if (strcmp(filename, blame->commit->filename))
				show_filenames = true;
		}
	}

	return show_filenames;
}

static bool
blame_open(struct view *view, enum open_flags flags)
{
	struct blame_state *state = view->private;
	const char *file_argv[] = { repo.cdup, view->env->file , NULL };
	char path[SIZEOF_STR];
	size_t i;

	if (is_initial_view(view)) {
		/* Finish validating and setting up blame options */
		const char **args = get_blame_args();
		const char *file = NULL;
		const char *rev = NULL;
		const char **opts = NULL;
		bool dashdash = false;
		int j;

		for (j = 0; args && args[j]; j++) {
			const char *arg = args[j];

			if (!strcmp(arg, "--")) {
				dashdash = true;
				continue;
			}
			if (dashdash) {
				file = arg;
			} else if (arg[0] == '-') {
				argv_append(&opts, arg);
			} else if (!file && args[j + 1] && !dashdash) {
				/* rev then file */
				rev = arg;
			} else {
				file = arg;
			}
		}
		if (!file && rev) {
			file = rev;
			rev = NULL;
		}
		if (!file)
			die("No file chosen, press %s to open tree view", "t");
		string_ncopy(view->env->file, file, strlen(file));
		if (rev)
			string_ncopy(view->env->ref, rev, strlen(rev));
		if (opts) {
			argv_free(opt_blame_options);
			free(opt_blame_options);
			opt_blame_options = opts;
		}
	}

	if (!view->env->file[0]) {
		report("No file chosen, press %s to open tree view", get_view_key(view, REQ_VIEW_TREE));
		return false;
	}

	if (!view->prev && *repo.prefix && !(flags & (OPEN_RELOAD | OPEN_REFRESH))) {
		string_copy(path, view->env->file);
		if (!string_format(view->env->file, "%s%s", repo.prefix, path)) {
			report("Failed to setup the blame view");
			return false;
		}
	}

	if (*view->env->ref || !begin_update(view, repo.cdup, file_argv, flags)) {
		const char *blame_cat_file_argv[] = {
			"git", "cat-file", "blob", "%(ref):%(file)", NULL
		};

		if (!begin_update(view, repo.cdup, blame_cat_file_argv, flags))
			return false;
	}

	/* First pass: remove multiple references to the same commit. */
	for (i = 0; i < view->lines; i++) {
		struct blame *blame = view->line[i].data;

		if (blame->commit && blame->commit->id[0])
			blame->commit->id[0] = 0;
		else
			blame->commit = NULL;
	}

	/* Second pass: free existing references. */
	for (i = 0; i < view->lines; i++) {
		struct blame *blame = view->line[i].data;

		if (blame->commit)
			free(blame->commit);
	}

	if (!(flags & OPEN_RELOAD))
		reset_view_history(&blame_view_history);
	string_copy_rev(state->history_state.id, view->env->ref);
	state->history_state.filename = get_path_from_argv_env(view->env->file);
	string_copy(view->vid, view->env->file);
	string_format(view->ref, "%s ...", view->env->file);
	state->blamed = 0;
	state->done_reading = false;
	state->commit = NULL;
	state->auto_filename_display = false;

	return true;
}

const char *
get_path_from_argv_env(const char *file)
{
	static char buf[SIZEOF_STR];

	string_ncopy(buf, file, strlen(file));
	return buf;
}

static struct blame_commit *
get_blame_commit(struct view *view, const char *id)
{
	size_t i;

	for (i = 0; i < view->lines; i++) {
		struct blame *blame = view->line[i].data;

		if (!blame->commit)
			continue;

		if (!strncmp(blame->commit->id, id, SIZEOF_REV - 1))
			return blame->commit;
	}

	{
		struct blame_commit *commit = calloc(1, sizeof(*commit));

		if (commit)
			string_ncopy(commit->id, id, SIZEOF_REV);
		return commit;
	}
}

static struct blame_commit *
read_blame_commit(struct view *view, const char *text, struct blame_state *state)
{
	struct blame_header header;
	struct blame_commit *commit;
	struct blame *blame;

	if (!parse_blame_header(&header, text))
		return NULL;

	commit = get_blame_commit(view, text);
	if (!commit)
		return NULL;

	state->blamed += header.group;
	while (header.group--) {
		struct line *line = &view->line[header.lineno + header.group - 1];

		blame = line->data;
		blame->commit = commit;
		blame->lineno = header.orig_lineno + header.group - 1;
		line->dirty = 1;
	}

	return commit;
}

bool
parse_blame_header(struct blame_header *header, const char *text)
{
	const char *pos = text + SIZEOF_REV - 2;

	if (strlen(text) <= SIZEOF_REV || pos[0] != ' ')
		return false;

	string_ncopy(header->id, text, SIZEOF_REV);

	if (!parse_number(&pos, &header->orig_lineno, 1, 9999999) ||
	    !parse_number(&pos, &header->lineno, 1, 9999999) ||
	    !parse_number(&pos, &header->group, 1, 9999999))
		return false;

	return true;
}

bool
parse_number(const char **posref, size_t *number, size_t min, size_t max)
{
	const char *pos = *posref;

	*posref = NULL;
	pos = strchr(pos + 1, ' ');
	if (!pos || !isdigit((unsigned char) pos[1]))
		return false;
	*number = atoi(pos + 1);
	if (*number < min || *number > max)
		return false;

	*posref = pos;
	return true;
}

static bool
blame_read_file(struct view *view, struct buffer *buf, struct blame_state *state)
{
	if (!buf) {
		const char *blame_argv[] = {
			"git", "blame", "--encoding=UTF-8", "%(blameargs)", "--incremental",
				*view->env->ref ? view->env->ref : "--incremental", "--", view->env->file, NULL
		};
		const char *blame_argv2[] = {
			"git", "blame", "--encoding=UTF-8", "%(blameargs)", "-p", "--", view->env->file, NULL
		};

		if (view->lines == 0 && !view->prev)
			die("No blame exist for %s", view->vid);

		(void) blame_argv;
		if (view->lines == 0 || !begin_update(view, repo.cdup, *view->env->ref ? (const char *[]) {
			"git", "blame", "--encoding=UTF-8", "%(blameargs)", "-p", view->env->ref, "--", view->env->file, NULL } : blame_argv2, OPEN_EXTRA)) {
			report("Failed to load blame data");
			return true;
		}

		if (view->env->goto_lineno > 0) {
			select_view_line(view, view->env->goto_lineno);
			view->env->goto_lineno = 0;
		}

		state->done_reading = true;
		return false;

	} else {
		struct blame *blame;
		size_t linelen = buf->size;
		struct line *line = add_line_alloc(view, &blame, LINE_DEFAULT, linelen, false);

		if (!line)
			return false;

		blame->commit = NULL;
		strncpy(blame->text, buf->data, linelen);
		blame->text[linelen] = 0;
		return true;
	}
}

static bool
blame_read(struct view *view, struct buffer *buf, bool force_stop)
{
	struct blame_state *state = view->private;

	if (!state->done_reading)
		return blame_read_file(view, buf, state);

	if (!buf) {
		state->auto_filename_display = blame_detect_filename_display(view);
		string_format(view->ref, "%s", view->vid);
		if (view_is_displayed(view)) {
			update_view_title(view);
			redraw_view_from(view, 0);
		}
		return true;
	}

	if (!state->commit) {
		state->commit = read_blame_commit(view, buf->data, state);
		string_format(view->ref, "%s %2zd%%", view->vid,
			      view->lines ? state->blamed * 100 / view->lines : 0);

	} else if (parse_blame_info(state->commit, state->line_buf, buf->data)) {
		bool update_view_columns = true;
		size_t i;

		state->commit = NULL;
		for (i = 0; i < view->lines; i++) {
			struct line *line = &view->line[i];
			struct blame *blame = line->data;

			if (blame && blame->commit && *blame->commit->id && update_view_columns)
				view_column_info_update(view, line);
		}
	}

	return true;
}

bool
parse_blame_info(struct blame_commit *commit, char author[SIZEOF_STR], char *line)
{
	if (match_blame_header("author ", &line)) {
		string_ncopy_do(author, SIZEOF_STR, line, strlen(line));

	} else if (match_blame_header("author-mail ", &line)) {
		char *end = strchr(line, '>');

		if (end)
			*end = 0;
		if (*line == '<')
			line++;
		commit->author = get_author_ident(author, line);
		author[0] = 0;

	} else if (match_blame_header("author-time ", &line)) {
		parse_timesec(&commit->time, line);

	} else if (match_blame_header("author-tz ", &line)) {
		parse_timezone(&commit->time, line);

	} else if (match_blame_header("summary ", &line)) {
		string_ncopy(commit->title, line, strlen(line));

	} else if (match_blame_header("previous ", &line)) {
		if (strlen(line) <= SIZEOF_REV)
			return false;
		string_copy_rev(commit->parent_id, line);
		line += SIZEOF_REV;
		string_ncopy(commit->parent_filename, line, strlen(line));

	} else if (match_blame_header("filename ", &line)) {
		string_ncopy(commit->filename, line, strlen(line));
		return true;
	}

	return false;
}

bool
match_blame_header(const char *name, char **line)
{
	size_t namelen = strlen(name);
	bool matched = !strncmp(name, *line, namelen);

	if (matched)
		*line += namelen;

	return matched;
}

static bool
blame_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
{
	struct blame_state *state = view->private;
	struct blame *blame = line->data;

	if (blame->commit) {
		column_data->id = blame->commit->id;
		column_data->author = blame->commit->author;
		column_data->date = &blame->commit->time;
		column_data->author_date = &blame->commit->time;
		if (state->auto_filename_display || get_view_column(view, VIEW_COLUMN_FILE_NAME)->opt.file_name.display == FILENAME_DISPLAY_ALWAYS)
			column_data->file_name = blame->commit->filename;
	} else {
		if (state->auto_filename_display || (get_view_column(view, VIEW_COLUMN_FILE_NAME) && get_view_column(view, VIEW_COLUMN_FILE_NAME)->opt.file_name.display == FILENAME_DISPLAY_ALWAYS))
			column_data->file_name = "";
	}
	column_data->text = blame->text;
	return true;
}

static bool
blame_draw(struct view *view, struct line *line, unsigned int lineno)
{
	return view_columns_draw(view, line, lineno);
}

static bool
check_blame_commit(struct blame *blame, bool check_null_id)
{
	if (!blame->commit)
		report("Commit data not loaded yet");
	else if (check_null_id && string_rev_is_null(blame->commit->id))
		report("No commit exist for the selected line");
	else
		return true;
	return false;
}

static void
setup_blame_parent_line(struct view *view, struct blame *blame)
{
	char from[SIZEOF_REF + SIZEOF_STR];
	char to[SIZEOF_REF + SIZEOF_STR];
	const char *diff_tree_argv[] = {
		"git", "diff", "--no-textconv", "--no-ext-diff", "--no-color",
			"-U0", from, to, "--", NULL
	};
	struct io io;
	int parent_lineno = -1;
	int blamed_lineno = -1;
	char *line;

	if (!string_format(from, "%s:%s", view->env->ref, view->env->file) ||
	    !string_format(to, "%s:%s", blame->commit->id, blame->commit->filename) ||
	    !io_run(&io, IO_RD, NULL, NULL, diff_tree_argv))
		return;

	while ((line = io_get(&io, '\n', true))) {
		if (*line == '@') {
			char *pos = strchr(line, '+');

			parent_lineno = atoi(line + 4);
			if (pos)
				blamed_lineno = atoi(pos + 1);

		} else if (*line == '+' && parent_lineno != -1) {
			if (blame->lineno == blamed_lineno - 1 &&
			    !strcmp(blame->text, line + 1)) {
				view->pos.lineno = parent_lineno ? parent_lineno - 1 : 0;
				break;
			}
			blamed_lineno++;
		}
	}

	io_done(&io);
}

static void
blame_go_forward(struct view *view, struct blame *blame, bool parent)
{
	struct blame_state *state = view->private;
	struct blame_history_state *history_state = &state->history_state;
	const char *id = parent ? blame->commit->parent_id : blame->commit->id;
	const char *filename = parent ? blame->commit->parent_filename : blame->commit->filename;

	if (!*id && parent) {
		report("The selected commit has no parents");
	} else {
		if (!strcmp(history_state->id, id) && !strcmp(history_state->filename, filename)) {
			report("The selected commit is already displayed");
			return;
		}
		if (!push_view_history_state(&blame_view_history, &view->pos, history_state)) {
			report("Failed to save current view state");
			return;
		}

		string_ncopy(view->env->ref, id, sizeof(view->env->ref));
		string_ncopy(view->env->file, filename, strlen(filename));
		if (parent)
			setup_blame_parent_line(view, blame);
		view->env->goto_lineno = blame->lineno;
		reload_view(view);
	}
}

static void
blame_go_back(struct view *view)
{
	struct blame_history_state history_state;

	if (!pop_view_history_state(&blame_view_history, &view->pos, &history_state)) {
		report("Already at start of history");
		return;
	}

	string_copy(view->env->ref, history_state.id);
	string_ncopy(view->env->file, history_state.filename, strlen(history_state.filename));
	view->env->goto_lineno = view->pos.lineno;
	reload_view(view);
}

static enum request
blame_request(struct view *view, enum request request, struct line *line)
{
	enum open_flags flags = view_is_displayed(view) ? OPEN_SPLIT : OPEN_DEFAULT;
	struct blame *blame = line->data;

	switch (request) {
	case REQ_VIEW_BLAME:
	case REQ_PARENT:
		if (!check_blame_commit(blame, request == REQ_VIEW_BLAME))
			break;
		blame_go_forward(view, blame, request == REQ_PARENT);
		break;

	case REQ_BACK:
		blame_go_back(view);
		break;

	case REQ_ENTER:
		if (!check_blame_commit(blame, false))
			break;

		if (view_is_displayed(view_from_request(REQ_VIEW_DIFF)) &&
		    !strcmp(blame->commit->id, view_from_request(REQ_VIEW_DIFF)->ref))
			break;

		if (string_rev_is_null(blame->commit->id)) {
			struct view *diff = view_from_request(REQ_VIEW_DIFF);
			const char *diff_parent_argv[] = {
				"git", "diff", "--encoding=UTF-8", "--no-color", "%(diffargs)", "--", "%(file)", NULL
			};
			const char *diff_no_parent_argv[] = {
				"git", "diff", "--encoding=UTF-8", "--no-color", "%(diffargs)", "--", "%(file)", NULL
			};
			const char **diff_index_argv = *blame->commit->parent_id
				? diff_parent_argv : diff_no_parent_argv;

			open_argv(view, diff, diff_index_argv, NULL, flags);
			if (diff->pipe)
				string_copy_rev(diff->ref, NULL_ID);
		} else {
			open_view(view, view_from_request(REQ_VIEW_DIFF), flags);
		}
		break;

	default:
		return request;
	}

	return REQ_NONE;
}

static void
blame_select(struct view *view, struct line *line)
{
	struct blame *blame = line->data;
	struct blame_commit *commit = blame->commit;

	if (!commit)
		return;

	if (string_rev_is_null(commit->id))
		string_ncopy(view->env->commit, "HEAD", 4);
	else
		string_copy_rev(view->env->commit, commit->id);
	view->env->lineno = line->lineno;
}

static bool
blame_grep(struct view *view, struct line *line)
{
	return view_column_grep(view, line);
}

static struct view_ops blame_ops = {
	"line",
	"%(file)",
	VIEW_SEND_CHILD_ENTER | VIEW_BLAME_LIKE,
	sizeof(struct blame_state),
	blame_open,
	blame_read,
	blame_draw,
	blame_request,
	blame_grep,
	blame_select,
	NULL,
	(1 << VIEW_COLUMN_AUTHOR) | (1 << VIEW_COLUMN_COMMITTER) | (1 << VIEW_COLUMN_DATE) | (1 << VIEW_COLUMN_FILE_NAME) |
	(1 << VIEW_COLUMN_ID) | (1 << VIEW_COLUMN_LINE_NUMBER) | (1 << VIEW_COLUMN_TEXT),
	blame_get_column_data,
};

struct view blame_view = { "blame", &blame_ops, &argv_env };
