			column_data->file_name = blame->commit->filename;
	} else {
		if (state->auto_filename_display || (get_view_column(view, VIEW_COLUMN_FILE_NAME) && get_view_column(view, VIEW_COLUMN_FILE_NAME)->opt.file_name.display == FILENAME_DISPLAY_ALWAYS))
