static bool
blame_open(struct view *view, enum open_flags flags)
{
	struct blame_state *state = view->private;
	const char *blame_argv[] = {
		"git", "blame", "--encoding=UTF-8", "%(blameargs)", "-p",
		*view->env->ref ? "%(ref)" : "-p", "--", "%(file)", NULL
	};
	char path[SIZEOF_STR];

	if (is_initial_view(view) && !state->parsed_args) {
		/* Finish validating and setting up blame options */
		const char **args = get_blame_args();
		const char *file = NULL;
		const char *rev = NULL;
		const char **opts = NULL;
		const char **positional = NULL;
		bool dashdash = false;
		int j;

		state->parsed_args = true;
		for (j = 0; args && args[j]; j++) {
			const char *arg = args[j];

			if (!dashdash && !strcmp(arg, "--")) {
				dashdash = true;
				continue;
			}
			if (dashdash) {
				file = arg;
			} else if (arg[0] == '-') {
				argv_append(&opts, arg);
			} else {
				argv_append(&positional, arg);
			}
		}
		if (positional) {
			size_t n = argv_size(positional);

			if (file) {
				rev = positional[0];
			} else if (n >= 2) {
				rev = positional[0];
				file = positional[1];
			} else {
				file = positional[0];
			}
		}
		if (!file)
			die("No file chosen, press %s to open tree view", get_view_key(view, REQ_VIEW_TREE));
		string_ncopy(view->env->file, file, strlen(file));
		if (rev)
			string_ncopy(view->env->ref, rev, strlen(rev));
		if (opts) {
			argv_free(opt_blame_options);
			free(opt_blame_options);
			opt_blame_options = opts;
		}
	}

	if (!view->env->file[0]) {
		report("No file chosen, press %s to open tree view", get_view_key(view, REQ_VIEW_TREE));
		return false;
	}

	if (!view->prev && *repo.prefix && !(flags & (OPEN_RELOAD | OPEN_REFRESH))) {
		string_copy(path, view->env->file);
		if (!string_format(view->env->file, "%s%s", repo.prefix, path)) {
			report("Failed to setup the blame view");
			return false;
		}
	}

	if (!begin_update(view, repo.cdup, blame_argv, flags))
		return false;

	blame_free_commits(state);
	state->commit = NULL;
	state->auto_filename_display = false;

	if (!(flags & OPEN_RELOAD))
		reset_view_history(&blame_view_history);
	string_copy_rev(state->history_state.id, view->env->ref);
	string_copy(state->history_state.filename, view->env->file);
	string_copy(view->vid, view->env->file);
	string_format(view->ref, "%s ...", view->env->file);

	return true;
}

static struct blame_commit *
get_blame_commit(struct view *view, const char *id)
{
	struct blame_state *state = view->private;
	struct blame_commit *commit;
	struct blame_commit **tmp;
	size_t i;

	for (i = 0; i < state->commits_size; i++)
		if (!strncmp(state->commits[i]->id, id, SIZEOF_REV - 1))
			return state->commits[i];

	commit = calloc(1, sizeof(*commit));
	if (!commit)
		return NULL;
	string_ncopy(commit->id, id, SIZEOF_REV - 1);
	tmp = realloc(state->commits, (state->commits_size + 1) * sizeof(*tmp));
	if (!tmp) {
		free(commit);
		return NULL;
	}
	state->commits = tmp;
	state->commits[state->commits_size++] = commit;
	return commit;
}

bool
match_blame_header(const char *name, char **line)
{
	size_t namelen = strlen(name);
	bool matched = !strncmp(name, *line, namelen);

	if (matched)
		*line += namelen;

	return matched;
}

static bool
blame_read(struct view *view, struct buffer *buf, bool force_stop)
{
	struct blame_state *state = view->private;
	char *line;

	if (!buf) {
		state->auto_filename_display = blame_detect_filename_display(view);
		string_format(view->ref, "%s", view->vid);
		if (view->env->goto_lineno > 0 && view->env->goto_lineno <= view->lines) {
			select_view_line(view, view->env->goto_lineno - 1);
			view->env->goto_lineno = 0;
		}
		if (view_is_displayed(view)) {
			update_view_title(view);
			redraw_view_from(view, 0);
		}
		return true;
	}

	line = buf->data;

	if (*line == '\t') {
		struct blame *blame;
		size_t linelen = buf->size - 1;
		struct line *l = add_line_alloc(view, &blame, LINE_DEFAULT, linelen, false);

		if (!l)
			return false;
		blame->commit = state->commit;
		blame->lineno = state->orig_lineno;
		strncpy(blame->text, line + 1, linelen);
		blame->text[linelen] = 0;
		view_column_info_update(view, l);
		return true;
	}

	if (buf->size > SIZEOF_REV && line[SIZEOF_REV - 1] == ' ' && iscommit((char[]) { 0 }) == false) {
		char id[SIZEOF_REV];
		const char *pos = line + SIZEOF_REV - 1;
		unsigned long orig, final;
		const char *end;
		bool ishex = true;
		int i;

		for (i = 0; i < SIZEOF_REV - 1; i++)
			if (!isxdigit((unsigned char) line[i]))
				ishex = false;

		if (ishex && parse_ulong(&orig, pos + 1, &end) && *end == ' ' && parse_ulong(&final, end + 1, &end)) {
			string_ncopy(id, line, SIZEOF_REV - 1);
			state->commit = get_blame_commit(view, id);
			state->orig_lineno = orig;
			state->author[0] = 0;
			return true;
		}
	}

	if (!state->commit)
		return true;

	if (match_blame_header("author ", &line)) {
		string_ncopy(state->author, line, strlen(line));

	} else if (match_blame_header("author-mail ", &line)) {
		char *end = strchr(line, '>');

		if (end)
			*end = 0;
		if (*line == '<')
			line++;
		state->commit->author = get_author_ident(state->author, line);

	} else if (match_blame_header("author-time ", &line)) {
		parse_timesec(&state->commit->time, line);

	} else if (match_blame_header("author-tz ", &line)) {
		parse_timezone(&state->commit->time, line);

	} else if (match_blame_header("summary ", &line)) {
		string_ncopy(state->commit->title, line, strlen(line));

	} else if (match_blame_header("previous ", &line)) {
		if (strlen(line) > SIZEOF_REV) {
			string_copy_rev(state->commit->parent_id, line);
			line += SIZEOF_REV;
			string_ncopy(state->commit->parent_filename, line, strlen(line));
		}

	} else if (match_blame_header("boundary", &line)) {
		state->commit->boundary = true;

	} else if (match_blame_header("filename ", &line)) {
		string_ncopy(state->commit->filename, line, strlen(line));
	}

	return true;
}

static bool
blame_get_column_data(struct view *view, const struct line *line, struct view_column_data *column_data)
