	struct blame_state *state = view->private;
	struct blame *blame = line->data;
	struct view_column *fcol = get_view_column(view, VIEW_COLUMN_FILE_NAME);
	bool show_file = fcol && (fcol->opt.file_name.display == FILENAME_DISPLAY_ALWAYS ||
