static inline bool
stage_diff_done(struct line *line, struct line *end)
{
	return line >= end ||
	       line->type == LINE_DIFF_CHUNK ||
	       line->type == LINE_DIFF_HEADER;
}

static bool
stage_diff_write(struct io *io, struct line *line, struct line *end)
{
	while (line < end) {
		if (!io_write(io, box_text(line), strlen(box_text(line))) ||
		    !io_write(io, "\n", 1))
			return false;
		line++;
		if (stage_diff_done(line, end))
			break;
	}

	return true;
}

static bool
stage_diff_single_write(struct io *io, bool staged,
			struct line *line, struct line *single, struct line *end)
{
	enum line_type write_as_normal = staged ? LINE_DIFF_ADD : LINE_DIFF_DEL;
	enum line_type ignore = staged ? LINE_DIFF_DEL : LINE_DIFF_ADD;

	while (line < end) {
		const char *prefix = "";
		const char *data = box_text(line);

		if (line == single) {
			/* Write the complete line. */

		} else if (line->type == write_as_normal) {
			prefix = " ";
			data = data + 1;

		} else if (line->type == ignore) {
			data = NULL;
		}

		if (data && !io_printf(io, "%s%s\n", prefix, data))
			return false;

		line++;
		if (stage_diff_done(line, end))
			break;
	}

	return true;
}

static bool
stage_apply_line(struct io *io, struct line *diff_hdr, struct line *chunk, struct line *single, struct line *end)
{
	struct chunk_header header;
	bool staged = stage_line_type == LINE_STAT_STAGED;
	int diff = single->type == LINE_DIFF_DEL ? -1 : 1;

	if (!parse_chunk_header(&header, box_text(chunk)))
		return false;

	if (staged)
		header.old.lines = header.new.lines - diff;
	else
		header.new.lines = header.old.lines + diff;

	return stage_diff_write(io, diff_hdr, chunk) &&
	       io_printf(io, "@@ -%lu,%lu +%lu,%lu @@\n",
		       header.old.position, header.old.lines,
		       header.new.position, header.new.lines) &&
	       stage_diff_single_write(io, staged, chunk + 1, single, end);
}

static bool
stage_apply_chunk(struct view *view, struct line *chunk, struct line *single, bool revert)
{
	const char *apply_argv[SIZEOF_ARG] = {
		"git", "apply", "--whitespace=nowarn", NULL
	};
	struct line *diff_hdr;
	struct io io;
	int argc = 3;

	diff_hdr = find_prev_line_by_type(view, chunk, LINE_DIFF_HEADER);
	if (!diff_hdr)
		return false;

	if (!revert)
		apply_argv[argc++] = "--cached";
	if (revert || stage_line_type == LINE_STAT_STAGED)
		apply_argv[argc++] = "-R";
	apply_argv[argc++] = "-";
	apply_argv[argc++] = NULL;
	if (!io_run(&io, IO_WR, repo.cdup, NULL, apply_argv))
		return false;

	if (single != NULL) {
		if (!stage_apply_line(&io, diff_hdr, chunk, single, view->line + view->lines))
			chunk = NULL;

	} else {
		if (!stage_diff_write(&io, diff_hdr, chunk) ||
		    !stage_diff_write(&io, chunk, view->line + view->lines))
			chunk = NULL;
	}

	io_done(&io);

	return chunk ? true : false;
}

static bool
stage_update_files(struct view *view, enum line_type type)
{
	struct line *line;

	for (line = view->line; view_has_line(view, line); line++)
		;
	return status_update_file(view, &stage_status, type);
}

static bool
stage_update(struct view *view, struct line *line, bool single)
{
	struct line *chunk = NULL;

	if (!is_initial_commit() && stage_line_type != LINE_STAT_UNTRACKED)
		chunk = find_prev_line_by_type(view, line, LINE_DIFF_CHUNK);

	if (chunk) {
		if (!stage_apply_chunk(view, chunk, single ? line : NULL, false)) {
			report("Failed to apply chunk");
			return false;
		}

	} else if (!stage_status.status) {
		view = view->parent;

		for (line = view->line; view_has_line(view, line); line++)
			if (line->type == stage_line_type)
				break;

		if (!status_update_file(view, &stage_status, stage_line_type)) {
			report("Failed to update files");
			return false;
		}

	} else if (!status_update_file(view, &stage_status, stage_line_type)) {
		report("Failed to update file");
		return false;
	}

	return true;
}

static bool
stage_revert(struct view *view, struct line *line)
{
	struct line *chunk = NULL;

	if (!is_initial_commit() && stage_line_type == LINE_STAT_UNSTAGED)
		chunk = find_prev_line_by_type(view, line, LINE_DIFF_CHUNK);

	if (chunk) {
		if (!prompt_yesno("Are you sure you want to revert changes?"))
			return false;

		if (!stage_apply_chunk(view, chunk, NULL, true)) {
			report("Failed to revert chunk");
			return false;
		}
		return true;

	} else {
		return status_revert_dummy(&stage_status, stage_line_type, false);
	}
}

bool
status_revert_dummy(struct status *status, enum line_type type, bool has_none)
{
	if (!status || type != LINE_STAT_UNSTAGED) {
		if (type == LINE_STAT_STAGED)
			report("Cannot revert changes to staged files");
		else if (type == LINE_STAT_UNTRACKED)
			report("Cannot revert changes to untracked files");
		else
			report("Cannot revert changes to multiple files");
		return false;
	}

	if (prompt_yesno("Are you sure you want to revert changes?")) {
		const char *checkout_argv[] = {
			"git", "checkout", "--", status->old.name, NULL
		};

		return io_run_fg(checkout_argv, repo.cdup);
	}
	return false;
}

static void
stage_next(struct view *view, struct line *line)
{
	struct stage_state *state = view->private;
	int i;

	if (!state->chunks) {
		for (line = view->line; view_has_line(view, line); line++) {
			if (line->type != LINE_DIFF_CHUNK)
				continue;

			if (!realloc_ints(&state->chunk, state->chunks, 1)) {
				report("Allocation failure");
				return;
			}

			state->chunk[state->chunks++] = line - view->line;
		}
	}

	for (i = 0; i < state->chunks; i++) {
		if (state->chunk[i] > view->pos.lineno) {
			do_scroll_view(view, state->chunk[i] - view->pos.lineno);
			report("Chunk %d of %zd", i + 1, state->chunks);
			return;
		}
	}

	report("No next chunk found");
}

bool
realloc_ints(int **ints, size_t size, size_t extra)
{
	int *tmp = realloc(*ints, (size + extra) * sizeof(**ints));

	if (!tmp)
		return false;
	*ints = tmp;
	return true;
}

static struct line *
stage_insert_chunk(struct view *view, struct chunk_header *header,
		   struct line *from, struct line *to, struct line *last_unchanged_line)
{
	char buf[SIZEOF_STR];
	char *chunk_line;
	unsigned long from_lineno = last_unchanged_line - view->line;
	unsigned long to_lineno = to - view->line;
	unsigned long after_lineno = to_lineno;

	if (!string_format(buf, "@@ -%lu,%lu +%lu,%lu @@",
			header->old.position, header->old.lines,
			header->new.position, header->new.lines))
		return NULL;

	chunk_line = strdup(buf);
	if (!chunk_line)
		return NULL;

	free(from->data);
	{
		struct box *box = calloc(1, sizeof(*box) + sizeof(struct box_cell) + strlen(chunk_line) + 1);

		if (!box)
			return NULL;
		box->text = (char *) &box->cell[2];
		strcpy((char *) box->text, chunk_line);
		box->cells = 1;
		box->cell[0].type = LINE_DIFF_CHUNK;
		box->cell[0].length = strlen(chunk_line);
		from->data = box;
		free(chunk_line);
	}

	if (!to)
		return from;

	if (!add_line_at(view, after_lineno++, buf, LINE_DIFF_CHUNK, strlen(buf) + 1, false))
		return NULL;

	while (from_lineno < to_lineno) {
		struct line *line = &view->line[from_lineno++];

		if (!add_line_at(view, after_lineno++, box_text(line), line->type, strlen(box_text(line)) + 1, false))
			return NULL;
	}

	return view->line + after_lineno;
}

static void
stage_split_chunk(struct view *view, struct line *chunk_start)
{
	report("Splitting chunks is not supported");
	(void) stage_insert_chunk;
}

static enum request
stage_request(struct view *view, enum request request, struct line *line)
{
	switch (request) {
	case REQ_STATUS_UPDATE:
		if (!stage_update(view, line, false))
			return REQ_NONE;
		break;

	case REQ_STATUS_REVERT:
		if (!stage_revert(view, line))
			return REQ_NONE;
		break;

	case REQ_STAGE_UPDATE_LINE:
		if (stage_line_type == LINE_STAT_UNTRACKED ||
		    stage_status.status == 'A') {
			report("Staging single lines is not supported for new files");
			return REQ_NONE;
		}
		if (line->type != LINE_DIFF_DEL && line->type != LINE_DIFF_ADD) {
			report("Please select a change to stage");
			return REQ_NONE;
		}
		if (!stage_update(view, line, true))
			return REQ_NONE;
		break;

	case REQ_STAGE_UPDATE_PART:
		report("Staging part of a chunk is not supported");
		return REQ_NONE;

	case REQ_STAGE_SPLIT_CHUNK:
		if (stage_line_type == LINE_STAT_UNTRACKED ||
		    !(line = find_prev_line_by_type(view, line, LINE_DIFF_CHUNK))) {
			report("No chunk to split");
			return REQ_NONE;
		}
		stage_split_chunk(view, line);
		return REQ_NONE;

	case REQ_EDIT:
		if (!stage_status.new.name[0])
			return diff_common_edit(view, request, line) ? REQ_NONE : request;

		if (stage_status.status == 'D') {
			report("File has been deleted.");
			return REQ_NONE;
		}

		if (stage_line_type == LINE_STAT_UNTRACKED) {
			open_editor(stage_status.new.name, (line - view->line) + 1);
		} else {
			open_editor(stage_status.new.name, diff_get_lineno(view, line, false));
		}
		break;

	case REQ_REFRESH:
		/* Reload everything(including current branch information) ... */
		load_refs(true);
		break;

	case REQ_VIEW_BLAME:
		if (stage_line_type == LINE_STAT_UNTRACKED) {
			report("Nothing to blame here");
			return REQ_NONE;
		}
		if (stage_status.new.name[0]) {
			string_copy(view->env->file, stage_status.new.name);
			view->env->ref[0] = 0;
		}
		return request;

	case REQ_ENTER:
		return diff_common_enter(view, request, line);

	default:
		return request;
	}

	refresh_view(view->parent ? view->parent : view);

	/* Check whether the staged entry still exists, and close the
	 * stage view if it doesn't. */
	if (view->parent && !status_exists(view->parent, &stage_status, stage_line_type)) {
		maximize_view(view->parent, true);
		return REQ_NONE;
	}

	if (stage_line_type == LINE_STAT_UNTRACKED) {
		if (access(stage_status.new.name, R_OK)) {
			report("File is no longer in the untracked state");
			if (view->parent)
				maximize_view(view->parent, true);
			return REQ_NONE;
		}
	}

	refresh_view(view);

	return REQ_NONE;
}

static bool
stage_open(struct view *view, enum open_flags flags)
{
	const char *no_head_diff_argv[] = {
		"git", "diff", "--encoding=UTF-8", "--no-color", "--patch-with-stat", "%(stat-width)",
			"%(diffargs)", "--word-diff=none", "--", "%(file)", NULL
	};
	const char *index_show_argv[] = {
		"git", "diff-index", "--encoding=UTF-8", "--textconv", "--patch-with-stat", "%(stat-width)",
			"-C", "--cached", "--diff-filter=ACDMRTXB", "%(diffargs)", "--word-diff=none", "HEAD", "--",
			"%(file)", "%(file_old)", NULL
	};
	const char *files_show_argv[] = {
		"git", "diff-files", "--encoding=UTF-8", "--textconv", "--patch-with-stat", "%(stat-width)",
			"-C", "%(diffargs)", "--word-diff=none", "--", "%(file)", "%(file_old)", NULL
	};
	/* Diffs for unmerged entries are empty when passing the new
	 * path, so leave out the new path. */
	const char *files_unmerged_argv[] = {
		"git", "diff-files", "--encoding=UTF-8", "--textconv", "--patch-with-stat", "%(stat-width)",
			"-C", "%(diffargs)", "--word-diff=none", "--", "%(file_old)", NULL
	};
	static const char *file_argv[] = { repo.cdup, "%(file)", NULL };
	const char **argv = NULL;
	struct stage_state *state = view->private;
	char stat_width[32];
	const char *tmp_argv[SIZEOF_ARGV + 4];
	int i, argc = 0;

	if (!stage_line_type) {
		report("No stage content, press %s to open the status view and choose file",
			get_view_key(view, REQ_VIEW_STATUS));
		return false;
	}

	view->encoding = NULL;

	switch (stage_line_type) {
	case LINE_STAT_STAGED:
		watch_register(NULL, 0);
		if (is_initial_commit()) {
			argv = no_head_diff_argv;
		} else {
			argv = index_show_argv;
		}
		break;

	case LINE_STAT_UNSTAGED:
		if (stage_status.status != 'U')
			argv = files_show_argv;
		else
			argv = files_unmerged_argv;
		break;

	case LINE_STAT_UNTRACKED:
		argv = file_argv;
		break;

	case LINE_HEADER:
	default:
		die("line type %d not handled in switch", stage_line_type);
	}

	if (!status_stage_info_(view->ref, sizeof(view->ref), stage_line_type, &stage_status)
		|| !argv_copy(&view->argv, argv)) {
		report("Failed to open staged view");
		return false;
	}

	if (stage_line_type != LINE_STAT_UNTRACKED)
		memset(&state->diff, 0, sizeof(state->diff));
	free(state->chunk);
	state->chunk = NULL;
	state->chunks = 0;

	string_format(stat_width, "--stat=%d", view->width ? view->width : COLS);
	for (i = 0; argv[i] && argc < SIZEOF_ARGV; i++) {
		if (!strcmp(argv[i], "%(stat-width)"))
			tmp_argv[argc++] = stat_width;
		else if (!strcmp(argv[i], "%(file_old)")) {
			if (*stage_status.old.name && strcmp(stage_status.old.name, stage_status.new.name) == 0)
				tmp_argv[argc++] = argv[i];
			else if (*stage_status.old.name)
				tmp_argv[argc++] = argv[i];
			else
				tmp_argv[argc++] = "%(file)";
		} else
			tmp_argv[argc++] = argv[i];
	}
	tmp_argv[argc] = NULL;

	view->vid[0] = 0;
	view->dir = repo.cdup;
	if (stage_line_type == LINE_STAT_UNTRACKED) {
		char path[SIZEOF_STR];
		struct io io;

		string_format(path, "%s%s", repo.cdup, stage_status.new.name);
		reset_view(view);
		string_ncopy(view->vid, view->ops->id, strlen(view->ops->id));
		if (!io_open(&io, "%s", path)) {
			report("Failed to open file");
			return false;
		}
		view->io = io;
		view->pipe = &view->io;
		view->start_time = time(NULL);
		if (!(flags & (OPEN_RELOAD | OPEN_REFRESH)))
			view->env->file[0] = 0;
		string_copy(view->env->file, stage_status.new.name);
		return true;
	}
	return begin_update(view, repo.cdup, tmp_argv, flags);
}

void
watch_register(void *w, int flags)
{
}

static bool
stage_read(struct view *view, struct buffer *buf, bool force_stop)
{
	struct stage_state *state = view->private;

	if (stage_line_type == LINE_STAT_UNTRACKED)
		return pager_read(view, buf, force_stop);

	if (buf && diff_common_read(view, buf->data, &state->diff))
		return true;

	return pager_read(view, buf, force_stop);
}

static void
stage_select(struct view *view, struct line *line)
{
	diff_common_select(view, line, stage_line_type == LINE_STAT_STAGED ? "Staged changes" :
				       stage_line_type == LINE_STAT_UNSTAGED ? "Unstaged changes" : NULL);
	if (stage_line_type == LINE_STAT_UNTRACKED) {
		string_format(view->ref, "Untracked file %s", stage_status.new.name);
		string_copy(view->env->file, stage_status.new.name);
		view->env->lineno = view->pos.lineno + 1;
	} else if (line->type == LINE_DIFF_STAT) {
		/* ref set by diff_common_select */
	} else {
		const char *file = diff_get_pathname(view, line, false);

		if (!file)
			status_stage_info_(view->ref, sizeof(view->ref), stage_line_type, &stage_status);
	}
}

static struct view_ops stage_ops = {
	"line",
	"",
	VIEW_DIFF_LIKE | VIEW_REFRESH,
	sizeof(struct stage_state),
	stage_open,
	stage_read,
	view_columns_draw_wrap,
	stage_request,
	pager_common_grep,
	stage_select,
	NULL,
	(1 << VIEW_COLUMN_LINE_NUMBER) | (1 << VIEW_COLUMN_TEXT),
	pager_get_column_data,
};

struct view stage_view = { "stage", &stage_ops, &argv_env };

void
open_stage_view(struct view *prev, void *status, enum line_type type, enum open_flags flags)
{
	if (type) {
		stage_line_type = type;
		if (status)
			stage_status = *(struct status *) status;
		else
			memset(&stage_status, 0, sizeof(stage_status));
	}

	open_view(prev, &stage_view, flags);
}
