static bool
grep_prompt(void)
{
	const char *argv[SIZEOF_ARGV + 2];
	int argc = 0;
	char *text = read_prompt("grep: ");

	if (!text || !*text)
		return false;
	argv[0] = NULL;
	if (!argv_from_string(argv, &argc, text))
		return false;
	argv_free(grep_argv);
	free(grep_argv);
	grep_argv = NULL;
	return argv_append_array(&grep_argv, argv);
}

static enum request
grep_request(struct view *view, enum request request, struct line *line)
{
	struct grep_state *state = view->private;
	struct grep_line *grep = grep_get_line(line);
	struct view *file_view = view_from_request(REQ_VIEW_BLOB);

	switch (request) {
	case REQ_REFRESH:
		refresh_view(view);
		return REQ_NONE;

	case REQ_ENTER:
		if (!*grep->file)
			return REQ_NONE;
		if (file_view->parent == view && file_view->prev == view &&
		    view_is_displayed(file_view) && !strcmp(grep->file, file_view->env->file)) {
			if (*grep->text) {
				select_view_line(file_view, grep->lineno - 1);
				update_view_title(file_view);
			}
		} else {
			const char *file_argv[] = { repo.cdup, grep->file, NULL };

			clear_position(&file_view->pos);
			view->env->goto_lineno = grep->lineno;
			view->env->blob[0] = 0;
			string_ncopy(view->env->file, grep->file, strlen(grep->file));
			open_argv(view, file_view, file_argv, repo.cdup, OPEN_SPLIT | OPEN_RELOAD);
		}
		return REQ_NONE;

	case REQ_EDIT:
		if (!*grep->file)
			return request;
		open_editor(grep->file, grep->lineno);
		return REQ_NONE;

	case REQ_VIEW_BLAME:
		view->env->ref[0] = 0;
		view->env->goto_lineno = grep->lineno;
		return request;

	case REQ_VIEW_GREP:
		if (!grep_prompt())
			return REQ_NONE;
		(void) state;
		refresh_view(view);
		return REQ_NONE;

	default:
		return request;
	}
}

static bool
grep_open(struct view *view, enum open_flags flags)
{
	const char **argv = NULL;

	if (is_initial_view(view) && !grep_argv) {
		const char **args = get_grep_args();

		if (args)
			argv_copy(&grep_argv, args);
		else
			grep_argv = NULL;
	}

	if (!grep_argv && !grep_prompt())
		return false;

	if (!argv_append_array(&argv, grep_args) ||
	    (grep_argv && !argv_append_array(&argv, grep_argv)))
		return false;

	{
		bool ok = begin_update(view, NULL, argv, flags);

		argv_free(argv);
		free(argv);
		return ok;
	}
}

static bool
grep_read(struct view *view, struct buffer *buf, bool force_stop)
{
	struct grep_state *state = view->private;
	struct grep_line *grep;
	char *lineno, *text;
	struct line *line;
	const char *file;
	size_t textlen;

	if (!buf) {
		state->last_file = NULL;
		return true;
	}

	if (!*buf->data)
		return true;

	if (!strcmp(buf->data, "--")) {
		add_line_nodata(view, LINE_DELIMITER);
		return true;
	}

	lineno = io_memchr(buf, buf->data, 0);
	text = io_memchr(buf, lineno, 0);

	if (!lineno || !text)
		return false;

	if (!state->last_file || strcmp(state->last_file, buf->data)) {
		struct line *fline = add_line_text(view, buf->data, LINE_FILE);

		if (!fline)
			return false;
		state->last_file = box_text(fline);
	}

	file = state->last_file;
	textlen = strlen(text);

	line = add_line_alloc(view, &grep, LINE_DEFAULT, textlen, false);
	if (!line)
		return false;

	grep->file = file;
	grep->lineno = atoi(lineno);
	strncpy(grep->text, text, textlen);
	grep->text[textlen] = 0;
	view_column_info_update(view, line);

	return true;
}

char *
io_memchr(struct buffer *buf, char *data, int c)
{
	char *pos;

	if (data < buf->data || data >= buf->data + buf->size)
		return NULL;
	pos = memchr(data, c, buf->size - (data - buf->data) - 1);
	return pos ? pos + 1 : NULL;
}

static bool
grep_grep(struct view *view, struct line *line)
{
	struct grep_line *grep = grep_get_line(line);
	const char *text[] = { grep->text, NULL };

	return grep_text(view, text);
}

