	{
		const struct ref *ref = reference->ref;
		const char *all_references_argv[] = {
			"git", "log", "--encoding=UTF-8", "%(commit-order)", "%(cmdlineargs)", "%(revargs)",
			"--date=raw", "--parents", "--no-color", "%(notes)",
			"--pretty=format:commit %m %H %P%x00%aN <%aE> %ad%x00%cN <%cE> %cd%x00%s%x00%N%x03",
			refs_is_all(reference) ? "--all" : ref->name, "--", "%(fileargs)", NULL
		};
		struct view *main_view = view_from_request(REQ_VIEW_MAIN);

		(void) all_references_argv;
		if (refs_is_all(reference)) {
			argv_free(opt_rev_args);
			free(opt_rev_args);
			opt_rev_args = NULL;
			argv_append(&opt_rev_args, "--all");
		} else {
			argv_free(opt_rev_args);
			free(opt_rev_args);
			opt_rev_args = NULL;
			argv_append(&opt_rev_args, ref->name);
		}
		open_view(view, main_view, OPEN_SPLIT | OPEN_RELOAD);
		return REQ_NONE;
	}
	default:
		return request;
	}
}

static bool
refs_read(struct view *view, struct buffer *buf, bool force_stop)
{
	char *author;
	char *title;
	char *committer;
	struct line *line;
	char *id;

	if (!buf)
		return true;

	id = buf->data;
	author = io_memchr(buf, id, 0);
	committer = io_memchr(buf, author, 0);
	title = io_memchr(buf, committer, 0);
	if (!author || !committer || !title)
		return true;

	for (line = &view->line[1]; view_has_line(view, line); line++) {
		struct reference *reference = line->data;

		if (strcmp(reference->id, id))
			continue;

		{
			const char *name;
			char *lt = strchr(author, '<');
			char *gt = strchr(author, '>');
			char email[SIZEOF_STR] = "";
			char ident[SIZEOF_STR];

			string_ncopy(ident, author, strlen(author));
			if (lt && gt && gt > lt)
				string_ncopy(email, lt + 1, gt - lt - 1);
			parse_author_line(ident, &name, &reference->time);
			reference->author = get_author_ident(name, email);
		}
		string_expand(reference->title, sizeof(reference->title), title, -1, 1);

		view_column_info_update(view, line);
		line->dirty = true;
	}

	return true;
}

static bool
refs_open_visitor(void *data, const struct ref *ref)
{
	struct view *view = data;
	struct reference *reference;
	bool is_all = ref == &refs_all;
	struct line *line;

	if (ref->type == REFERENCE_STASH || ref->type == REFERENCE_NOTE || ref->type == REFERENCE_REPLACE ||
	    ref->type == REFERENCE_PREFETCH)
		return true;
	if (!is_all && opt_cmdline_args) {
		bool branches = argv_contains(opt_cmdline_args, "--branches");
		bool tags = argv_contains(opt_cmdline_args, "--tags");
		bool remotes = argv_contains(opt_cmdline_args, "--remotes");

		if (branches || tags || remotes) {
			bool ok = false;

			if (branches && (ref->type == REFERENCE_BRANCH || ref->type == REFERENCE_HEAD))
				ok = true;
			if (tags && ref_is_tag(ref))
				ok = true;
			if (remotes && ref_is_remote(ref))
				ok = true;
			if (!ok)
				return true;
		}
	}

	line = add_line_alloc(view, &reference, LINE_DEFAULT, 0, is_all);
	if (!line)
		return false;

	reference->ref = ref;
	string_copy_rev(reference->id, ref->id);
	view_column_info_update(view, line);

	return true;
}

static int
refs_sort_cmp(const void *a, const void *b)
{
	const struct line *l1 = a, *l2 = b;
	const struct reference *r1 = l1->data, *r2 = l2->data;

	return ref_compare(r1->ref, r2->ref);
}

static bool
refs_open(struct view *view, enum open_flags flags)
{
	const char *refs_log[] = {
		"git", "log", "--encoding=UTF-8", "--no-color", "--date=raw",
			"--pretty=format:%H%x00%aN <%aE> %ad%x00%cN <%cE> %cd%x00%s",
			"--all", "--decorate-refs=", "--simplify-by-decoration", NULL
	};

	if (!begin_update(view, NULL, refs_log, flags))
		return false;

	refs_open_visitor(view, &refs_all);
	foreach_ref(refs_open_visitor, view);

	if (view->lines > 1) {
		qsort(view->line + 1, view->lines - 1, sizeof(*view->line), refs_sort_cmp);
		{
			size_t i;

			for (i = 0; i < view->lines; i++)
				view->line[i].lineno = i + 1;
		}
	}

	return true;
}

static void
refs_select(struct view *view, struct line *line)
{
	struct reference *reference = line->data;

	if (refs_is_all(reference)) {
		string_copy(view->ref, "All references");
		return;
	}
	string_copy_rev(view->ref, reference->id);
	string_copy_rev(view->env->commit, reference->id);
	{
		const struct ref *ref = reference->ref;

		view->env->branch[0] = 0;
		view->env->tag[0] = 0;
		view->env->remote[0] = 0;
		string_ncopy(view->env->refname, ref->name, strlen(ref->name));
		if (ref->type == REFERENCE_HEAD || ref->type == REFERENCE_BRANCH) {
			string_ncopy(view->env->branch, ref->name, strlen(ref->name));
		} else if (ref_is_tag(ref)) {
			string_ncopy(view->env->tag, ref->name, strlen(ref->name));
		} else if (ref_is_remote(ref)) {
			const char *sep = strchr(ref->name, '/');

			if (sep) {
				string_ncopy(view->env->remote, ref->name, sep - ref->name);
				string_ncopy(view->env->branch, sep + 1, strlen(sep + 1));
			}
		}
	}
}

