	(1 << VIEW_COLUMN_LINE_NUMBER) | (1 << VIEW_COLUMN_COMMIT_TITLE) | (1 << VIEW_COLUMN_REF),
	refs_get_column_data,
};

struct view refs_view = { "refs", &refs_ops, &argv_env };
