new='''static void
save_window_line(WINDOW *win, int row, int width, char *buf, size_t bufsize)
{
	int col;
	int len = 0;

	for (col = 0; col < width && len < bufsize - 8; col++) {
		cchar_t cc;
		wchar_t wch[CCHARW_MAX];
		attr_t attrs;
		short pair;

		if (mvwin_wch(win, row, col, &cc) == ERR) {
			buf[len++] = ' ';
			continue;
		}
		if (getcchar(&cc, wch, &attrs, &pair, NULL) == ERR) {
			buf[len++] = ' ';
			continue;
		}
		if (attrs & A_ALTCHARSET) {
			/* ACS character: output the raw code */
			char c = (char) (wch[0] & 0x7f);
			buf[len++] = c ? c : ' ';
			continue;
		}
		if (wch[0] == 0) {
			buf[len++] = ' ';
			continue;
		}
		{
			char mb[MB_LEN_MAX + 1];
			int n;
			int k;

			for (k = 0; k < CCHARW_MAX && wch[k]; k++) {
				n = wctomb(mb, wch[k]);
				if (n <= 0) {
					buf[len++] = '?';
				} else {
					memcpy(buf + len, mb, n);
					len += n;
				}
			}
			/* Skip the continuation cells of wide characters */
			{
				int w = wcwidth(wch[0]);
				if (w > 1)
					col += w - 1;
			}
		}
	}
	buf[len] = 0;
}

void
save_display(const char *path)
{
	int fd = open(path, O_WRONLY | O_CREAT | O_EXCL, 0666);
	FILE *file;
	char *buf, *tmp;
	size_t bufsize = SIZEOF_STR * 16;
	int row;
	int y, x;
	int i;

	if (fd < 0)
		return;
	file = fdopen(fd, "w");
	if (!file) {
		close(fd);
		return;
	}
	buf = malloc(bufsize);
	tmp = malloc(bufsize);

	getmaxyx(stdscr, y, x);

	/* Render each row of the screen by combining the view windows. */
	for (row = 0; row < y - 1; row++) {
		char *line = buf;
		size_t pos = 0;
		struct view *view;
		int col = 0;

		line[0] = 0;
		foreach_displayed_view (view, i) {
			int begy, begx;
			int vrow;

			getbegyx(view->win, begy, begx);
			if (col < begx) {
				/* separator between views */
				string_nformat(line, bufsize, &pos, "%*s", begx - col - 1, "");
				string_nformat(line, bufsize, &pos, "|");
				col = begx;
			}
			vrow = row - begy;
			if (vrow >= 0 && vrow < view->height) {
				save_window_line(view->win, vrow, view->width, tmp, bufsize);
				string_nformat(line, bufsize, &pos, "%s", tmp);
				col += view->width;
			} else if (vrow == view->height) {
				save_window_line(view->title, 0, view->width, tmp, bufsize);
				string_nformat(line, bufsize, &pos, "%s", tmp);
				col += view->width;
			} else {
				string_nformat(line, bufsize, &pos, "%*s", view->width, "");
				col += view->width;
			}
		}
		/* Trim trailing whitespace, keep at least one char */
		while (pos > 1 && line[pos - 1] == ' ')
			line[--pos] = 0;
		fprintf(file, "%s\\n", line);
	}

	free(buf);
	free(tmp);
	fclose(file);
}

